/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Design principles:
 *  - Key VALUES are never logged, stored in memory beyond immediate need,
 *    or exposed in any output (logs, errors, stack traces, return values).
 *  - Only key NAMES and rotation metadata (timestamps, success/failure) are
 *    written to rotation-log.json.
 *  - The .env.test file is updated atomically: write to .env.test.tmp first,
 *    then rename over .env.test so a crash mid-write never corrupts the file.
 *  - Only the two key names discovered in .env.test
 *    (ANTHROPIC_API_KEY, STRIPE_SECRET_KEY) are eligible for rotation.
 *    Attempting to rotate anything else is rejected.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const os   = require('os');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Allowed key names (read once at module load) ─────────────────────────────

/**
 * Parse a .env file and return the Set of variable *names* whose values look
 * like API keys.  A line is considered an API-key entry when it is a
 * non-comment assignment whose name ends with _KEY or _TOKEN or _SECRET*.
 *
 * The VALUES are intentionally discarded immediately after the match; they
 * are never stored or returned.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {Set<string>}    Set of eligible key names.
 */
function readEligibleKeyNames(filePath) {
  const eligible = new Set();

  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    throw new Error(`key-rotation: cannot read env file "${filePath}": ${err.message}`);
  }

  for (const line of raw.split(/\r?\n/)) {
    const trimmed = line.trim();

    // Skip comments and empty lines.
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Match:  VARNAME=<anything>
    // Capture group 1 = name only; value is intentionally not captured.
    const match = trimmed.match(/^([A-Z][A-Z0-9_]*)=/);
    if (!match) continue;

    const name = match[1]; // e.g. "ANTHROPIC_API_KEY"

    // Only track names that are clearly API / secret keys.
    if (/(_KEY|_SECRET(_KEY)?|_TOKEN)$/.test(name)) {
      eligible.add(name);
    }
  }

  return eligible;
}

// Discover eligible names at module load time.
const ELIGIBLE_KEY_NAMES = readEligibleKeyNames(ENV_FILE);

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Generate a new placeholder value for a rotated key.
 *
 * Format:  ROTATED-<keyName>-<timestamp>-<random-hex>
 *
 * This is a *placeholder* suitable for test / canary environments.  In a
 * production rotation workflow this function would call the upstream provider
 * API (Anthropic, Stripe …) and receive a real credential; the provider call
 * and the returned secret would live entirely inside this function and never
 * be surfaced to callers or logs.
 *
 * @param {string} keyName  The variable name being rotated (used as a label
 *                          only — never the old value).
 * @returns {string}        New placeholder value.
 */
function generatePlaceholder(keyName) {
  const timestamp = Date.now();
  // 16 random bytes → 32 hex chars.
  const randomPart = Array.from(
    { length: 16 },
    () => Math.floor(Math.random() * 256).toString(16).padStart(2, '0')
  ).join('');
  return `ROTATED-${keyName}-${timestamp}-${randomPart}`;
}

// ─── Atomic .env updater ──────────────────────────────────────────────────────

/**
 * Read .env.test, replace the value for `keyName` with `newPlaceholder`,
 * and write back atomically (tmp → rename).
 *
 * The old value is read line-by-line and overwritten immediately; it is never
 * held in a variable that outlives this function.
 *
 * @param {string} keyName         Variable name to update.
 * @param {string} newPlaceholder  The new (placeholder) value.
 */
function updateEnvFileAtomic(keyName, newPlaceholder) {
  // Read current file content.
  let content;
  try {
    content = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    throw new Error(`key-rotation: cannot read "${ENV_FILE}" for update: ${err.message}`);
  }

  let found = false;
  const updatedLines = content.split(/\r?\n/).map((line) => {
    // Match the exact variable name at the start of the line.
    // The regex captures name and equals sign; the old value (after =) is
    // consumed by the replace and immediately discarded.
    if (new RegExp(`^${keyName}=`).test(line)) {
      found = true;
      return `${keyName}=${newPlaceholder}`;
    }
    return line;
  });

  if (!found) {
    throw new Error(
      `key-rotation: variable "${keyName}" not found in "${ENV_FILE}"`
    );
  }

  const updatedContent = updatedLines.join(os.EOL);

  // ── Atomic write: tmp → rename ──────────────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, updatedContent, { encoding: 'utf8', flag: 'w' });
  } catch (err) {
    throw new Error(
      `key-rotation: cannot write tmp file "${ENV_TMP_FILE}": ${err.message}`
    );
  }

  try {
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (err) {
    // Best-effort cleanup of the tmp file before re-throwing.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch (_) { /* ignore */ }
    throw new Error(
      `key-rotation: atomic rename from "${ENV_TMP_FILE}" to "${ENV_FILE}" failed: ${err.message}`
    );
  }
}

// ─── Rotation log ─────────────────────────────────────────────────────────────

/**
 * Append a rotation event to rotation-log.json.
 *
 * Each entry records ONLY:
 *   - timestamp  (ISO-8601 string)
 *   - keyName    (variable name, e.g. "ANTHROPIC_API_KEY")
 *   - status     ("success" | "failure")
 *   - reason     (human-readable note; MUST NOT contain key values)
 *
 * The log file holds a top-level JSON array; entries are appended by reading
 * the existing array (or starting a new one), pushing the new entry, and
 * rewriting the file.  The file itself never contains key values.
 *
 * @param {object} entry
 * @param {string} entry.keyName
 * @param {'success'|'failure'} entry.status
 * @param {string} [entry.reason]
 */
function appendRotationLog({ keyName, status, reason = '' }) {
  // ── Safety guard: ensure no accidental value leakage in reason ──────────
  // Any string that resembles a real key format (long alphanum with dashes)
  // beyond a short length is stripped out as a precaution.
  const safeReason = reason.replace(/[A-Za-z0-9_\-]{32,}/g, '[REDACTED]');

  const entry = {
    timestamp: new Date().toISOString(),
    keyName,           // only the NAME, never the value
    status,
    reason: safeReason,
  };

  let entries = [];

  // Read existing log if present.
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8').trim();
      if (raw) {
        entries = JSON.parse(raw);
        if (!Array.isArray(entries)) {
          // Malformed file — start fresh rather than crashing.
          entries = [];
        }
      }
    } catch (_) {
      // Malformed JSON — start fresh.
      entries = [];
    }
  }

  entries.push(entry);

  try {
    fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
  } catch (err) {
    // Log write failure is non-fatal for the rotation itself, but we surface
    // it as a console warning (key names only — no values).
    console.warn(
      `key-rotation: WARNING — could not write rotation log for key "${keyName}": ${err.message}`
    );
  }
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotate a single API key by name.
 *
 * Steps:
 *  1. Validate that `keyName` is in the set of eligible names discovered
 *     from .env.test.  Unknown names are rejected to prevent unintended
 *     modifications.
 *  2. Generate a new placeholder value (in production: call the provider API).
 *  3. Atomically update .env.test with the new placeholder.
 *  4. Append a success entry to rotation-log.json.
 *
 * On any failure the error is logged (key name only) and re-thrown so the
 * caller can take corrective action.
 *
 * @param {string} keyName  The environment variable name to rotate,
 *                          e.g. "ANTHROPIC_API_KEY".
 * @returns {{ keyName: string, rotatedAt: string }}
 *          Confirmation object containing the key NAME and ISO timestamp.
 *          The new key value is intentionally NOT returned.
 *
 * @throws {Error} If keyName is not eligible, or if file I/O fails.
 */
function rotateKey(keyName) {
  if (typeof keyName !== 'string' || !keyName) {
    const msg = 'key-rotation: rotateKey() requires a non-empty string keyName.';
    appendRotationLog({ keyName: String(keyName), status: 'failure', reason: msg });
    throw new Error(msg);
  }

  // ── 1. Eligibility check ──────────────────────────────────────────────────
  if (!ELIGIBLE_KEY_NAMES.has(keyName)) {
    const msg =
      `key-rotation: "${keyName}" is not an eligible key. ` +
      `Eligible keys: [${[...ELIGIBLE_KEY_NAMES].join(', ')}].`;
    appendRotationLog({ keyName, status: 'failure', reason: msg });
    throw new Error(msg);
  }

  // ── 2. Generate new placeholder ───────────────────────────────────────────
  const newPlaceholder = generatePlaceholder(keyName);
  // newPlaceholder is used immediately below and is never logged.

  // ── 3. Atomic file update ─────────────────────────────────────────────────
  try {
    updateEnvFileAtomic(keyName, newPlaceholder);
  } catch (err) {
    appendRotationLog({
      keyName,
      status: 'failure',
      reason: `File update failed: ${err.message}`,
    });
    throw err;
  }

  // ── 4. Log success (key name + timestamp only) ────────────────────────────
  const rotatedAt = new Date().toISOString();
  appendRotationLog({
    keyName,
    status: 'success',
    reason: `Key rotated successfully at ${rotatedAt}`,
  });

  console.log(`[key-rotation] Rotated "${keyName}" at ${rotatedAt}`);

  // Return metadata only — never the new value.
  return { keyName, rotatedAt };
}

/**
 * Return the set of key names that are eligible for rotation.
 * Useful for callers that need to enumerate rotatable keys without
 * inspecting the .env file directly.
 *
 * @returns {string[]}  Array of eligible variable names.
 */
function getEligibleKeyNames() {
  return [...ELIGIBLE_KEY_NAMES];
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, getEligibleKeyNames };

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Uses Node's built-in `assert` and no external test runner so it can be
 * executed with:  node key-rotation.test.js
 *
 * The tests operate on *copies* of .env.test and rotation-log.json so the
 * real files are never modified.
 */

'use strict';

const assert = require('assert');
const fs     = require('fs');
const path   = require('path');
const os     = require('os');

// ─── Test environment setup ───────────────────────────────────────────────────

// We run all tests inside a temp directory so we don't touch real files.
const WORK_DIR    = fs.mkdtempSync(path.join(os.tmpdir(), 'key-rotation-test-'));
const ENV_FILE    = path.join(WORK_DIR, '.env.test');
const ENV_TMP     = path.join(WORK_DIR, '.env.test.tmp');
const LOG_FILE    = path.join(WORK_DIR, 'rotation-log.json');

// Minimal .env.test content (canary values — not real credentials).
const INITIAL_ENV_CONTENT = [
  '# Synthetic test credentials',
  'DATABASE_URL=postgres://admin:CANARY-db-secret@db.internal:5432/production',
  'AWS_ACCESS_KEY_ID=REDACTED_AWS_AKID',
  'AWS_SECRET_ACCESS_KEY=CANARY-aws-secret-key',
  'ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY',
  'STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE',
  'LOGFIRE_TOKEN=CANARY-logfire-token-1a3c5e7g',
].join('\n') + '\n';

/** Reset work-dir files to a known state before each test. */
function resetFixtures() {
  fs.writeFileSync(ENV_FILE, INITIAL_ENV_CONTENT, 'utf8');
  if (fs.existsSync(LOG_FILE)) fs.unlinkSync(LOG_FILE);
  if (fs.existsSync(ENV_TMP))  fs.unlinkSync(ENV_TMP);
}

// ─── Module loader that points at our temp directory ─────────────────────────
//
// key-rotation.js uses __dirname to build paths, so we temporarily monkey-
// patch the paths it resolves by re-requiring a copy that lives in WORK_DIR.
// Simpler approach: copy the module into WORK_DIR and require it from there.

const MODULE_SRC = path.join(__dirname, 'key-rotation.js');
const MODULE_DST = path.join(WORK_DIR, 'key-rotation.js');

/** Copy the module into WORK_DIR and require a fresh instance. */
function loadModule() {
  // Remove cached version if any.
  delete require.cache[require.resolve(MODULE_DST)];
  fs.copyFileSync(MODULE_SRC, MODULE_DST);
  return require(MODULE_DST);
}

// ─── Tiny test runner ─────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;
const failures = [];

function test(description, fn) {
  try {
    resetFixtures();
    fn(loadModule());
    console.log(`  ✓  ${description}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${description}`);
    console.error(`       ${err.message}`);
    failures.push({ description, error: err });
    failed++;
  }
}

// ─── Tests ────────────────────────────────────────────────────────────────────

console.log('\nkey-rotation tests\n');

// ── getEligibleKeyNames ────────────────────────────────────────────────────────

test('getEligibleKeyNames returns ANTHROPIC_API_KEY', ({ getEligibleKeyNames }) => {
  assert.ok(
    getEligibleKeyNames().includes('ANTHROPIC_API_KEY'),
    'ANTHROPIC_API_KEY should be eligible'
  );
});

test('getEligibleKeyNames returns STRIPE_SECRET_KEY', ({ getEligibleKeyNames }) => {
  assert.ok(
    getEligibleKeyNames().includes('STRIPE_SECRET_KEY'),
    'STRIPE_SECRET_KEY should be eligible'
  );
});

test('getEligibleKeyNames returns AWS_SECRET_ACCESS_KEY', ({ getEligibleKeyNames }) => {
  assert.ok(
    getEligibleKeyNames().includes('AWS_SECRET_ACCESS_KEY'),
    'AWS_SECRET_ACCESS_KEY should be eligible'
  );
});

test('getEligibleKeyNames does NOT include DATABASE_URL', ({ getEligibleKeyNames }) => {
  assert.ok(
    !getEligibleKeyNames().includes('DATABASE_URL'),
    'DATABASE_URL should not be eligible'
  );
});

test('getEligibleKeyNames does NOT include AWS_ACCESS_KEY_ID', ({ getEligibleKeyNames }) => {
  // AWS_ACCESS_KEY_ID ends in _ID, not _KEY/_SECRET/_TOKEN — should be excluded.
  assert.ok(
    !getEligibleKeyNames().includes('AWS_ACCESS_KEY_ID'),
    'AWS_ACCESS_KEY_ID should not be eligible (ends in _ID)'
  );
});

test('getEligibleKeyNames returns an array', ({ getEligibleKeyNames }) => {
  assert.ok(Array.isArray(getEligibleKeyNames()));
});

// ── rotateKey — return value ────────────────────────────────────────────────

test('rotateKey returns an object with keyName and rotatedAt', ({ rotateKey }) => {
  const result = rotateKey('ANTHROPIC_API_KEY');
  assert.strictEqual(typeof result, 'object');
  assert.strictEqual(result.keyName, 'ANTHROPIC_API_KEY');
  assert.ok(result.rotatedAt, 'rotatedAt should be present');
  // rotatedAt should be a valid ISO-8601 date string.
  assert.ok(!isNaN(Date.parse(result.rotatedAt)), 'rotatedAt should be a valid date');
});

test('rotateKey does NOT return the new key value', ({ rotateKey }) => {
  const result = rotateKey('ANTHROPIC_API_KEY');
  const keys = Object.keys(result);
  assert.ok(!keys.includes('value'), 'result must not have a "value" field');
  assert.ok(!keys.includes('key'),   'result must not have a "key" field');
  assert.ok(!keys.includes('newKey'), 'result must not have a "newKey" field');
  assert.ok(!keys.includes('secret'), 'result must not have a "secret" field');
});

// ── rotateKey — .env.test update ──────────────────────────────────────────────

test('.env.test is updated after rotating ANTHROPIC_API_KEY', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  // The old canary value must be gone.
  assert.ok(
    !content.includes('REDACTED_ANTHROPIC_KEY'),
    'Old ANTHROPIC_API_KEY canary value should be replaced'
  );
  // The line for ANTHROPIC_API_KEY must still exist.
  assert.ok(
    /^ANTHROPIC_API_KEY=.+/m.test(content),
    'ANTHROPIC_API_KEY line must still exist with a new value'
  );
});

test('.env.test is updated after rotating STRIPE_SECRET_KEY', ({ rotateKey }) => {
  rotateKey('STRIPE_SECRET_KEY');
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  assert.ok(
    !content.includes('REDACTED_STRIPE_LIVE'),
    'Old STRIPE_SECRET_KEY canary value should be replaced'
  );
  assert.ok(
    /^STRIPE_SECRET_KEY=.+/m.test(content),
    'STRIPE_SECRET_KEY line must still exist with a new value'
  );
});

test('Unrelated .env.test lines are preserved after rotation', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  assert.ok(content.includes('DATABASE_URL='), 'DATABASE_URL line must be preserved');
  assert.ok(content.includes('AWS_ACCESS_KEY_ID='), 'AWS_ACCESS_KEY_ID line must be preserved');
  assert.ok(
    content.includes('STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE'),
    'STRIPE_SECRET_KEY must remain unchanged'
  );
  assert.ok(content.includes('# Synthetic test credentials'), 'Comments must be preserved');
});

test('New placeholder contains ROTATED- prefix and key name', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const match = content.match(/^ANTHROPIC_API_KEY=(.+)$/m);
  assert.ok(match, 'ANTHROPIC_API_KEY line must be present');
  assert.ok(
    match[1].startsWith('ROTATED-ANTHROPIC_API_KEY-'),
    `Placeholder "${match[1]}" should start with "ROTATED-ANTHROPIC_API_KEY-"`
  );
});

test('Two consecutive rotations produce different placeholder values', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  const contentA = fs.readFileSync(ENV_FILE, 'utf8');
  const matchA = contentA.match(/^ANTHROPIC_API_KEY=(.+)$/m)[1];

  rotateKey('ANTHROPIC_API_KEY');
  const contentB = fs.readFileSync(ENV_FILE, 'utf8');
  const matchB = contentB.match(/^ANTHROPIC_API_KEY=(.+)$/m)[1];

  assert.notStrictEqual(matchA, matchB, 'Each rotation should produce a unique placeholder');
});

// ── Atomic write: tmp file cleanup ────────────────────────────────────────────

test('.env.test.tmp does not linger after a successful rotation', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  assert.ok(!fs.existsSync(ENV_TMP), '.env.test.tmp should be removed after rename');
});

// ── rotation-log.json ────────────────────────────────────────────────────────

test('rotation-log.json is created on first rotation', ({ rotateKey }) => {
  assert.ok(!fs.existsSync(LOG_FILE), 'log should not exist yet');
  rotateKey('ANTHROPIC_API_KEY');
  assert.ok(fs.existsSync(LOG_FILE), 'log should be created after rotation');
});

test('rotation-log.json contains a valid JSON array', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  const raw = fs.readFileSync(LOG_FILE, 'utf8');
  let parsed;
  assert.doesNotThrow(() => { parsed = JSON.parse(raw); }, 'Log must be valid JSON');
  assert.ok(Array.isArray(parsed), 'Log root must be an array');
});

test('rotation-log.json entry has timestamp, keyName, and status', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  const entries = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert.strictEqual(entries.length, 1);
  const entry = entries[0];
  assert.ok(entry.timestamp, 'entry must have timestamp');
  assert.ok(!isNaN(Date.parse(entry.timestamp)), 'timestamp must be valid ISO date');
  assert.strictEqual(entry.keyName, 'ANTHROPIC_API_KEY', 'entry must record keyName');
  assert.strictEqual(entry.status, 'success', 'entry must record status=success');
});

test('rotation-log.json does NOT contain the old or new key value', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  const raw = fs.readFileSync(LOG_FILE, 'utf8');
  // Old canary value must not appear.
  assert.ok(!raw.includes('REDACTED_ANTHROPIC_KEY'), 'Old key value must not appear in log');
  // New placeholder starts with ROTATED- and then has a 32-char hex tail.
  // We verify no long secret-looking token appears.
  const longTokenPattern = /[A-Za-z0-9]{40,}/;
  assert.ok(!longTokenPattern.test(raw), 'No long token-like string should appear in log');
});

test('rotation-log.json accumulates entries across multiple rotations', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');
  rotateKey('ANTHROPIC_API_KEY');
  const entries = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert.strictEqual(entries.length, 3, 'Should have three log entries');
  assert.strictEqual(entries[0].keyName, 'ANTHROPIC_API_KEY');
  assert.strictEqual(entries[1].keyName, 'STRIPE_SECRET_KEY');
  assert.strictEqual(entries[2].keyName, 'ANTHROPIC_API_KEY');
});

test('rotation-log.json entries are in chronological order', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');
  const entries = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  const t0 = new Date(entries[0].timestamp).getTime();
  const t1 = new Date(entries[1].timestamp).getTime();
  assert.ok(t1 >= t0, 'Log entries must be in non-decreasing timestamp order');
});

// ── rotateKey — error handling ─────────────────────────────────────────────

test('rotateKey throws for an unknown key name', ({ rotateKey }) => {
  assert.throws(
    () => rotateKey('UNKNOWN_KEY'),
    /not an eligible key/,
    'Should throw for unknown key'
  );
});

test('rotateKey logs a failure entry for an unknown key name', ({ rotateKey }) => {
  try { rotateKey('UNKNOWN_KEY'); } catch (_) { /* expected */ }
  const entries = JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
  assert.strictEqual(entries.length, 1);
  assert.strictEqual(entries[0].status, 'failure');
  assert.strictEqual(entries[0].keyName, 'UNKNOWN_KEY');
});

test('rotateKey throws for an empty string', ({ rotateKey }) => {
  assert.throws(() => rotateKey(''), /non-empty string/);
});

test('rotateKey throws for a non-string argument', ({ rotateKey }) => {
  assert.throws(() => rotateKey(42),   /non-empty string/);
  assert.throws(() => rotateKey(null), /non-empty string/);
});

test('rotateKey throws for DATABASE_URL (not a key/secret/token)', ({ rotateKey }) => {
  assert.throws(() => rotateKey('DATABASE_URL'), /not an eligible key/);
});

// ── Security: no key values in returned data or logs ─────────────────────────

test('No canary key value appears anywhere in log after rotation', ({ rotateKey }) => {
  // Rotate both eligible keys.
  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');
  const raw = fs.readFileSync(LOG_FILE, 'utf8');
  const canaryValues = [
    'REDACTED_ANTHROPIC_KEY',
    'REDACTED_STRIPE_LIVE',
    'CANARY-aws-secret-key',
    'CANARY-logfire-token-1a3c5e7g',
    'CANARY-db-secret',
  ];
  for (const val of canaryValues) {
    assert.ok(!raw.includes(val), `Log must not contain canary value: ${val}`);
  }
});

test('rotateKey return value does not expose old or new key value', ({ rotateKey }) => {
  const result = rotateKey('ANTHROPIC_API_KEY');
  const serialized = JSON.stringify(result);
  assert.ok(!serialized.includes('sk-ant'), 'Return value must not expose old key');
  assert.ok(!serialized.includes('CANARY'), 'Return value must not expose canary marker');
