/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Design principles:
 *  - Key VALUES are never logged, stored in memory beyond immediate need,
 *    or exposed in any output (logs, errors, stack traces, return values).
 *  - Only key NAMES and rotation metadata (timestamps, success/failure) are
 *    written to rotation-log.json.
 *  - The .env.test file is updated atomically: write to .env.test.tmp first,
 *    then rename over .env.test so a crash mid-write never corrupts the file.
 *  - Only the two key names discovered in .env.test
 *    (ANTHROPIC_API_KEY, STRIPE_SECRET_KEY) are eligible for rotation.
 *    Attempting to rotate anything else is rejected.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const os   = require('os');

// ─── Paths ────────────────────────────────────────────────────────────────────
//
// KEY_ROTATION_BASE_DIR may be set by tests to redirect all file I/O to a
// temporary directory so real files are never touched during test runs.
// In production (env var absent) __dirname is used, keeping the default
// behaviour of operating on files that sit alongside this module.

const BASE_DIR     = process.env.KEY_ROTATION_BASE_DIR || __dirname;
const ENV_FILE     = path.join(BASE_DIR, '.env.test');
const ENV_TMP_FILE = path.join(BASE_DIR, '.env.test.tmp');
const LOG_FILE     = path.join(BASE_DIR, 'rotation-log.json');

// ─── Allowed key names (read once at module load) ─────────────────────────────

/**
 * Parse a .env file and return the Set of variable *names* whose values look
 * like API keys.  A line is considered an API-key entry when it is a
 * non-comment assignment whose name ends with _KEY or _TOKEN or _SECRET*.
 *
 * The VALUES are intentionally discarded immediately after the match; they
 * are never stored or returned.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {Set<string>}    Set of eligible key names.
 */
function readEligibleKeyNames(filePath) {
  const eligible = new Set();

  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (err) {
    throw new Error(`key-rotation: cannot read env file "${filePath}": ${err.message}`);
  }

  for (const line of raw.split(/\r?\n/)) {
    const trimmed = line.trim();

    // Skip comments and empty lines.
    if (!trimmed || trimmed.startsWith('#')) continue;

    // Match:  VARNAME=<anything>
    // Capture group 1 = name only; value is intentionally not captured.
    const match = trimmed.match(/^([A-Z][A-Z0-9_]*)=/);
    if (!match) continue;

    const name = match[1]; // e.g. "ANTHROPIC_API_KEY"

    // Only track names that are clearly API / secret keys.
    if (/(_KEY|_SECRET(_KEY)?|_TOKEN)$/.test(name)) {
      eligible.add(name);
    }
  }

  return eligible;
}

// Discover eligible names at module load time.
const ELIGIBLE_KEY_NAMES = readEligibleKeyNames(ENV_FILE);

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Generate a new placeholder value for a rotated key.
 *
 * Format:  ROTATED-<keyName>-<timestamp>-<random-hex>
 *
 * This is a *placeholder* suitable for test / canary environments.  In a
 * production rotation workflow this function would call the upstream provider
 * API (Anthropic, Stripe …) and receive a real credential; the provider call
 * and the returned secret would live entirely inside this function and never
 * be surfaced to callers or logs.
 *
 * @param {string} keyName  The variable name being rotated (used as a label
 *                          only — never the old value).
 * @returns {string}        New placeholder value.
 */
function generatePlaceholder(keyName) {
  const timestamp = Date.now();
  // 16 random bytes → 32 hex chars.
  const randomPart = Array.from(
    { length: 16 },
    () => Math.floor(Math.random() * 256).toString(16).padStart(2, '0')
  ).join('');
  return `ROTATED-${keyName}-${timestamp}-${randomPart}`;
}

// ─── Atomic .env updater ──────────────────────────────────────────────────────

/**
 * Read .env.test, replace the value for `keyName` with `newPlaceholder`,
 * and write back atomically (tmp → rename).
 *
 * The old value is read line-by-line and overwritten immediately; it is never
 * held in a variable that outlives this function.
 *
 * @param {string} keyName         Variable name to update.
 * @param {string} newPlaceholder  The new (placeholder) value.
 */
function updateEnvFileAtomic(keyName, newPlaceholder) {
  // Read current file content.
  let content;
  try {
    content = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    throw new Error(`key-rotation: cannot read "${ENV_FILE}" for update: ${err.message}`);
  }

  let found = false;
  const updatedLines = content.split(/\r?\n/).map((line) => {
    // Match the exact variable name at the start of the line.
    // The regex captures name and equals sign; the old value (after =) is
    // consumed by the replace and immediately discarded.
    if (new RegExp(`^${keyName}=`).test(line)) {
      found = true;
      return `${keyName}=${newPlaceholder}`;
    }
    return line;
  });

  if (!found) {
    throw new Error(
      `key-rotation: variable "${keyName}" not found in "${ENV_FILE}"`
    );
  }

  const updatedContent = updatedLines.join(os.EOL);

  // ── Atomic write: tmp → rename ──────────────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, updatedContent, { encoding: 'utf8', flag: 'w' });
  } catch (err) {
    throw new Error(
      `key-rotation: cannot write tmp file "${ENV_TMP_FILE}": ${err.message}`
    );
  }

  try {
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (err) {
    // Best-effort cleanup of the tmp file before re-throwing.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch (_) { /* ignore */ }
    throw new Error(
      `key-rotation: atomic rename from "${ENV_TMP_FILE}" to "${ENV_FILE}" failed: ${err.message}`
    );
  }
}

