/**
 * Append a rotation event to rotation-log.json.
 *
 * Each entry records ONLY:
 *   - timestamp  (ISO-8601 string)
 *   - keyName    (variable name, e.g. "ANTHROPIC_API_KEY")
 *   - status     ("success" | "failure")
 *   - reason     (human-readable note; MUST NOT contain key values)
 *
 * The log file holds a top-level JSON array; entries are appended by reading
 * the existing array (or starting a new one), pushing the new entry, and
 * rewriting the file.  The file itself never contains key values.
 *
 * @param {object} entry
 * @param {string} entry.keyName
