  // ── 5. Security: key values never leave .env.test ────────────────────────
  console.log('\nSecurity: key values never exposed');

  await test('.env.test still contains all original non-rotated keys after rotation',
    withSandbox(() => {
      const { rotateKey } = require('./key-rotation');
      rotateKey('ANTHROPIC_API_KEY');

      const content = fs.readFileSync(ORIGINAL_ENV_FILE, 'utf8');
      assert(content.includes('DATABASE_URL=postgres://'),     'DATABASE_URL must be intact');
      assert(content.includes('LOGFIRE_TOKEN=CANARY-logfire'), 'LOGFIRE_TOKEN must be intact');
    })
  );

  await test('return value of rotateKey has no property containing the new placeholder',
    withSandbox(() => {
      const { rotateKey } = require('./key-rotation');
      const result = rotateKey('STRIPE_SECRET_KEY');

      for (const [k, v] of Object.entries(result)) {
