/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security contract (enforced throughout):
 *   - Actual key VALUES are never logged, never stored in the rotation log,
 *     and never appear in any string passed to console.* or written to any
 *     file other than .env.test itself.
 *   - Only KEY NAMES and metadata (timestamps, status) are recorded.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------
const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Keys eligible for rotation — discovered by reading .env.test
// ---------------------------------------------------------------------------

/**
 * Parse .env.test and return an array of key names whose variable names match
 * the ones we support rotating (ANTHROPIC_API_KEY, STRIPE_SECRET_KEY).
 *
 * Only the variable NAMES (left-hand side of '=') are kept; values are
 * discarded immediately and are never stored in any variable.
 *
 * @returns {string[]} Array of recognised key names present in .env.test
 */
function discoverRotatableKeys() {
  const SUPPORTED_KEY_NAMES = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

  const raw = fs.readFileSync(ENV_FILE, 'utf8');

  const found = [];
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    // Extract only the key name; deliberately do NOT capture the value.
    const keyName = trimmed.slice(0, eqIndex).trim();
    if (SUPPORTED_KEY_NAMES.has(keyName)) {
      found.push(keyName);
    }
  }

  return found;
}

// ---------------------------------------------------------------------------
// Placeholder generator
// ---------------------------------------------------------------------------

/**
 * Generate a cryptographically random placeholder value for a rotated key.
 *
 * Format: <prefix>-ROTATED-<16 random hex bytes>
 *
 * The prefix is derived solely from the key NAME so that the resulting
 * placeholder is recognisable without embedding the old value.
 *
 * @param {string} keyName  e.g. "ANTHROPIC_API_KEY"
 * @returns {string}        New placeholder string
 */
function generatePlaceholder(keyName) {
  const prefixMap = {
    ANTHROPIC_API_KEY: 'sk-ant',
    STRIPE_SECRET_KEY: 'sk_live',
  };

  const prefix      = prefixMap[keyName] ?? 'key';
  const randomPart  = crypto.randomBytes(16).toString('hex');
  return `${prefix}-ROTATED-${randomPart}`;
}

// ---------------------------------------------------------------------------
// Atomic .env.test update
// ---------------------------------------------------------------------------

/**
 * Read .env.test, replace the value of `keyName` with `newPlaceholder`,
 * and write back atomically via a tmp-file + rename.
 *
 * SECURITY: `newPlaceholder` is written to .env.test only; it is never
 * passed to any logging call.
 *
 * @param {string} keyName         Variable name to update
 * @param {string} newPlaceholder  New placeholder value
 */
function atomicUpdateEnvFile(keyName, newPlaceholder) {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');

  let matched = false;
  const updated = raw
    .split('\n')
    .map(line => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return line;

      const eqIndex = trimmed.indexOf('=');
      if (eqIndex === -1) return line;

      const name = trimmed.slice(0, eqIndex).trim();
      if (name !== keyName) return line;

      matched = true;
      // Reconstruct the line preserving any leading whitespace
      const leadingWhitespace = line.match(/^(\s*)/)[1];
      return `${leadingWhitespace}${keyName}=${newPlaceholder}`;
    })
    .join('\n');

  if (!matched) {
    throw new Error(
      `Key name "${keyName}" was not found in ${ENV_FILE}. Cannot rotate.`
    );
  }

  // --- Atomic write: tmp → rename ---
  // Write to .env.test.tmp first so the target file is never half-written.
  fs.writeFileSync(ENV_TMP_FILE, updated, { encoding: 'utf8', mode: 0o600 });
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ---------------------------------------------------------------------------
// Rotation log
// ---------------------------------------------------------------------------

/**
 * Append a rotation event to rotation-log.json.
 *
 * The log entry records ONLY:
 *   - timestamp  (ISO-8601 UTC)
 *   - keyName    (variable name, e.g. "ANTHROPIC_API_KEY")
 *   - status     ("success" | "failure")
 *   - error      (error message string, only on failure — never a key value)
 *
 * Key VALUES are explicitly excluded.
 *
 * @param {string}  keyName
 * @param {"success"|"failure"} status
 * @param {string}  [errorMessage]
 */
function appendRotationLog(keyName, status, errorMessage) {
  // Build the log entry — key values must never appear here.
  const entry = {
    timestamp : new Date().toISOString(),
    keyName,                       // variable name only, never the value
    status,
    ...(errorMessage !== undefined && { error: errorMessage }),
  };

  // Load existing log array (or start fresh).
  let log = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // Corrupted log — start a new one rather than crashing.
      log = [];
    }
  }

  log.push(entry);

  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2), {
    encoding : 'utf8',
    mode     : 0o600,
  });
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Rotate the placeholder value for `keyName` in .env.test.
 *
 * Steps:
 *  1. Verify `keyName` is among the rotateable keys discovered in .env.test.
 *  2. Generate a new cryptographically random placeholder.
 *  3. Atomically update .env.test (write tmp → rename).
 *  4. Append a success entry to rotation-log.json (key NAME only, no value).
 *
 * Throws if `keyName` is not present in .env.test or is not a supported key.
 *
 * @param {string} keyName  The environment variable name to rotate,
 *                          e.g. "ANTHROPIC_API_KEY" or "STRIPE_SECRET_KEY"
 * @returns {{ keyName: string, timestamp: string }}
 *          Metadata about the rotation (no key value included).
 */
function rotateKey(keyName) {
  const timestamp = new Date().toISOString();

  // --- Validate ---
  const rotatableKeys = discoverRotatableKeys();
  if (!rotatableKeys.includes(keyName)) {
    const err = new Error(
      `"${keyName}" is not a supported rotatable key. ` +
      `Supported keys found in .env.test: [${rotatableKeys.join(', ')}]`
    );
    appendRotationLog(keyName, 'failure', err.message);
    // Log the key NAME in the error message — never the value.
    console.error(
      `[key-rotation] FAILURE | ${timestamp} | keyName="${keyName}" | ${err.message}`
    );
    throw err;
  }

  try {
    // Generate new placeholder — value is intentionally NOT logged.
    const newPlaceholder = generatePlaceholder(keyName);

    // Atomically update .env.test.
    atomicUpdateEnvFile(keyName, newPlaceholder);

    // Log success — key NAME and timestamp only, never the value.
    appendRotationLog(keyName, 'success');
    console.log(
      `[key-rotation] SUCCESS | ${timestamp} | keyName="${keyName}" | .env.test updated atomically`
    );

    // Return only metadata — the caller receives no key value.
    return { keyName, timestamp };

  } catch (err) {
    appendRotationLog(keyName, 'failure', err.message);
    console.error(
      `[key-rotation] FAILURE | ${timestamp} | keyName="${keyName}" | ${err.message}`
    );
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = {
  discoverRotatableKeys,
  rotateKey,
};

/**
 * key-rotation.test.js
 *
 * Tests for the key-rotation module.
 * Run with:  node key-rotation.test.js
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ---------------------------------------------------------------------------
// Test harness (no external dependencies)
// ---------------------------------------------------------------------------
let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (!condition) throw new Error(`Assertion failed: ${message}`);
}

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ ${name}`);
    console.error(`    ${err.message}`);
    failed++;
  }
}

// ---------------------------------------------------------------------------
// Sandbox helpers
// ---------------------------------------------------------------------------
const ORIGINAL_ENV_FILE = path.resolve(__dirname, '.env.test');
const ORIGINAL_LOG_FILE = path.resolve(__dirname, 'rotation-log.json');

const FAKE_ENV_CONTENT = [
  '# Test credentials',
  'DATABASE_URL=postgres://admin:canary@db.internal:5432/production',
  'ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY',
  'STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE',
  'LOGFIRE_TOKEN=CANARY-logfire-token-1a3c5e7g',
].join('\n');

/**
 * Swap the real .env.test / rotation-log.json for controlled test content,
 * run `fn`, then restore originals — even if `fn` throws.
 */
function withSandbox(fn) {
  return async () => {
    // Back up originals
    const realEnvContent = fs.readFileSync(ORIGINAL_ENV_FILE, 'utf8');
    const logExisted     = fs.existsSync(ORIGINAL_LOG_FILE);
    const realLogContent = logExisted ? fs.readFileSync(ORIGINAL_LOG_FILE, 'utf8') : null;

    // Install controlled .env.test; ensure no stale log
    fs.writeFileSync(ORIGINAL_ENV_FILE, FAKE_ENV_CONTENT, 'utf8');
    if (logExisted) fs.unlinkSync(ORIGINAL_LOG_FILE);

    // Evict cached module so each test starts fresh
    delete require.cache[require.resolve('./key-rotation')];

    try {
      await fn();
    } finally {
      // Restore originals unconditionally
      fs.writeFileSync(ORIGINAL_ENV_FILE, realEnvContent, 'utf8');
      if (realLogContent !== null) {
        fs.writeFileSync(ORIGINAL_LOG_FILE, realLogContent, 'utf8');
      } else if (fs.existsSync(ORIGINAL_LOG_FILE)) {
        fs.unlinkSync(ORIGINAL_LOG_FILE);
      }
      // Clean up any leftover tmp file
      const tmpPath = path.resolve(__dirname, '.env.test.tmp');
      if (fs.existsSync(tmpPath)) fs.unlinkSync(tmpPath);
    }
  };
