/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security guarantees:
 *  - Actual key VALUES are never logged, printed, or included in any
 *    persistent record — only the key NAMES (e.g. "ANTHROPIC_API_KEY").
 *  - .env.test is updated atomically: the new content is written to a
 *    temporary file (.env.test.tmp) first, then renamed over the original
 *    so that a crash mid-write cannot leave the file partially updated.
 *  - rotation-log.json records only { timestamp, keyName, status }.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ───────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that this module is allowed to rotate ───────────────────────────────

/**
 * Reads .env.test and returns the set of key *names* that are present in the
 * file.  Only these names are eligible for rotation.
 *
 * @returns {Set<string>}
 */
function readRotatableKeyNames() {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  const names = new Set();

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    // Skip blank lines and comments.
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    names.add(trimmed.slice(0, eqIndex).trim());
  }

  return names;
}

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Generates a new placeholder value for a rotated key.
 *
 * Format:  ROTATED-<keyName>-<16 random hex chars>-<ISO timestamp fragment>
 *
 * The result intentionally looks like a synthetic / canary credential; it is
 * NOT a real API key and must be replaced with a genuine secret by your
 * secrets-management pipeline after rotation.
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(8).toString('hex'); // 16 hex chars
  // Use a compact timestamp fragment (YYYYMMDDTHHMMSS) so the placeholder
  // carries a human-readable "rotated-at" hint without embedding a full
  // ISO string that might confuse line parsers.
  const now = new Date();
  const ts = [
    now.getUTCFullYear(),
    String(now.getUTCMonth() + 1).padStart(2, '0'),
    String(now.getUTCDate()).padStart(2, '0'),
    'T',
    String(now.getUTCHours()).padStart(2, '0'),
    String(now.getUTCMinutes()).padStart(2, '0'),
    String(now.getUTCSeconds()).padStart(2, '0'),
    'Z',
  ].join('');

  return `ROTATED-${keyName}-${randomHex}-${ts}`;
}

// ─── Atomic .env.test writer ──────────────────────────────────────────────────

/**
 * Parses .env.test, replaces the value for `keyName` with `newValue`, and
 * writes the result back atomically (tmp → rename).
 *
 * Lines that do not belong to `keyName` — including comments and blanks —
 * are preserved byte-for-byte.
 *
 * @param {string} keyName   The variable name whose value should be replaced.
 * @param {string} newValue  The replacement value (a placeholder string).
 */
function atomicUpdateEnvFile(keyName, newValue) {
  const raw  = fs.readFileSync(ENV_FILE, 'utf8');
  let   found = false;

  const updated = raw
    .split('\n')
    .map((line) => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return line;

      const eqIndex = trimmed.indexOf('=');
      if (eqIndex === -1) return line;

      const name = trimmed.slice(0, eqIndex).trim();
      if (name !== keyName) return line;

      found = true;
      // Preserve any leading whitespace the original line had.
      const leadingWhitespace = line.slice(0, line.length - line.trimStart().length);
      return `${leadingWhitespace}${keyName}=${newValue}`;
    })
    .join('\n');

  if (!found) {
    throw new Error(
      `Key "${keyName}" was not found in ${ENV_FILE}. Rotation aborted.`
    );
  }

  // ① Write to the temporary file.
  fs.writeFileSync(ENV_TMP_FILE, updated, { encoding: 'utf8', flag: 'w' });

  // ② Atomically rename tmp → original.
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ─── Audit log ────────────────────────────────────────────────────────────────

/**
 * Appends a rotation event to rotation-log.json.
 *
 * The log entry contains ONLY:
 *   - timestamp  : ISO-8601 wall-clock time of the rotation
 *   - keyName    : the variable *name* (e.g. "ANTHROPIC_API_KEY")
 *   - status     : "success" | "failure"
 *   - error      : (only present on failure) a sanitised error message
 *
 * Key *values* are never written here.
 *
 * @param {string}      keyName
 * @param {"success"|"failure"} status
 * @param {Error|null}  [err]
 */
function appendRotationLog(keyName, status, err = null) {
  // Read existing log or start fresh.
  let entries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      entries = Array.isArray(parsed) ? parsed : [];
    } catch {
      // If the log file is corrupt, start a new array rather than crashing.
      entries = [];
    }
  }

  const entry = {
    timestamp: new Date().toISOString(),
    keyName,
    status,
  };

  if (status === 'failure' && err instanceof Error) {
    // Sanitise the error message to make sure it cannot leak a value.
    // We strip anything that looks like an `=VALUE` assignment.
    entry.error = err.message.replace(/=\S+/g, '=<redacted>');
  }

  entries.push(entry);

  // Write the log file.  This does NOT need to be atomic for correctness
  // (it is append-only audit data), but we do a read-modify-write so that
  // the file is always valid JSON.
  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotates the specified key in .env.test.
 *
 * Steps:
 *  1. Verify `keyName` is one of the keys present in .env.test
 *     (currently ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are the targets,
 *     but the check is dynamic — any key listed in the file is rotatable).
 *  2. Generate a new placeholder value.
 *  3. Atomically update .env.test (write tmp, rename).
 *  4. Append a rotation event to rotation-log.json (name + timestamp only).
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ keyName: string, timestamp: string }}
 *   Metadata about the rotation (never includes the new value).
 * @throws {Error} If keyName is not found in .env.test or I/O fails.
 */
function rotateKey(keyName) {
  if (typeof keyName !== 'string' || !keyName.trim()) {
    const err = new TypeError('rotateKey: keyName must be a non-empty string.');
    appendRotationLog(String(keyName), 'failure', err);
    throw err;
  }

  // Step 1 — confirm the key exists in the file.
  const rotatableNames = readRotatableKeyNames();
  if (!rotatableNames.has(keyName)) {
    const err = new Error(
      `rotateKey: "${keyName}" is not present in ${ENV_FILE}. ` +
      `Available keys: ${[...rotatableNames].join(', ')}.`
    );
    appendRotationLog(keyName, 'failure', err);
    throw err;
  }

  // Step 2 — generate placeholder (value is kept in a local variable only).
  const placeholder = generatePlaceholder(keyName);

  // Step 3 — atomic file update.
  try {
    atomicUpdateEnvFile(keyName, placeholder);
  } catch (err) {
    appendRotationLog(keyName, 'failure', err);
    throw err;
  }

  // Step 4 — audit log (name + timestamp, NOT the placeholder value).
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName, 'success');

  console.log(`[key-rotation] Rotated key: ${keyName} at ${timestamp}`);

  // Return only metadata — the caller never receives the new value.
  return { keyName, timestamp };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  rotateKey,
  readRotatableKeyNames, // exported for inspection / testing
};

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Run with:  node key-rotation.test.js
 *
 * Each test works against temporary copies of .env.test and rotation-log.json
 * so the real files are never mutated by the test run.
 */

'use strict';

const fs   = require('fs');
const path = require('path');

// ─── Minimal test harness ─────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (!condition) throw new Error(`Assertion failed: ${message}`);
}

async function test(name, fn) {
  try {
    await fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`     ${err.message}`);
    failed++;
  }
}

// ─── Fixture paths ────────────────────────────────────────────────────────────

const REAL_ENV      = path.resolve(__dirname, '.env.test');
const REAL_LOG      = path.resolve(__dirname, 'rotation-log.json');
const REAL_TMP      = path.resolve(__dirname, '.env.test.tmp');

// Backups so we can restore after the suite.
const BACKUP_ENV    = path.resolve(__dirname, '.env.test.bak');
const BACKUP_LOG    = path.resolve(__dirname, 'rotation-log.json.bak');

// ─── Setup / teardown helpers ─────────────────────────────────────────────────

function setup() {
  // Back up originals.
  fs.copyFileSync(REAL_ENV, BACKUP_ENV);
  if (fs.existsSync(REAL_LOG)) fs.copyFileSync(REAL_LOG, BACKUP_LOG);

  // Remove log so each suite run starts clean.
  if (fs.existsSync(REAL_LOG)) fs.unlinkSync(REAL_LOG);
}

function teardown() {
  // Restore originals.
  fs.copyFileSync(BACKUP_ENV, REAL_ENV);
  fs.unlinkSync(BACKUP_ENV);

  if (fs.existsSync(BACKUP_LOG)) {
    fs.copyFileSync(BACKUP_LOG, REAL_LOG);
    fs.unlinkSync(BACKUP_LOG);
  } else if (fs.existsSync(REAL_LOG)) {
    fs.unlinkSync(REAL_LOG);
  }

  // Clean up any leftover tmp file.
  if (fs.existsSync(REAL_TMP)) fs.unlinkSync(REAL_TMP);
}

function resetEnvToOriginal() {
  fs.copyFileSync(BACKUP_ENV, REAL_ENV);
}

function freshRequire() {
  // Delete cached module so path constants are re-evaluated from scratch.
  delete require.cache[require.resolve('./key-rotation')];
  return require('./key-rotation');
}

// ─── Test suite ───────────────────────────────────────────────────────────────

async function runTests() {
  console.log('\nkey-rotation.js — test suite\n');
  setup();

  // ── readRotatableKeyNames ──────────────────────────────────────────────────

  await test('readRotatableKeyNames returns a Set', () => {
