    const ts = entries[0].timestamp;
    assert(!isNaN(Date.parse(ts)), `Timestamp "${ts}" is not valid ISO-8601`);
  });

  await test('log grows with each rotation (entries are appended, not overwritten)', () => {
    resetEnvToOriginal();
    if (fs.existsSync(REAL_LOG)) fs.unlinkSync(REAL_LOG);

    const { rotateKey } = freshRequire();
    rotateKey('ANTHROPIC_API_KEY');
    rotateKey('STRIPE_SECRET_KEY');
    rotateKey('ANTHROPIC_API_KEY');

    const entries = JSON.parse(fs.readFileSync(REAL_LOG, 'utf8'));
    assert(entries.length === 3, `Expected 3 log entries, got ${entries.length}`);
  });

  // ── Security: key values must NEVER appear in the log ─────────────────────

  await test('SECURITY: actual key values do not appear in rotation-log.json', () => {
    resetEnvToOriginal();
    if (fs.existsSync(REAL_LOG)) fs.unlinkSync(REAL_LOG);

    // Capture all current values from the env file before rotation.
    const envContent = fs.readFileSync(REAL_ENV, 'utf8');
    const values = envContent
      .split('\n')
      .filter(l => l.trim() && !l.trim().startsWith('#') && l.includes('='))
      .map(l => l.slice(l.indexOf('=') + 1).trim())
      .filter(v => v.length > 0);

    const { rotateKey } = freshRequire();
    rotateKey('ANTHROPIC_API_KEY');
    rotateKey('STRIPE_SECRET_KEY');

    const logContent = fs.readFileSync(REAL_LOG, 'utf8');
    for (const val of values) {
      assert(!logContent.includes(val),
        `SECURITY VIOLATION: key value "${val}" found in rotation-log.json`);
    }
  });

  await test('SECURITY: new placeholder values do not appear in rotation-log.json', () => {
    resetEnvToOriginal();
    if (fs.existsSync(REAL_LOG)) fs.unlinkSync(REAL_LOG);

    const { rotateKey } = freshRequire();
    rotateKey('ANTHROPIC_API_KEY');

    // Read what the new value actually is in the env file.
    const envContent = fs.readFileSync(REAL_ENV, 'utf8');
    const newValue = envContent
      .split('\n')
      .find(l => l.startsWith('ANTHROPIC_API_KEY='))
      .slice('ANTHROPIC_API_KEY='.length);

    const logContent = fs.readFileSync(REAL_LOG, 'utf8');
    assert(!logContent.includes(newValue),
      `SECURITY VIOLATION: new placeholder value "${newValue}" found in rotation-log.json`);
  });

  // ── Error handling ────────────────────────────────────────────────────────

  await test('rotateKey throws for an unknown key name', () => {
    const { rotateKey } = freshRequire();
    let threw = false;
    try {
      rotateKey('NONEXISTENT_KEY_XYZ');
    } catch {
      threw = true;
    }
    assert(threw, 'rotateKey must throw for an unknown key name');
  });

  await test('rotateKey logs a failure entry for an unknown key name', () => {
    if (fs.existsSync(REAL_LOG)) fs.unlinkSync(REAL_LOG);

    const { rotateKey } = freshRequire();
    try { rotateKey('NONEXISTENT_KEY_XYZ'); } catch { /* expected */ }

    const entries = JSON.parse(fs.readFileSync(REAL_LOG, 'utf8'));
    const failEntry = entries.find(e => e.keyName === 'NONEXISTENT_KEY_XYZ');
    assert(failEntry, 'A failure log entry must be written for the bad key');
    assert(failEntry.status === 'failure', 'status must be "failure"');
  });

  await test('rotateKey throws for an empty string key name', () => {
    const { rotateKey } = freshRequire();
    let threw = false;
    try { rotateKey(''); } catch { threw = true; }
    assert(threw, 'rotateKey must throw for an empty string');
  });

  await test('rotateKey throws for a non-string argument', () => {
    const { rotateKey } = freshRequire();
    for (const bad of [null, undefined, 42, {}, []]) {
      let threw = false;
      try { rotateKey(bad); } catch { threw = true; }
      assert(threw, `rotateKey must throw for argument: ${JSON.stringify(bad)}`);
    }
  });

  // ── Idempotency / file integrity ──────────────────────────────────────────

  await test('.env.test comment lines are preserved after rotation', () => {
    resetEnvToOriginal();
    const before = fs.readFileSync(REAL_ENV, 'utf8');
    const commentsBefore = before.split('\n').filter(l => l.trim().startsWith('#'));

    const { rotateKey } = freshRequire();
    rotateKey('ANTHROPIC_API_KEY');

    const after = fs.readFileSync(REAL_ENV, 'utf8');
    const commentsAfter = after.split('\n').filter(l => l.trim().startsWith('#'));

    assert(JSON.stringify(commentsBefore) === JSON.stringify(commentsAfter),
      'Comment lines must be unchanged after rotation');
  });

  await test('.env.test is still parseable as an env file after rotation', () => {
    resetEnvToOriginal();
    const { rotateKey } = freshRequire();
    rotateKey('ANTHROPIC_API_KEY');
    rotateKey('STRIPE_SECRET_KEY');

    const content = fs.readFileSync(REAL_ENV, 'utf8');
    for (const line of content.split('\n')) {
      const t = line.trim();
      if (!t || t.startsWith('#')) continue;
      assert(t.includes('='),
        `Every non-comment, non-blank line must contain "=": "${line}"`);
    }
  });

  // ── Summary ───────────────────────────────────────────────────────────────

  teardown();

  console.log(`\n${'─'.repeat(50)}`);
  console.log(`Results: ${passed} passed, ${failed} failed`);

  if (failed > 0) {
    process.exitCode = 1;
  }
}

runTests().catch(err => {
  console.error('Unexpected error in test runner:', err);
  teardown();
  process.exitCode = 1;
});

