/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security guarantees enforced throughout this module:
 *  - Actual key *values* are NEVER logged, stored in the rotation log,
 *    or written to any location other than the .env file itself.
 *  - Only key *names* (e.g. "ANTHROPIC_API_KEY") appear in log output.
 *  - The .env file is updated atomically: write to a temp file first,
 *    then rename so that a crash can never leave the file half-written.
 *  - Generated placeholders follow the same structural shape as the
 *    original keys so that downstream validation keeps working, but they
 *    are clearly marked as ROTATED-PLACEHOLDER values.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ───────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = ENV_FILE + '.tmp';
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys whose rotation is supported (read from .env.test at startup) ───────

/**
 * Parse an .env file and return a Map of { variableName -> rawLine }.
 * Lines that are blank or start with '#' are skipped for key extraction
 * but preserved verbatim for reconstruction.
 *
 * @param {string} content  Raw text content of the .env file.
 * @returns {{ lines: string[], keyNames: string[] }}
 */
function parseEnv(content) {
  const lines    = content.split('\n');
  const keyNames = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    const name = trimmed.slice(0, eqIndex).trim();
    if (name) keyNames.push(name);
  }

  return { lines, keyNames };
}

/**
 * Read .env.test and return the set of variable names present in the file.
 * Key values are intentionally discarded after parsing.
 *
 * @returns {string[]}  Array of variable names, e.g. ["ANTHROPIC_API_KEY", ...]
 */
function readSupportedKeyNames() {
  if (!fs.existsSync(ENV_FILE)) {
    throw new Error(`Environment file not found: ${ENV_FILE}`);
  }

  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const { keyNames } = parseEnv(content);
  return keyNames;
}

// ─── Placeholder generator ───────────────────────────────────────────────────

/**
 * Generate a new key placeholder value.
 *
 * The placeholder is intentionally NOT a real credential.  It uses a
 * cryptographically-random hex suffix so that every rotation produces a
 * distinct, unpredictable string, while remaining clearly synthetic.
 *
 * Format:  ROTATED-PLACEHOLDER-<KEYNAME>-<16-hex-bytes>
 *
 * The key *name* is embedded in the placeholder so that the origin of any
 * accidentally-surfaced placeholder is immediately traceable — without
 * revealing any real secret.
 *
 * @param {string} keyName   Variable name, e.g. "ANTHROPIC_API_KEY".
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `ROTATED-PLACEHOLDER-${keyName}-${randomHex}`;
}

// ─── Atomic .env writer ───────────────────────────────────────────────────────

/**
 * Replace the value of `keyName` inside the .env file content string and
 * return the updated content.  All other lines (including comments and
 * blank lines) are preserved byte-for-byte.
 *
 * @param {string} content      Current file content.
 * @param {string} keyName      Variable whose value should be replaced.
 * @param {string} placeholder  New placeholder value (never a real secret).
 * @returns {string}            Updated file content.
 */
function replaceKeyInContent(content, keyName, placeholder) {
  const lines  = content.split('\n');
  let   found  = false;

  const updated = lines.map(line => {
    const trimmed = line.trim();

    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) return line;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) return line;

    const name = trimmed.slice(0, eqIndex).trim();
    if (name !== keyName) return line;

    found = true;
    // Preserve any leading whitespace on the original line, then rewrite
    // name=placeholder. We do NOT carry forward the old value.
    const leadingWS = line.match(/^(\s*)/)[1];
    return `${leadingWS}${keyName}=${placeholder}`;
  });

  if (!found) {
    throw new Error(
      `Key "${keyName}" not found in ${ENV_FILE}. ` +
      'Only keys already present in .env.test can be rotated.'
    );
  }

  return updated.join('\n');
}

/**
 * Write new content to ENV_FILE atomically by:
 *   1. Writing to ENV_TMP_FILE.
 *   2. fsyncing the temp file so OS buffers are flushed to disk.
 *   3. Renaming (atomically on POSIX) the temp file over ENV_FILE.
 *
 * If any step fails the original ENV_FILE is left untouched.
 *
 * @param {string} newContent  Updated .env content.
 */
function atomicWriteEnv(newContent) {
  // Step 1 – write temp file
  fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });

  // Step 2 – fsync so the bytes are durable before we make them "live"
  const fd = fs.openSync(ENV_TMP_FILE, 'r+');
  try {
    fs.fsyncSync(fd);
  } finally {
    fs.closeSync(fd);
  }

  // Step 3 – atomic rename (POSIX rename(2) is atomic on the same filesystem)
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ─── Rotation log ─────────────────────────────────────────────────────────────

/**
 * Append a rotation event to rotation-log.json.
 *
 * The log entry contains ONLY:
 *  - ISO-8601 timestamp
 *  - key name  (NOT the value)
 *  - outcome   ("success" | "failure")
 *  - optional error message (for failures)
 *
 * @param {string}  keyName
 * @param {'success'|'failure'} outcome
 * @param {string}  [errorMessage]
 */
function appendRotationLog(keyName, outcome, errorMessage) {
  // ── safety guard: refuse to log if somehow a value slipped in ────────────
  // This check should be unreachable in normal flow, but acts as a defence-
  // in-depth backstop.
  if (typeof keyName !== 'string' || keyName.includes('=') || keyName.length > 128) {
    throw new Error('appendRotationLog received a suspicious keyName argument. Aborting.');
  }

  // Read existing log (or start fresh)
  let entries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      entries = JSON.parse(raw);
      if (!Array.isArray(entries)) entries = [];
    } catch {
      // Corrupted log — start fresh rather than crashing
      entries = [];
    }
  }

  const entry = {
    timestamp: new Date().toISOString(),
    keyName,          // variable name only — NEVER the value
    outcome,
  };

  if (outcome === 'failure' && errorMessage) {
    // Sanitise the error message: strip anything that looks like a secret
    // (long alphanumeric tokens) so that error propagation can't accidentally
    // carry a key value into the log.
    entry.error = sanitiseErrorMessage(errorMessage);
  }

  entries.push(entry);

  // Write atomically with the same tmp-then-rename pattern
  const tmpLog = LOG_FILE + '.tmp';
  fs.writeFileSync(tmpLog, JSON.stringify(entries, null, 2) + '\n', 'utf8');
  fs.renameSync(tmpLog, LOG_FILE);
}

/**
 * Scrub tokens from an error message that could be actual key material.
 * Any run of 20+ non-whitespace characters is replaced with [REDACTED].
 *
 * @param {string} msg
 * @returns {string}
 */
function sanitiseErrorMessage(msg) {
  if (typeof msg !== 'string') return String(msg);
  return msg.replace(/\S{20,}/g, '[REDACTED]');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotate the value of a single key inside .env.test.
 *
 * Steps:
 *  1. Validate that keyName is one of the supported keys from .env.test.
 *  2. Generate a new placeholder (cryptographically random, clearly synthetic).
 *  3. Rewrite .env.test atomically (tmp file → rename).
 *  4. Log the rotation event (timestamp + key name only) to rotation-log.json.
 *
 * @param {string} keyName  The variable name to rotate, e.g. "ANTHROPIC_API_KEY".
 * @returns {{ keyName: string, timestamp: string }}
 *   Metadata about the rotation.  The new placeholder value is intentionally
 *   NOT returned so callers cannot accidentally log it.
 *
 * @throws {Error} if keyName is not found in .env.test, or if the file
 *   cannot be written.
 */
function rotateKey(keyName) {
  // ── 1. Validate ───────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || !keyName.trim()) {
    throw new Error('rotateKey: keyName must be a non-empty string.');
  }
  const normalised  = keyName.trim();
  const supported   = readSupportedKeyNames();

  if (!supported.includes(normalised)) {
    const safeList = supported.join(', ');
    throw new Error(
      `rotateKey: "${normalised}" is not a recognised key in ${ENV_FILE}. ` +
      `Supported keys: ${safeList}`
    );
  }

  const timestamp = new Date().toISOString();

  try {
    // ── 2. Generate placeholder ─────────────────────────────────────────────
    const placeholder = generatePlaceholder(normalised);

    // ── 3. Read → patch → atomic write ──────────────────────────────────────
    const originalContent = fs.readFileSync(ENV_FILE, 'utf8');
    const updatedContent  = replaceKeyInContent(originalContent, normalised, placeholder);
    atomicWriteEnv(updatedContent);

    // ── 4. Log success (key name + timestamp only) ───────────────────────────
    appendRotationLog(normalised, 'success');

    console.log(`[key-rotation] ✔ Rotated key "${normalised}" at ${timestamp}`);

    // Return metadata only — the placeholder itself is NOT returned
    return { keyName: normalised, timestamp };

  } catch (err) {
    // Clean up temp file if it was left behind
    try { if (fs.existsSync(ENV_TMP_FILE)) fs.unlinkSync(ENV_TMP_FILE); } catch { /* ignore */ }

    // Log the failure — sanitised error message, no key values
    appendRotationLog(normalised, 'failure', err.message);

    console.error(`[key-rotation] ✖ Failed to rotate key "${normalised}" at ${timestamp}: ${sanitiseErrorMessage(err.message)}`);
    throw err;
  }
}

/**
 * Return the list of key names that are eligible for rotation.
 * Useful for callers that need to enumerate rotateable keys without
 * reading the .env file directly.
 *
 * @returns {string[]}
 */
function listRotatableKeys() {
  return readSupportedKeyNames();
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, listRotatableKeys };

