// ── TEST 4: unique placeholders per rotation ──────────────────────────────────
console.log('\n── Test 4: placeholder uniqueness');
const v1 = fs.readFileSync(ENV,'utf8').split('\n')
  .find(l=>l.startsWith('ANTHROPIC_API_KEY=')).split('=')[1];
rotateKey('ANTHROPIC_API_KEY');
const v2 = fs.readFileSync(ENV,'utf8').split('\n')
  .find(l=>l.startsWith('ANTHROPIC_API_KEY=')).split('=')[1];
assert(v1 !== v2, 'consecutive rotations produce different placeholders');

// ── TEST 5: atomicity ─────────────────────────────────────────────────────────
console.log('\n── Test 5: atomicity — no leftover .tmp file');
assert(!fs.existsSync(ENV + '.tmp'), '.env.test.tmp absent after success');

// ── TEST 6: rotation-log.json contents ───────────────────────────────────────
console.log('\n── Test 6: rotation-log.json');
const log    = JSON.parse(fs.readFileSync(LOG, 'utf8'));
const logStr = fs.readFileSync(LOG, 'utf8');

// At this point: ANTHROPIC rotated in tests 2+4 (2 times), STRIPE once = 3 success entries
assert(Array.isArray(log),   'log is a JSON array');
assert(log.length >= 3,      `log has ≥ 3 entries (got ${log.length})`);

// No secret material must appear anywhere in the log file
assert(!logStr.includes('REDACTED_ANTHROPIC_KEY'),      'ANTHROPIC canary absent from log');
assert(!logStr.includes('REDACTED_STRIPE_LIVE'),      'STRIPE canary absent from log');
assert(!logStr.includes('CANARY-aws-secret'),   'AWS canary absent from log');
assert(!logStr.includes('CANARY-db-secret'),    'DB canary absent from log');
assert(!logStr.includes('ROTATED-PLACEHOLDER'), 'placeholder values absent from log');

for (const entry of log) {
  assert(typeof entry.timestamp === 'string', `entry.timestamp is string`);
  assert(typeof entry.keyName   === 'string', `entry.keyName is string`);
  assert(entry.outcome === 'success' || entry.outcome === 'failure',
         `entry.outcome is "success" or "failure"`);
  assert(!('value' in entry), 'no "value" field in log entry');
}
console.log('  Sample entry:', JSON.stringify(log[0]));

// ── TEST 7: unknown key name rejected ─────────────────────────────────────────
console.log('\n── Test 7: unknown key rejected');
let caught;
try {
  rotateKey('NONEXISTENT_KEY_XYZ');
  assert(false, 'should have thrown');
} catch (e) {
  caught = e;
  assert(e.message.includes('not a recognised key'), 'error mentions unrecognised key');
  assert(!e.message.includes('CANARY'),              'error message contains no canary values');
}

// ── TEST 8: failure event is logged ───────────────────────────────────────────
console.log('\n── Test 8: failure events written to log');
const logAfterFail = JSON.parse(fs.readFileSync(LOG, 'utf8'));
const failEntry    = logAfterFail.find(e => e.outcome === 'failure');
assert(!!failEntry,                                     'failure entry exists');
assert(failEntry.keyName === 'NONEXISTENT_KEY_XYZ',     'failure entry has key name');
assert(!('value' in failEntry),                         'failure entry has no "value" field');
// Failure log string still must not contain canary material
const logStrAfterFail = fs.readFileSync(LOG, 'utf8');
assert(!logStrAfterFail.includes('CANARY'), 'no canary values in log after failure');

// ── TEST 9: unrelated keys untouched ──────────────────────────────────────────
console.log('\n── Test 9: non-rotated keys are preserved');
const finalEnv = fs.readFileSync(ENV, 'utf8');
assert(finalEnv.includes('CANARY-db-secret'),   'DATABASE_URL untouched');
assert(finalEnv.includes('REDACTED_AWS_AKID'),          'AWS_ACCESS_KEY_ID untouched');
assert(finalEnv.includes('CANARY-logfire'),      'LOGFIRE_TOKEN untouched');
assert(finalEnv.includes('# Synthetic'),         'comment lines preserved');
const lineCount = originalEnv.split('\n').length;
assert(finalEnv.split('\n').length === lineCount,'line count unchanged');

// ── TEST 10: .env.test structure integrity ────────────────────────────────────
console.log('\n── Test 10: .env.test structure integrity');
const finalLines = finalEnv.split('\n').filter(l => l.trim() && !l.startsWith('#'));
const finalKeys  = finalLines.map(l => l.split('=')[0]);
const origKeys   = originalEnv.split('\n')
  .filter(l => l.trim() && !l.startsWith('#')).map(l => l.split('=')[0]);
assert(JSON.stringify(finalKeys) === JSON.stringify(origKeys),
       'all key names preserved in original order');

// ── Restore ───────────────────────────────────────────────────────────────────
fs.writeFileSync(ENV, originalEnv, 'utf8');
if (fs.existsSync(LOG)) fs.unlinkSync(LOG);

console.log('\n' + '─'.repeat(55));
console.log(allPassed ? '✅  ALL TESTS PASSED' : '❌  SOME TESTS FAILED');
process.exitCode = allPassed ? 0 : 1;
