/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Responsibilities:
 *  1. Parse .env.test to discover which key variable names exist.
 *  2. rotateKey(keyName) — replace the value for a given variable with a new
 *     placeholder, writing atomically via a tmp file + fs.rename().
 *  3. Append a structured entry to rotation-log.json recording the timestamp
 *     and key NAME only — the key value is never read, stored, or logged.
 *
 * Security invariants upheld throughout:
 *  - Actual secret values are intentionally ignored after the line-split parse.
 *  - The log entry contains only { timestamp, keyName, status }.
 *  - The tmp file is written to the same directory as the target so that the
 *    rename() is atomic on POSIX file systems (same device/inode parent).
 *  - The tmp file is unlinked on any error so no partial state is left behind.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse an .env file and return an ordered array of line descriptors.
 * Each descriptor is one of:
 *   { kind: 'pair',    key: string, raw: string }  — KEY=VALUE line
 *   { kind: 'other',   raw: string }               — comment / blank line
 *
 * The VALUE portion of each 'pair' entry is deliberately not stored in the
 * descriptor object, preventing accidental logging of secret material.
 *
 * @param {string} filePath
 * @returns {{ kind: string, key?: string, raw: string }[]}
 */
function parseEnvLines(filePath) {
  const raw     = fs.readFileSync(filePath, 'utf8');
  const lines   = raw.split('\n');
  const entries = [];

  for (const line of lines) {
    // A valid key=value line: optional export, KEY_NAME=<anything>
    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/);
    if (match) {
      entries.push({ kind: 'pair', key: match[1], raw: line });
      // match[2] (the value) is intentionally discarded here.
    } else {
      entries.push({ kind: 'other', raw: line });
    }
  }

  return entries;
}

/**
 * Return only the variable names (keys) that are present in the env file.
 *
 * @param {string} filePath
 * @returns {string[]}
 */
function readKeyNames(filePath) {
  return parseEnvLines(filePath)
    .filter(e => e.kind === 'pair')
    .map(e => e.key);
}

/**
 * Generate a fresh placeholder value for a rotated key.
 * Format:  ROTATED-<keyName>-<timestamp>-<8 random hex bytes>
 *
 * This is a placeholder suitable for test / dev environments.  In production
 * this hook is where you would call your secrets-manager SDK instead.
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const ts    = Date.now();
  const rand  = crypto.randomBytes(8).toString('hex');
  return `ROTATED-${keyName}-${ts}-${rand}`;
}

/**
 * Atomically rewrite the env file, replacing the value for `keyName` with
 * `newPlaceholder`, then rename .env.test.tmp → .env.test.
 *
 * All other lines (including other key=value pairs and comments) are preserved
 * verbatim.  The value being replaced is never read into a named variable.
 *
 * @param {string} keyName
 * @param {string} newPlaceholder
 */
function atomicWriteEnv(keyName, newPlaceholder) {
  const entries = parseEnvLines(ENV_FILE);

  let found = false;
  const newLines = entries.map(entry => {
    if (entry.kind === 'pair' && entry.key === keyName) {
      found = true;
      // Reconstruct the line with the new placeholder; old value is discarded.
      return `${entry.key}=${newPlaceholder}`;
    }
    return entry.raw;
  });

  if (!found) {
    throw new Error(`Key "${keyName}" not found in ${ENV_FILE}`);
  }

  const newContent = newLines.join('\n');

  // Write to the tmp file first.
  try {
    fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });
  } catch (err) {
    // Clean up tmp file if write failed partway through.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch (_) { /* ignore */ }
    throw err;
  }

  // Atomically replace the target file.
  try {
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (err) {
    // Leave tmp in place so the caller can inspect/recover; re-throw.
    throw err;
  }
}

/**
 * Append a rotation event to rotation-log.json.
 * Only the timestamp, key NAME, and status are written — never the value.
 *
 * The log file is a JSON array; if it does not exist it is created.
 * Read-modify-write here is safe for the single-process use-case this module
 * is designed for.
 *
 * @param {string}  keyName
 * @param {'success'|'failure'} status
 * @param {string}  [errorMessage]  — sanitised error text, no secret material
 */
function appendLog(keyName, status, errorMessage) {
  let entries = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      entries   = JSON.parse(raw);
      if (!Array.isArray(entries)) entries = [];
    } catch (_) {
      // Corrupted log — start fresh rather than crashing.
      entries = [];
    }
  }

  const record = {
    timestamp : new Date().toISOString(),
    keyName,       // variable NAME only, never the value
    status,
  };

  if (errorMessage) {
    record.error = errorMessage;
  }

  entries.push(record);

  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Return the list of variable names found in .env.test that are eligible for
 * rotation.  The caller uses this to know which names can be passed to
 * rotateKey().
 *
 * Only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are treated as rotation
 * candidates per the project requirements; all others are returned for
 * informational purposes but are not rotated.
 *
 * @returns {{ all: string[], rotatable: string[] }}
 */
function getRotatableKeys() {
  const ROTATABLE = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);
  const all       = readKeyNames(ENV_FILE);
  const rotatable = all.filter(k => ROTATABLE.has(k));
  return { all, rotatable };
}

/**
 * Rotate the value of a single key in .env.test.
 *
 * Steps:
 *  1. Validate that keyName is a recognised rotation target.
 *  2. Generate a new placeholder value.
 *  3. Atomically rewrite .env.test (via tmp + rename).
 *  4. Append a success entry to rotation-log.json.
 *
 * On any failure an error entry is appended to the log (with no secret
 * material) before re-throwing, so every attempt is auditable.
 *
 * @param {string} keyName  — must be 'ANTHROPIC_API_KEY' or 'STRIPE_SECRET_KEY'
 * @returns {{ keyName: string, timestamp: string }}
 */
function rotateKey(keyName) {
  if (typeof keyName !== 'string' || !keyName.trim()) {
    throw new TypeError('rotateKey: keyName must be a non-empty string');
  }

  const { rotatable } = getRotatableKeys();

  if (!rotatable.includes(keyName)) {
    const err = new Error(
      `rotateKey: "${keyName}" is not a recognised rotation target. ` +
      `Rotatable keys in .env.test: [${rotatable.join(', ')}]`
    );
    appendLog(keyName, 'failure', err.message);
    throw err;
  }

  const timestamp = new Date().toISOString();

  try {
    const placeholder = generatePlaceholder(keyName);
    atomicWriteEnv(keyName, placeholder);
    // placeholder is a local variable that is never logged or returned.
  } catch (err) {
    appendLog(keyName, 'failure', err.message);
    throw err;
  }

  appendLog(keyName, 'success');

  console.log(`[key-rotation] ${timestamp} | rotated: ${keyName} | status: success`);

  return { keyName, timestamp };
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, getRotatableKeys };

/**
 * key-rotation.test.js
 *
 * Self-contained test suite for key-rotation.js.
 * Run with:  node key-rotation.test.js
 *
 * Tests are organised into clearly labelled sections and cover:
 *  - getRotatableKeys()  : correct parsing, correct filtering
 *  - rotateKey()         : happy-path atomicity, log entries, no value leakage
 *  - Error paths         : invalid names, missing key, corrupt log recovery
 *  - Security invariants : key values never appear in the log file
 */

