    console.log(`  ✓  ${message}`);
    passed++;
  } else {
    console.error(`  ✗  ${message}`);
    failed++;
  }
}

function assertThrows(fn, expectedMessageFragment, label) {
  try {
    fn();
    console.error(`  ✗  ${label} — expected an error but none was thrown`);
    failed++;
  } catch (err) {
    if (!expectedMessageFragment || err.message.includes(expectedMessageFragment)) {
