// ---------------------------------------------------------------------------
// Test: rotateKey – security: values never exposed
// ---------------------------------------------------------------------------

console.log('\n── rotateKey – security: no value exposure ───────────────');

test('log file contains NO actual key values', () => {
  const rawEnv = fs.readFileSync(ENV_FILE, 'utf8');
  // Collect the current values from .env.test BEFORE rotation
  const valuesBefore = rawEnv
    .split('\n')
    .filter(l => l.trim() && !l.trim().startsWith('#') && l.includes('='))
    .map(l => l.slice(l.indexOf('=') + 1).trim())
    .filter(Boolean);

  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');

  // Also collect the NEW values from .env.test AFTER rotation
  const rawAfter     = fs.readFileSync(ENV_FILE, 'utf8');
  const valuesAfter  = rawAfter
    .split('\n')
    .filter(l => l.trim() && !l.trim().startsWith('#') && l.includes('='))
    .map(l => l.slice(l.indexOf('=') + 1).trim())
    .filter(Boolean);

  const allValues    = [...valuesBefore, ...valuesAfter];
  const logRaw       = fs.readFileSync(LOG_FILE, 'utf8');

  for (const v of allValues) {
    assert(
      !logRaw.includes(v),
      `Secret value leaked into rotation-log.json: ${v}`
    );
  }
});

test('log entries contain only permitted fields', () => {
  rotateKey('ANTHROPIC_API_KEY');
  const entries = readLogEntries();
  assert(entries.length > 0, 'No log entries found');

  const PERMITTED_FIELDS = new Set(['eventId', 'timestamp', 'keyName', 'action']);
  for (const entry of entries) {
    for (const key of Object.keys(entry)) {
      assert(
        PERMITTED_FIELDS.has(key),
        `Unexpected field in log entry: "${key}"`
      );
    }
  }
});

test('log entry records the correct key name', () => {
  rotateKey('STRIPE_SECRET_KEY');
  const entries = readLogEntries();
  const last    = entries[entries.length - 1];
  assert(last.keyName === 'STRIPE_SECRET_KEY', 'keyName mismatch in log');
  assert(last.action  === 'rotate',            'action mismatch in log');
});

test('log entry timestamp is a valid ISO-8601 date', () => {
  rotateKey('ANTHROPIC_API_KEY');
  const entries = readLogEntries();
  const last    = entries[entries.length - 1];
  assert(!isNaN(Date.parse(last.timestamp)),
    `Non-ISO timestamp in log: "${last.timestamp}"`);
});

test('each rotation appends a new log entry (log grows)', () => {
  rotateKey('ANTHROPIC_API_KEY');
  const countAfterFirst = readLogEntries().length;

  rotateKey('STRIPE_SECRET_KEY');
  const countAfterSecond = readLogEntries().length;

  assert(
    countAfterSecond === countAfterFirst + 1,
    `Expected ${countAfterFirst + 1} log entries, got ${countAfterSecond}`
  );
});

test('eventId values are unique across two rotations', () => {
  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('ANTHROPIC_API_KEY');
  const entries  = readLogEntries();
  const ids      = entries.map(e => e.eventId);
  const unique   = new Set(ids);
  assert(unique.size === ids.length, 'Duplicate eventId values found in log');
});

// ---------------------------------------------------------------------------
// Test: rotateKey – error handling
// ---------------------------------------------------------------------------

console.log('\n── rotateKey – error handling ────────────────────────────');

test('throws for an unknown key name', () => {
  assertThrows(
    () => rotateKey('NONEXISTENT_KEY_XYZ'),
    'not found'
  );
});

test('throws for an empty string key name', () => {
  assertThrows(() => rotateKey(''), 'non-empty string');
});

test('throws for a key name with invalid characters', () => {
  assertThrows(() => rotateKey('BAD KEY!'), 'invalid characters');
});

test('throws for a non-string key name', () => {
  assertThrows(() => rotateKey(42), 'non-empty string');
});

test('.env.test is unchanged when rotation throws (unknown key)', () => {
  const before = fs.readFileSync(ENV_FILE, 'utf8');
  try { rotateKey('DOES_NOT_EXIST'); } catch (_) { /* expected */ }
  const after  = fs.readFileSync(ENV_FILE, 'utf8');
  assert(before === after, '.env.test was modified despite a failed rotation');
});

// ---------------------------------------------------------------------------
// Summary
// ---------------------------------------------------------------------------

console.log(`\n${'─'.repeat(54)}`);
console.log(`  Results:  ${passed} passed,  ${failed} failed`);
console.log(`${'─'.repeat(54)}\n`);

if (failed > 0) process.exit(1);

