/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security guarantees
 * -------------------
 *  1. Actual secret VALUES are NEVER read into memory. The .env.test file is
 *     parsed line-by-line; only the variable NAME (left-hand side of `=`) is
 *     extracted. The right-hand side (the secret) is treated as an opaque
 *     byte-string and is replaced in-place with a new placeholder – it is
 *     never stored in a JavaScript variable, logged, or sent anywhere.
 *
 *  2. Writes are atomic: new content is written to `.env.test.tmp` first,
 *     then `fs.renameSync` replaces `.env.test` in a single syscall, so a
 *     crash mid-write cannot leave a corrupt or half-written file.
 *
 *  3. The rotation log (`rotation-log.json`) records ONLY:
 *       - ISO-8601 timestamp
 *       - key NAME (e.g. "ANTHROPIC_API_KEY")
 *       - a rotation event ID (crypto random hex, for deduplication)
 *     It never records, echoes, or derives anything from the secret value.
 *
 *  4. The generated placeholder is built from cryptographically random bytes
 *     (crypto.randomBytes) so it cannot be predicted or replayed.
 */

'use strict';

const fs      = require('fs');
const path    = require('path');
const crypto  = require('crypto');

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const TMP_FILE     = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parse an .env file and return ONLY the variable names that are present.
 * The values are intentionally discarded and never stored.
 *
 * Handles:
 *   - Blank lines
 *   - Comment lines (starting with #)
 *   - Lines of the form:  KEY=anything
 *   - Quoted values (the quote characters stay in the opaque value blob;
 *     we never inspect them)
 *
 * @param {string} raw - Raw text content of the .env file.
 * @returns {string[]} Array of environment variable names found in the file.
 */
function parseEnvNames(raw) {
  const names = [];
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    // Skip blanks and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue; // malformed line – skip safely

    const name = trimmed.slice(0, eqIdx).trim();
    // Validate: env var names must be [A-Z0-9_] (we accept lowercase too)
    if (/^[A-Za-z_][A-Za-z0-9_]*$/.test(name)) {
      names.push(name);
    }
  }
  return names;
}

/**
 * Generate a cryptographically random placeholder value.
 *
 * Format: `ROTATED-<PREFIX>-<32 hex chars>-<timestamp ms>`
 *
 * The PREFIX is derived from the key name so log entries and the file stay
 * human-readable without embedding any real secret material.
 *
 * @param {string} keyName - The environment variable name being rotated.
 * @returns {string} A new placeholder value (NOT a real secret).
 */
function generatePlaceholder(keyName) {
  const randomHex   = crypto.randomBytes(16).toString('hex'); // 32 hex chars
  const tsMs        = Date.now();
  // Use only the first segment of the key name to keep lines short
  const prefix      = keyName.split('_')[0].toUpperCase();
  return `ROTATED-${prefix}-${randomHex}-${tsMs}`;
}

/**
 * Rewrite a single key's value inside the raw .env text WITHOUT ever reading
 * the old value.  The replacement is done with a regex that matches the
 * NAME= prefix and then skips over everything up to the next newline (or
 * end-of-string), replacing only the value portion.
 *
 * @param {string} raw         - Current raw content of the .env file.
 * @param {string} keyName     - The variable name whose value should change.
 * @param {string} placeholder - The new value to write.
 * @returns {string} Updated raw content.
 * @throws {Error} If keyName is not found in the file.
 */
function replaceValueInRaw(raw, keyName, placeholder) {
  // Escape the key name for use in a regex (underscores are safe, but be
  // defensive in case the caller passes something unexpected).
  const escapedName = keyName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  // Match:  ^KEY_NAME=<anything except newline>
  // Capture group 1 = everything after '=' on that line (the old value).
  // We replace group 1 with the placeholder – the old value is never read.
  const pattern = new RegExp(`^(${escapedName}=)[^\n]*`, 'm');

  if (!pattern.test(raw)) {
    throw new Error(
      `rotateKey: key "${keyName}" not found in ${ENV_FILE}. ` +
      'Verify the key name exists in the file before rotating.'
    );
  }

  // $1 keeps "KEY_NAME="; the old value is discarded without being captured.
  return raw.replace(pattern, `$1${placeholder}`);
}

/**
 * Append a rotation event to the JSON log file.
 *
 * The log file is a JSON array stored as newline-delimited JSON entries
 * (one JSON object per line) so appending is O(1) and the file never needs
 * to be fully re-parsed.
 *
 * Logged fields:
 *   - eventId   : random hex string for deduplication / idempotency checks
 *   - timestamp : ISO-8601 UTC
 *   - keyName   : the variable name that was rotated
 *   - action    : always "rotate"
 *
 * NOT logged: old value, new value, any derivative of either value.
 *
 * @param {string} keyName  - Variable name that was rotated.
 * @param {string} eventId  - Unique event identifier (hex).
 */
function appendRotationLog(keyName, eventId) {
  const entry = {
    eventId,                          // random, for dedup – not secret
    timestamp : new Date().toISOString(),
    keyName,                          // e.g. "ANTHROPIC_API_KEY"
    action    : 'rotate',
  };

  const line = JSON.stringify(entry) + '\n';
  // appendFileSync is safe here: each line is a self-contained JSON object.
  fs.appendFileSync(LOG_FILE, line, { encoding: 'utf8', flag: 'a' });
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Read the .env.test file and return the list of environment variable names
 * that are present.  Values are never read or returned.
 *
 * This is the "discovery" step described in requirement (1): the caller can
 * inspect which keys exist before deciding which ones to rotate.
 *
 * @returns {string[]} Array of variable names, e.g.
 *                     ["ANTHROPIC_API_KEY", "STRIPE_SECRET_KEY", ...]
 */
function listKeyNames() {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  return parseEnvNames(raw);
}

/**
 * Rotate a single key by:
 *   1. Reading the current .env.test content.
 *   2. Verifying `keyName` is present in the file (name-only check).
 *   3. Generating a cryptographically random placeholder value.
 *   4. Writing the updated content atomically:
 *        a. Write to .env.test.tmp
 *        b. fsync the tmp file (flush kernel buffers to disk)
 *        c. Rename .env.test.tmp → .env.test  (atomic on POSIX systems)
 *   5. Logging the event (timestamp + keyName only) to rotation-log.json.
 *
 * The old value is NEVER stored in a variable, passed to a function, or
 * written to any file.  The new placeholder is written directly to disk and
 * is not logged.
 *
 * @param {string} keyName - The environment variable name to rotate,
 *                           e.g. "ANTHROPIC_API_KEY".
 * @returns {{ keyName: string, eventId: string, timestamp: string }}
 *          Metadata about the rotation event (no secret values).
 * @throws {Error} If keyName is not found, or if file I/O fails.
 */
function rotateKey(keyName) {
  // ── 1. Validate input ────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || !keyName.trim()) {
    throw new TypeError('rotateKey: keyName must be a non-empty string.');
  }
  if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(keyName)) {
    throw new TypeError(
      `rotateKey: keyName "${keyName}" contains invalid characters. ` +
      'Only letters, digits, and underscores are allowed.'
    );
  }

  // ── 2. Read current file content ─────────────────────────────────────────
  //    We read the raw text so we can rewrite it.  The value on the matched
  //    line is NEVER extracted into a variable.
  const rawContent = fs.readFileSync(ENV_FILE, 'utf8');

  // ── 3. Check key exists (name-only) ──────────────────────────────────────
  const names = parseEnvNames(rawContent);
  if (!names.includes(keyName)) {
    throw new Error(
      `rotateKey: key "${keyName}" was not found in ${ENV_FILE}.\n` +
      `Available keys: ${names.join(', ')}`
    );
  }

  // ── 4. Generate a fresh placeholder ──────────────────────────────────────
  //    Never derived from the old value.
  const placeholder = generatePlaceholder(keyName);
  const eventId     = crypto.randomBytes(12).toString('hex'); // 24 hex chars

  // ── 5. Build updated file content ────────────────────────────────────────
  //    replaceValueInRaw discards the old value without storing it.
  const updatedContent = replaceValueInRaw(rawContent, keyName, placeholder);

  // ── 6. Atomic write ───────────────────────────────────────────────────────
  //    a) Write to the temp file
  const tmpFd = fs.openSync(TMP_FILE, 'w', 0o600); // owner-only permissions
  try {
    fs.writeSync(tmpFd, updatedContent, 0, 'utf8');
    // b) fsync: flush kernel write buffers → durable on disk before rename
    fs.fsyncSync(tmpFd);
  } finally {
    fs.closeSync(tmpFd);
  }
  //    c) Atomic rename: replaces .env.test in a single syscall
  fs.renameSync(TMP_FILE, ENV_FILE);

  // ── 7. Log the rotation event ─────────────────────────────────────────────
  //    Only keyName, eventId, and timestamp are written.  No val

