/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security contract
 * -----------------
 *  - Actual key VALUES are never logged, printed, or included in any output.
 *  - Only key NAMES and operational metadata (timestamps, status) are recorded.
 *  - The .env.test file is updated atomically: write to .env.test.tmp, then
 *    fs.renameSync() so readers never see a half-written file.
 *  - rotation-log.json is append-safe: the file is read, updated in memory,
 *    and written atomically via a tmp file + rename.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------
const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP      = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');
const LOG_TMP      = path.resolve(__dirname, 'rotation-log.json.tmp');

// ---------------------------------------------------------------------------
// Keys that are eligible for rotation.
// Read once at module load from the live .env.test file so the module always
// reflects what is actually declared there.
// ---------------------------------------------------------------------------

/**
 * Parse an .env file and return a Set of the variable *names* found in it.
 * Lines that are blank or start with '#' are ignored.
 * Values are intentionally discarded — we only need the names.
 *
 * @param {string} filePath  Absolute path to the .env file.
 * @returns {Set<string>}
 */
function parseEnvNames(filePath) {
  const names = new Set();
  const raw = fs.readFileSync(filePath, 'utf8');
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;
    const name = trimmed.slice(0, eqIndex).trim();
    if (name) names.add(name);
  }
  return names;
}

// The set of rotateable key names discovered from .env.test at load time.
// Re-exported so callers can inspect which keys are managed.
const ROTATEABLE_KEYS = parseEnvNames(ENV_FILE);

// ---------------------------------------------------------------------------
// Placeholder generator
// ---------------------------------------------------------------------------

/**
 * Generate a new key placeholder value.
 *
 * Real rotation would call the provider's API (Anthropic, Stripe, …) and
 * receive a real secret in return.  Because this module never handles live
 * secrets we produce a clearly-labelled placeholder that is:
 *   • cryptographically random (32 bytes → 64 hex chars)
 *   • prefixed with "PLACEHOLDER-ROTATED-" so it cannot be mistaken for a
 *     real credential and will be rejected by any real API.
 *
 * @returns {string}
 */
function generatePlaceholder() {
  const randomHex = crypto.randomBytes(32).toString('hex');
  return `PLACEHOLDER-ROTATED-${randomHex}`;
}

// ---------------------------------------------------------------------------
// Atomic .env.test writer
// ---------------------------------------------------------------------------

/**
 * Read .env.test, replace the value for `keyName` with `newPlaceholder`,
 * and write back atomically (tmp → rename).
 *
 * Structural invariant: every line is reproduced verbatim except the one
 * belonging to `keyName`.  Comments and blank lines are preserved.
 *
 * @param {string} keyName         The variable name whose value is replaced.
 * @param {string} newPlaceholder  The replacement value (a placeholder string,
 *                                 never a real secret).
 * @throws {Error} If `keyName` is not found in the file.
 */
function updateEnvFile(keyName, newPlaceholder) {
  const raw   = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = raw.split('\n');

  let found = false;
  const updated = lines.map((line) => {
    const trimmed = line.trim();
    if (trimmed.startsWith('#') || !trimmed.includes('=')) return line;

    const eqIndex = trimmed.indexOf('=');
    const name    = trimmed.slice(0, eqIndex).trim();

    if (name === keyName) {
      found = true;
      // Reconstruct exactly: NAME=VALUE  (no surrounding whitespace on name)
      return `${keyName}=${newPlaceholder}`;
    }
    return line;
  });

  if (!found) {
    throw new Error(
      `rotateKey: key name "${keyName}" was not found in ${ENV_FILE}`
    );
  }

  // Atomic write: tmp file → rename
  fs.writeFileSync(ENV_TMP, updated.join('\n'), { encoding: 'utf8', flag: 'w' });
  fs.renameSync(ENV_TMP, ENV_FILE);
}

// ---------------------------------------------------------------------------
// Atomic rotation-log.json writer
// ---------------------------------------------------------------------------

/**
 * Append a rotation event record to rotation-log.json.
 *
 * The record contains:
 *   - timestamp  ISO-8601 wall-clock time of the rotation
 *   - keyName    The variable name that was rotated  (NOT its value)
 *   - status     "success" or "failure"
 *   - error      (only present on failure) the error message
 *
 * Written atomically via tmp file + rename so the log is never corrupted by a
 * partial write.
 *
 * @param {object} record
 * @param {string} record.timestamp
 * @param {string} record.keyName
 * @param {'success'|'failure'} record.status
 * @param {string} [record.error]
 */
function appendRotationLog(record) {
  // Read existing log, or start fresh.
  let entries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
    } catch {
      // Corrupted log — start a new array rather than crashing.
      entries = [];
    }
  }

  entries.push(record);

  // Atomic write: tmp file → rename
  const serialised = JSON.stringify(entries, null, 2) + '\n';
  fs.writeFileSync(LOG_TMP, serialised, { encoding: 'utf8', flag: 'w' });
  fs.renameSync(LOG_TMP, LOG_FILE);
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Rotate the placeholder value for a single key in .env.test.
 *
 * Steps
 * -----
 *  1. Validate that `keyName` is among the keys declared in .env.test.
 *  2. Generate a new random placeholder (never a real secret).
 *  3. Atomically update .env.test (write tmp → rename).
 *  4. Append a timestamped record to rotation-log.json (name only, no value).
 *
 * @param {string} keyName  The exact variable name to rotate, e.g.
 *                          "ANTHROPIC_API_KEY" or "STRIPE_SECRET_KEY".
 * @returns {{ keyName: string, timestamp: string }}
 *          Metadata about the rotation event (key name + timestamp).
 *          The new placeholder value is intentionally NOT returned.
 * @throws {Error} If `keyName` is not a recognised key in .env.test.
 */
function rotateKey(keyName) {
  // ── 1. Validate ────────────────────────────────────────────────────────────
  if (!ROTATEABLE_KEYS.has(keyName)) {
    const known = [...ROTATEABLE_KEYS].join(', ');
    const err = new Error(
      `rotateKey: "${keyName}" is not a recognised key name in ${ENV_FILE}. ` +
      `Known keys: ${known}`
    );

    // Log the failed attempt (no value involved, so safe to log keyName).
    const timestamp = new Date().toISOString();
    appendRotationLog({ timestamp, keyName, status: 'failure', error: err.message });

    throw err;
  }

  const timestamp = new Date().toISOString();

  try {
    // ── 2. Generate placeholder ───────────────────────────────────────────────
    const newPlaceholder = generatePlaceholder();
    // newPlaceholder is used locally and written to the file; it is NEVER
    // logged or included in any return value.

    // ── 3. Atomic .env.test update ────────────────────────────────────────────
    updateEnvFile(keyName, newPlaceholder);

    // ── 4. Append success log entry (key NAME only) ───────────────────────────
    appendRotationLog({ timestamp, keyName, status: 'success' });

    console.log(`[key-rotation] ${timestamp} — rotated "${keyName}" successfully.`);

    // Return metadata only; the new placeholder value is NOT exposed.
    return { keyName, timestamp };

  } catch (err) {
    // Log failure with error message (still no key value).
    appendRotationLog({ timestamp, keyName, status: 'failure', error: err.message });
    // Re-throw so callers can handle or surface the error.
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = {
  /**
   * The set of key *names* loaded from .env.test at module initialisation.
   * Exported for inspection / testing; contains names only, never values.
   */
  ROTATEABLE_KEYS,

  /**
   * Rotate the placeholder for the named key.
   * @see rotateKey
   */
  rotateKey,
};

