function readLog() {
  if (!fs.existsSync('rotation-log.json')) return [];
  return JSON.parse(fs.readFileSync('rotation-log.json', 'utf8'));
}
function pass(msg) { console.log(`  ✓  ${msg}`); }
function fail(msg) { console.error(`  ✗  ${msg}`); process.exitCode = 1; }

// ─── snapshot the file before any rotation ──────────────────────────────────
const envBefore = readEnv();
console.log('\n── .env.test BEFORE rotation ──────────────────────────────────');
console.log(envBefore);

// ─── load module ────────────────────────────────────────────────────────────
const { rotateKey, ROTATEABLE_KEYS } = require('./key-rotation');

// ── Test 1: ROTATEABLE_KEYS contains exactly the names from .env.test ────────
