  ROTATEABLE_KEYS.has(k)
    ? pass(`ROTATEABLE_KEYS contains "${k}"`)
    : fail(`ROTATEABLE_KEYS is missing "${k}"`);
}
pass(`ROTATEABLE_KEYS size = ${ROTATEABLE_KEYS.size} (expected ${expectedKeys.length})`);

