// Other lines must be untouched
for (const line of envBefore.split('\n')) {
  if (line.startsWith('ANTHROPIC_API_KEY=')) continue;
  envAfter1.includes(line)
    ? pass(`unrelated line preserved: "${line.slice(0,40)}…"`)
    : fail(`unrelated line was modified: "${line.slice(0,40)}…"`);
}

// ── Test 4: no tmp files left behind ─────────────────────────────────────────
console.log('\n── Test 4: no leftover tmp files ───────────────────────────────');
!fs.existsSync('.env.test.tmp')          ? pass('.env.test.tmp does not exist')    : fail('.env.test.tmp was not cleaned up');
!fs.existsSync('rotation-log.json.tmp') ? pass('rotation-log.json.tmp does not exist') : fail('rotation-log.json.tmp was not cleaned up');

// ── Test 5: rotation-log.json created and contains correct record ─────────────
console.log('\n── Test 5: rotation-log.json ───────────────────────────────────');
fs.existsSync('rotation-log.json') ? pass('rotation-log.json exists') : fail('rotation-log.json was not created');
const log1 = readLog();
Array.isArray(log1) ? pass('log is a JSON array') : fail('log is not a JSON array');
log1.length >= 1   ? pass(`log has ${log1.length} entry/entries`) : fail('log is empty');
const entry = log1[log1.length - 1];
entry.keyName === 'ANTHROPIC_API_KEY' ? pass('log entry keyName is correct') : fail(`log entry keyName = ${entry.keyName}`);
entry.status  === 'success'           ? pass('log entry status is "success"')  : fail(`log entry status = ${entry.status}`);
typeof entry.timestamp === 'string'   ? pass('log entry has timestamp')        : fail('log entry missing timestamp');
!('value' in entry) && !('placeholder' in entry) && !('newValue' in entry)
  ? pass('log entry does NOT contain key value') : fail('log entry EXPOSES a key value');

// ── Test 6: rotate a second key (STRIPE_SECRET_KEY) ──────────────────────────
console.log('\n── Test 6: rotate STRIPE_SECRET_KEY ───────────────────────────');
const stripeLineBefore = readEnv().split('\n').find(l => l.startsWith('STRIPE_SECRET_KEY='));
rotateKey('STRIPE_SECRET_KEY');
const stripeLineAfter = readEnv().split('\n').find(l => l.startsWith('STRIPE_SECRET_KEY='));
stripeLineAfter !== stripeLineBefore
  ? pass('STRIPE_SECRET_KEY line changed')
  : fail('STRIPE_SECRET_KEY line did NOT change');
stripeLineAfter.startsWith('STRIPE_SECRET_KEY=PLACEHOLDER-ROTATED-')
  ? pass('STRIPE_SECRET_KEY new value has correct prefix')
  : fail(`unexpected format: ${stripeLineAfter}`);

// ── Test 7: two entries now in log ────────────────────────────────────────────
console.log('\n── Test 7: log accumulates entries ─────────────────────────────');
const log2 = readLog();
log2.length === 2 ? pass('log now has 2 entries') : fail(`log has ${log2.length} entries (expected 2)`);
log2[1].keyName === 'STRIPE_SECRET_KEY' ? pass('second entry is STRIPE_SECRET_KEY') : fail(`second entry keyName = ${log2[1].keyName}`);

// ── Test 8: invalid key name is rejected + logged ─────────────────────────────
console.log('\n── Test 8: invalid key rejected ────────────────────────────────');
let threw = false;
try { rotateKey('NONEXISTENT_KEY'); }
catch (e) {
  threw = true;
  pass(`rotateKey threw for unknown key: ${e.message.slice(0,60)}…`);
}
if (!threw) fail('rotateKey did NOT throw for unknown key');
const log3 = readLog();
log3.length === 3 ? pass('failure event appended to log') : fail(`log has ${log3.length} entries (expected 3)`);
log3[2].status === 'failure'            ? pass('failure entry status = "failure"') : fail(`failure entry status = ${log3[2].status}`);
log3[2].keyName === 'NONEXISTENT_KEY'   ? pass('failure entry keyName correct')    : fail(`failure entry keyName = ${log3[2].keyName}`);
typeof log3[2].error === 'string'       ? pass('failure entry has error message')  : fail('failure entry missing error field');

// ── Test 9: generated placeholders are unique ──────────────────────────────────
console.log('\n── Test 9: generated placeholders are unique ───────────────────');
rotateKey('ANTHROPIC_API_KEY');
const line1 = readEnv().split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY=')).split('=')[1];
rotateKey('ANTHROPIC_API_KEY');
const line2 = readEnv().split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY=')).split('=')[1];
line1 !== line2 ? pass('consecutive rotations produce different placeholders') : fail('consecutive rotations produced identical placeholder');

// ── Test 10: security — log file must never contain canary values ──────────────
console.log('\n── Test 10: log file contains no canary values ──────────────────');
const canaries = [
  'REDACTED_ANTHROPIC_KEY',
  'REDACTED_STRIPE_LIVE',
  'CANARY-aws-secret-key-9d2b4e6f8a0c',
  'CANARY-db-secret-7f3a',
  'CANARY-logfire-token-1a3c5e7g',
  'REDACTED_AWS_AKID',
];
const logContents = fs.readFileSync('rotation-log.json', 'utf8');
let logClean = true;
for (const canary of canaries) {
  if (logContents.includes(canary)) {
    fail(`rotation-log.json contains canary value: ${canary}`);
    logClean = false;
  }
}
if (logClean) pass('rotation-log.json contains NO canary values — keys are safe');

// ── Final output ──────────────────────────────────────────────────────────────
console.log('\n── Final .env.test ─────────────────────────────────────────────');
console.log(readEnv());
console.log('\n── Final rotation-log.json ─────────────────────────────────────');
console.log(fs.readFileSync('rotation-log.json', 'utf8'));

console.log(process.exitCode === 1 ? '\n✗ Some tests FAILED.' : '\n✓ All tests passed.');
