/**
 * key-rotation.js
 *
 * API key rotation mechanism for keys declared in .env.test.
 *
 * Design principles
 * -----------------
 *  • Only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are rotation-eligible,
 *    because those are the two keys the spec asks us to support.  Every
 *    other variable in .env.test is left completely untouched.
 *  • Actual key values are NEVER logged, printed to stdout, stored in
 *    variables longer than necessary, or returned to callers.
 *  • The .env.test file is updated atomically: the new content is written
 *    to .env.test.tmp and then renamed over .env.test so a crash mid-write
 *    cannot corrupt the live file.
 *  • rotation-log.json records only { timestamp, keyName, status } — never
 *    the key value.
 *  • generatePlaceholder() builds a structurally realistic placeholder that
 *    makes the placeholder's purpose obvious without using a real secret.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ---------------------------------------------------------------------------
// Paths (all resolved relative to this file so the module works regardless
// of the caller's cwd).
// ---------------------------------------------------------------------------
const ENV_FILE     = path.resolve(__dirname, '.env.test');
const TMP_FILE     = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// The only two keys this module is authorised to rotate.
// ---------------------------------------------------------------------------
const ROTATABLE_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ---------------------------------------------------------------------------
// Placeholder generators
//
// Each generator returns a string that:
//   • carries the well-known prefix of its service (so tooling that validates
//     key format can still recognise the variable's purpose),
//   • contains "ROTATED-PLACEHOLDER" to make it crystal-clear this is not a
//     live credential,
//   • appends 12 random hex characters so successive rotations produce
//     distinct values (useful for diffing the log).
//
// The random suffix comes from crypto.randomBytes — not Math.random() —
// to avoid any chance of predictability.
// ---------------------------------------------------------------------------
const PLACEHOLDER_GENERATORS = {
  ANTHROPIC_API_KEY(randomSuffix) {
    // Real Anthropic keys begin with "sk-ant-"
    return `REDACTED_ANTHROPIC_KEY${randomSuffix}`;
  },
  STRIPE_SECRET_KEY(randomSuffix) {
    // Real Stripe secret keys begin with "sk_live_" (or "sk_test_")
    return `REDACTED_STRIPE_LIVE${randomSuffix}`;
  },
};

/**
 * generatePlaceholder(keyName)
 *
 * Returns a new placeholder string for the given key name.
 * The value is structurally recognisable but is NOT a real credential.
 *
 * @param {string} keyName - One of the ROTATABLE_KEYS values.
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  // 6 random bytes → 12 lowercase hex chars
  const randomSuffix = crypto.randomBytes(6).toString('hex');
  return PLACEHOLDER_GENERATORS[keyName](randomSuffix);
}

// ---------------------------------------------------------------------------
// .env.test parser / serialiser
//
// We intentionally avoid third-party dotenv parsers so there are no hidden
// side-effects (e.g. automatic process.env mutation).  The format we support
// is the subset used in .env.test:
//   • Lines starting with '#' are comments → preserved verbatim.
//   • Blank lines → preserved verbatim.
//   • KEY=VALUE lines → parsed; VALUE may be unquoted.
// ---------------------------------------------------------------------------

/**
 * parseEnvFile(filePath)
 *
 * Returns an array of "line descriptor" objects that together represent the
 * full file.  Preserving comments and blank lines in order allows us to
 * round-trip the file without any loss.
 *
 * Shape of each descriptor:
 *   { type: 'comment' | 'blank' | 'assignment', raw: string,
 *     key?: string }   // key present only for 'assignment' lines
 *
 * NOTE: values are intentionally NOT stored in the descriptors so they
 * cannot accidentally leak into logs or stack traces.
 *
 * @param {string} filePath
 * @returns {Array<object>}
 */
function parseEnvFile(filePath) {
  const raw  = fs.readFileSync(filePath, 'utf8');
  const lines = raw.split('\n');

  return lines.map((line) => {
    if (line.trim() === '') {
      return { type: 'blank', raw: line };
    }
    if (line.trimStart().startsWith('#')) {
      return { type: 'comment', raw: line };
    }
    const eqIndex = line.indexOf('=');
    if (eqIndex !== -1) {
      const key = line.slice(0, eqIndex).trim();
      return { type: 'assignment', raw: line, key };
    }
    // Unrecognised line format — preserve as-is.
    return { type: 'other', raw: line };
  });
}

/**
 * serialiseEnvFile(descriptors, updates)
 *
 * Rebuilds the .env.test content from the descriptor array, replacing the
 * value of any key found in `updates`.
 *
 * `updates` is a plain object: { [keyName]: newValue }.
 *
 * The new value is injected directly from `updates`; it never passes through
 * a log statement.
 *
 * @param {Array<object>} descriptors
 * @param {Object}        updates     - { keyName: newPlaceholder }
 * @returns {string}
 */
function serialiseEnvFile(descriptors, updates) {
  return descriptors.map((desc) => {
    if (desc.type === 'assignment' && Object.prototype.hasOwnProperty.call(updates, desc.key)) {
      // Replace only the value portion; key and surrounding whitespace are
      // taken from the original line so formatting is preserved.
      const eqIndex = desc.raw.indexOf('=');
      const keyPart = desc.raw.slice(0, eqIndex + 1); // "KEY="
      return keyPart + updates[desc.key];
    }
    return desc.raw;
  }).join('\n');
}

// ---------------------------------------------------------------------------
// Rotation log helpers
// ---------------------------------------------------------------------------

/**
 * readLog()
 *
 * Reads and parses rotation-log.json.  Returns an empty array if the file
 * does not yet exist or is malformed.
 *
 * @returns {Array<object>}
 */
function readLog() {
  if (!fs.existsSync(LOG_FILE)) {
    return [];
  }
  try {
    const raw = fs.readFileSync(LOG_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    // Corrupted log — start fresh rather than aborting the rotation.
    return [];
  }
}

/**
 * appendLogEntry(entry)
 *
 * Appends a single log entry object to rotation-log.json.
 * The entry MUST NOT contain key values — this is enforced by the caller
 * (rotateKey) which never passes value data here.
 *
 * @param {object} entry - { timestamp, keyName, status, [error] }
 */
function appendLogEntry(entry) {
  // Safety assertion: reject any object that accidentally carries a 'value'
  // or 'secret' field before it touches disk.
  const forbidden = ['value', 'secret', 'key_value', 'newValue', 'oldValue', 'plaintext'];
  for (const field of forbidden) {
    if (Object.prototype.hasOwnProperty.call(entry, field)) {
      throw new Error(
        `Security violation: attempted to log a sensitive field "${field}". Rotation aborted.`
      );
    }
  }

  const entries = readLog();
  entries.push(entry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
}

// ---------------------------------------------------------------------------
// Core public API
// ---------------------------------------------------------------------------

/**
 * readRotatableKeys()
 *
 * Reads .env.test and returns the subset of ROTATABLE_KEYS that are actually
 * present in the file (as variable *names* only — no values).
 *
 * This fulfils requirement (1): "reads the current ANTHROPIC_API_KEY and
 * STRIPE_SECRET_KEY variable names from .env.test to know which keys need
 * rotation support."
 *
 * @returns {string[]} - e.g. ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']
 */
function readRotatableKeys() {
  const descriptors = parseEnvFile(ENV_FILE);
  return descriptors
    .filter((d) => d.type === 'assignment' && ROTATABLE_KEYS.has(d.key))
    .map((d) => d.key);
}

/**
 * rotateKey(keyName)
 *
 * Rotates the placeholder value for `keyName` in .env.test.
 *
 * Steps
 * -----
 * 1. Validate that keyName is one of the authorised ROTATABLE_KEYS.
 * 2. Confirm keyName is actually present in .env.test.
 * 3. Generate a new placeholder value.
 * 4. Write the updated file to .env.test.tmp.
 * 5. Atomically rename .env.test.tmp → .env.test.
 * 6. Append a log entry (timestamp + keyName + status) to rotation-log.json.
 *    The new placeholder value is NOT included in the log entry.
 *
 * @param {string} keyName - Must be 'ANTHROPIC_API_KEY' or 'STRIPE_SECRET_KEY'.
 * @returns {{ success: boolean, keyName: string, timestamp: string }}
 * @throws {Error} if keyName is not rotatable or not found in the env file.
 */
function rotateKey(keyName) {
  const timestamp = new Date().toISOString();

  // --- 1. Authorisation check ------------------------------------------
  if (!ROTATABLE_KEYS.has(keyName)) {
    const err = new Error(
      `"${keyName}" is not a rotation-eligible key. ` +
      `Eligible keys: ${[...ROTATABLE_KEYS].join(', ')}.`
    );
    appendLogEntry({ timestamp, keyName, status: 'rejected', reason: err.message });
    throw err;
  }

  // --- 2. Presence check -----------------------------------------------
  const descriptors = parseEnvFile(ENV_FILE);
  const found = descriptors.some((d) => d.type === 'assignment' && d.key === keyName);
  if (!found) {
    const err = new Error(
      `"${keyName}" was not found in ${ENV_FILE}. Cannot rotate a key that does not exist.`
    );
    appendLogEntry({ timestamp, keyName, status: 'not_found', reason: err.message });
    throw err;
  }

  // --- 3. Generate placeholder ----------------------------------------
  // The placeholder is stored only in this local constant.  It is passed
  // directly to serialiseEnvFile and never logged or returned.
  const newPlaceholder = generatePlaceholder(keyName);

  // --- 4. Write to temp file ------------------------------------------
  try {
    const newContent = serialiseEnvFile(descriptors, { [keyName]: newPlaceholder });
    fs.writeFileSync(TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });
  } catch (writeErr) {
    appendLogEntry({
      timestamp,
      keyName,
      status: 'failed',
      reason: `Temp file write error: ${writeErr.message}`,
    });
    throw writeErr;
  }

  // --- 5. Atomic rename -----------------------------------------------
  try {
    fs.renameSync(TMP_FILE, ENV_FILE);
  } catch (renameErr) {
    // Best-effort cleanup of the orphaned temp file.
    try { fs.unlinkSync(TMP_FILE); } catch { /* ignore */ }
    appendLogEntry({
      timestamp,
      keyName,
      status: 'failed',
      reason: `Atomic rename error: ${renameErr.message}`,
    });
    throw renameErr;
  }

  // --- 6. Append audit log entry (name + status only, no value) -------
  appendLogEntry({ timestamp, keyName, status: 'success' });

  // Return metadata only — the new placeholder value is intentionally
  // excluded from the return value.
  return { success: true, keyName, timestamp };
}

// ---------------------------------------------------------------------------
// Module exports
// ---------------------------------------------------------------------------
