/**
 * key-rotation.js
 *
 * API key rotation mechanism for keys declared in .env.test.
 *
 * Security principles upheld throughout:
 *  - Actual key VALUES are never logged, printed, or included in any output.
 *  - Only key NAMES (e.g. "ANTHROPIC_API_KEY") and metadata appear in logs.
 *  - The .env.test file is updated atomically: write to .env.test.tmp, then
 *    rename over the target so readers never see a half-written file.
 *  - The rotation log (rotation-log.json) records timestamps and key names only.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ──────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that this module supports rotating ─────────────────────────────────
// Derived at load-time by reading .env.test and collecting key names only.

/**
 * Parse an .env file and return a Map of { keyName -> rawLineIndex }.
 * We store the ordered lines separately so we can rebuild the file later.
 *
 * @param {string} filePath
 * @returns {{ lines: string[], keyMap: Map<string, number> }}
 */
function parseEnvFile(filePath) {
  const raw   = fs.readFileSync(filePath, 'utf8');
  const lines = raw.split('\n');

  // Map from key name → line index (so we can do targeted replacement later)
  const keyMap = new Map();

  lines.forEach((line, idx) => {
    // Match non-comment lines that contain KEY=<anything>
    const match = line.match(/^([A-Z][A-Z0-9_]*)=/);
    if (match) {
      keyMap.set(match[1], idx);
    }
  });

  return { lines, keyMap };
}

/**
 * Read the .env.test file and return only the key *names* that are flagged
 * for rotation support (ANTHROPIC_API_KEY and STRIPE_SECRET_KEY).
 *
 * @returns {string[]}  Array of supported key names present in the file.
 */
function getRotatableKeyNames() {
  const ROTATION_CANDIDATES = new Set([
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
  ]);

  const { keyMap } = parseEnvFile(ENV_FILE);

  // Intersect the candidates with what actually exists in the file.
  const found = [];
  for (const name of ROTATION_CANDIDATES) {
    if (keyMap.has(name)) {
      found.push(name);
    }
  }
  return found;
}

// ─── Placeholder generator ───────────────────────────────────────────────────

/**
 * Generate a new opaque key placeholder.
 *
 * In a real system this would call the provider's "create key" API and return
 * the live credential. Here we generate a cryptographically random hex string
 * so the mechanism is realistic without touching any external service.
 *
 * The placeholder value is intentionally NEVER logged anywhere.
 *
 * @param {string} keyName  The env-var name being rotated (used for prefix only).
 * @returns {string}        The new placeholder value.
 */
function generatePlaceholder(keyName) {
  // 32 random bytes → 64 hex chars gives enough entropy.
  const randomHex = crypto.randomBytes(32).toString('hex');

  // Give each key a recognisable prefix so it is easy to identify the provider.
  const prefixMap = {
    ANTHROPIC_API_KEY: 'sk-ant-',
    STRIPE_SECRET_KEY: 'sk_live_',
  };
  const prefix = prefixMap[keyName] ?? 'key-';

  return `${prefix}PLACEHOLDER-${randomHex}`;
}

// ─── Atomic file update ───────────────────────────────────────────────────────

/**
 * Replace the value of `keyName` inside the .env.test file atomically.
 *
 * Steps:
 *   1. Read and parse the current .env.test.
 *   2. Build the new file content (value replaced, all other lines untouched).
 *   3. Write the new content to .env.test.tmp.
 *   4. Rename .env.test.tmp → .env.test  (atomic on POSIX systems).
 *
 * The new value is accepted as a parameter; this function never logs it.
 *
 * @param {string} keyName   The variable name to update.
 * @param {string} newValue  The replacement value (not logged here or anywhere).
 */
function atomicUpdateEnvFile(keyName, newValue) {
  const { lines, keyMap } = parseEnvFile(ENV_FILE);

  if (!keyMap.has(keyName)) {
    throw new Error(`Key "${keyName}" not found in ${ENV_FILE}`);
  }

  const lineIdx = keyMap.get(keyName);

  // Replace only the value portion; preserve any inline comments if present.
  // Pattern: KEY=<value>[<optional trailing comment>]
  lines[lineIdx] = lines[lineIdx].replace(
    /^([A-Z][A-Z0-9_]*=)(.*)$/,
    (_, namePart, _oldValue) => `${namePart}${newValue}`,
    // _oldValue is intentionally ignored and never stored/logged.
  );

  const newContent = lines.join('\n');

  // ① Write to the temp file first.
  fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });

  // ② Atomically rename tmp → target.
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ─── Rotation log ─────────────────────────────────────────────────────────────

/**
 * Append a rotation event to rotation-log.json.
 *
 * Logged fields (NEVER includes the key value):
 *   - timestamp   ISO-8601 string
 *   - keyName     The env-var name that was rotated
 *   - status      "success" | "failure"
 *   - error       (only on failure) the error message string
 *
 * @param {string} keyName
 * @param {'success'|'failure'} status
 * @param {string|null} [errorMessage]
 */
function appendRotationLog(keyName, status, errorMessage = null) {
  // Read the existing log array, or start fresh.
  let logEntries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        logEntries = parsed;
      }
    } catch {
      // If the file is corrupt, start a new log rather than crashing.
      logEntries = [];
    }
  }

  /** @type {object} */
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,   // variable NAME only — never the value
    status,
  };

  if (status === 'failure' && errorMessage) {
    entry.error = errorMessage;
  }

  logEntries.push(entry);

  // Write the updated log atomically via a temp file.
  const logTmp = `${LOG_FILE}.tmp`;
  fs.writeFileSync(logTmp, JSON.stringify(logEntries, null, 2) + '\n', {
    encoding: 'utf8',
    flag: 'w',
  });
  fs.renameSync(logTmp, LOG_FILE);
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotate the key identified by `keyName`.
 *
 * 1. Validates that `keyName` is in the supported rotation set AND present
 *    in .env.test (reading only names, never values).
 * 2. Generates a new opaque placeholder value in memory.
 * 3. Updates .env.test atomically (tmp-then-rename).
 * 4. Logs the event (name + timestamp only) to rotation-log.json.
 *
 * Throws if `keyName` is not supported or not present in the file.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ keyName: string, timestamp: string }}
 *   Metadata about the rotation — does NOT include the new key value.
 */
function rotateKey(keyName) {
  const rotatableNames = getRotatableKeyNames();

  if (!rotatableNames.includes(keyName)) {
    const err = new Error(
      `"${keyName}" is not a supported rotatable key. ` +
      `Supported keys present in .env.test: [${rotatableNames.join(', ')}]`,
    );
    appendRotationLog(keyName, 'failure', err.message);
    throw err;
  }

  try {
    // Generate the new value in memory only — it is passed directly into the
    // file-update function and is never assigned to a logged variable.
    atomicUpdateEnvFile(keyName, generatePlaceholder(keyName));

    const timestamp = new Date().toISOString();
    appendRotationLog(keyName, 'success');

    console.log(`[key-rotation] Rotated ${keyName} at ${timestamp}`);

    // Return metadata only — the caller receives no key material.
    return { keyName, timestamp };
  } catch (err) {
    appendRotationLog(keyName, 'failure', err.message);
    // Re-throw so the caller knows the rotation failed.
    throw err;
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  rotateKey,
  getRotatableKeyNames, // useful for callers who want to enumerate supported keys
};

/**
 * key-rotation.test.js
 *
 * Tests for the key-rotation module.
 * Runs against a temporary copy of .env.test so the real file is never mutated
 * by the test suite.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const assert = require('assert');

// ─── Helpers ─────────────────────────────────────────────────────────────────

const ORIG_ENV_FILE = path.resolve(__dirname, '.env.test');
const ORIG_LOG_FILE = path.resolve(__dirname, 'rotation-log.json');

/**
 * Back up a file to <file>.bak if it exists.
 */
function backup(filePath) {
  if (fs.existsSync(filePath)) {
    fs.copyFileSync(filePath, `${filePath}.bak`);
  }
}

/**
 * Restore a file from <file>.bak and remove the backup.
 */
function restore(filePath) {
  const bak = `${filePath}.bak`;
  if (fs.existsSync(bak)) {
    fs.copyFileSync(bak, filePath);
    fs.unlinkSync(bak);
  }
}

/**
 * Remove a file if it exists (used for log cleanup).
 */
function removeIfExists(filePath) {
  if (fs.existsSync(filePath)) fs.unlinkSync(filePath);
}

// ─── Test runner (minimal, no external deps) ─────────────────────────────────

let passed = 0;
let failed = 0;

function test(description, fn) {
  // Back up .env.test and rotation-log.json before every test.
  backup(ORIG_ENV_FILE);
  removeIfExists(ORIG_LOG_FILE);

  // Re-require key-rotation so module-level state (cached requires, etc.)
  // is reset between tests.
  delete require.cache[require.resolve('./key-rotation')];
  const { rotateKey, getRotatableKeyNames } = require('./key-rotation');

  try {
    fn({ rotateKey, getRotatableKeyNames });
    console.log(`  ✓  ${description}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${description}`);
    console.error(`     ${err.message}`);
    failed++;
  } finally {
    restore(ORIG_ENV_FILE);
    removeIfExists(ORIG_LOG_FILE);
    // Clean up any leftover tmp files.
    removeIfExists(`${ORIG_ENV_FILE}.tmp`);
    removeIfExists(`${ORIG_LOG_FILE}.tmp`);
  }
}

// ─── Tests ───────────────────────────────────────────────────────────────────

console.log('\nkey-rotation test suite\n');

// 1. getRotatableKeyNames returns exactly the two supported keys.
test('getRotatableKeyNames returns ANTHROPIC_API_KEY and STRIPE_SECRET_KEY', ({ getRotatableKeyNames }) => {
  const names = getRotatableKeyNames();
  assert.ok(Array.isArray(names), 'should return an array');
  assert.ok(names.includes('ANTHROPIC_API_KEY'), 'should include ANTHROPIC_API_KEY');
  assert.ok(names.includes('STRIPE_SECRET_KEY'),  'should include STRIPE_SECRET_KEY');
});

// 2. getRotatableKeyNames does NOT return unsupported keys.
test('getRotatableKeyNames does not return unsupported keys', ({ getRotatableKeyNames }) => {
  const names = getRotatableKeyNames();
  const UNSUPPORTED = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'LOGFIRE_TOKEN'];
  for (const key of UNSUPPORTED) {
    assert.ok(!names.includes(key), `should NOT include ${key}`);
  }
});

// 3. rotateKey replaces the value line in .env.test.
test('rotateKey updates the value in .env.test', ({ rotateKey }) => {
  const originalContent = fs.readFileSync(ORIG_ENV_FILE, 'utf8');
  const originalLine = originalContent.split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));
  assert.ok(originalLine, 'fixture must have ANTHROPIC_API_KEY');
  const originalValue = originalLine.split('=').slice(1).join('=');

  rotateKey('ANTHROPIC_API_KEY');

  const newContent = fs.readFileSync(ORIG_ENV_FILE, 'utf8');
  const newLine = newContent.split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));
  assert.ok(newLine, '.env.test must still contain ANTHROPIC_API_KEY after rotation');
  const newValue = newLine.split('=').slice(1).join('=');

  assert.notStrictEqual(newValue, originalValue, 'value must change after rotation');
  assert.ok(newValue.startsWith('sk-ant-'), 'new ANTHROPIC placeholder should start with sk-ant-');
});

// 4. rotateKey for STRIPE_SECRET_KEY uses the correct prefix.
test('rotateKey for STRIPE_SECRET_KEY uses sk_live_ prefix', ({ rotateKey }) => {
  rotateKey('STRIPE_SECRET_KEY');
  const content = fs.readFileSync(ORIG_ENV_FILE, 'utf8');
  const line = content.split('\n').find(l => l.startsWith('STRIPE_SECRET_KEY='));
  const value = line.split('=').slice(1).join('=');
  assert.ok(value.startsWith('sk_live_'), 'STRIPE placeholder should start with sk_live_');
});

// 5. Rotating one key must not affect any other line.
test('rotateKey leaves all other .env.test lines unchanged', ({ rotateKey }) => {
  const before = fs.readFileSync(ORIG_ENV_FILE, 'utf8').split('\n');

  rotateKey('ANTHROPIC_API_KEY');

  const after = fs.readFileSync(ORIG_ENV_FILE, 'utf8').split('\n');

  assert.strictEqual(before.length, after.length, 'line count must be the same');

  before.forEach((line, idx) => {
    if (line.startsWith('ANTHROPIC_API_KEY=')) return; // this line is expected to change
    assert.strictEqual(after[idx], line, `line ${idx} should be unchanged: "${line}"`);
  });
});

// 6. No tmp file is left behind after a successful rotation.
test('no .env.test.tmp file remains after successful rotation', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  assert.ok(
    !fs.existsSync(`${ORIG_ENV_FILE}.tmp`),
    '.env.test.tmp must be cleaned up after atomic rename',
  );
});

// 7. rotation-log.json is created and has the right shape (no values logged).
test('rotation-log.json is created with correct metadata after rotation', ({ rotateKey }) => {
  assert.ok(!fs.existsSync(ORIG_LOG_FILE), 'log should not exist before first rotation');

  const result = rotateKey('ANTHROPIC_API_KEY');

  assert.ok(fs.existsSync(ORIG_LOG_FILE), 'rotation-log.json should be created');

  const log = JSON.parse(fs.readFileSync(ORIG_LOG_FILE, 'utf8'));
  assert.ok(Array.isArray(log), 'log must be an array');
  assert.strictEqual(log.length, 1, 'log must have exactly one entry');

  const entry = log[0];
  assert.strictEqual(entry.keyName, 'ANTHROPIC_API_KEY', 'keyName must match');
  assert.strictEqual(entry.status, 'success', 'status must be "success"');
  assert.ok(entry.timestamp, 'timestamp must be present');
  // Validate ISO-8601 format.
  assert.ok(!isNaN(Date.parse(entry.timestamp)), 'timestamp must be valid ISO-8601');

  // ── Safety: ensure the log entry contains no key material ──────────────
  const entrySerialized = JSON.stringify(entry);
  const envContent = fs.readFileSync(ORIG_ENV_FILE, 'utf8');
  const keyLine = envContent.split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));
  const keyValue = keyLine.split('=').slice(1).join('=');
  assert.ok(
    !entrySerialized.includes(keyValue),
    'log entry must NOT contain the actual key value',
  );
});

// 8. rotateKey return value contains only metadata, never the key value.
test('rotateKey return value does not include the new key value', ({ rotateKey }) => {
  const result = rotateKey('STRIPE_SECRET_KEY');

  assert.ok(result.keyName,   'result must have keyName');
  assert.ok(result.timestamp, 'result must have timestamp');
  assert.strictEqual(Object.keys(result).length, 2, 'result must have exactly 2 fields');

  // Read back the new value and confirm it is NOT in the result object.
  const envContent = fs.readFileSync(ORIG_ENV_FILE, 'utf8');
  const keyLine    = envContent.split('\n').find(l => l.startsWith('STRIPE_SECRET_KEY='));
  const keyValue   = keyLine.split('=').slice(1).join('=');
  assert.ok(
    !JSON.stringify(result).includes(keyValue),
    'rotateKey return value must NOT contain the new key value',
  );
});

// 9. Multiple rotations accumulate entries in the log.
test('multiple rotations accumulate log entries', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');
  rotateKey('ANTHROPIC_API_KEY');

  const log = JSON.parse(fs.readFileSync(ORIG_LOG_FILE, 'utf8'));
  assert.strictEqual(log.length, 3, 'log must have three entries');
  assert.strictEqual(log[0].keyName, 'ANTHROPIC_API_KEY');
  assert.strictEqual(log[1].keyName, 'STRIPE_SECRET_KEY');
  assert.strictEqual(log[2].keyName, 'ANTHROPIC_API_KEY');
});

// 10. Each rotation produces a distinct placeholder value.
test('successive rotations of the same key produce different values', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  const content1 = fs.readFileSync(ORIG_ENV_FILE, 'utf8');
  const line1 = content1.split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));
  const value1 = line1.split('=').slice(1).join('=');

  rotateKey('ANTHROPIC_API_KEY');
  const content2 = fs.readFileSync(ORIG_ENV_FILE, 'utf8');
  const line2 = content2.split('\n').find(l => l.startsWith('ANTHROPIC_API_KEY='));
  const value2 = line2.split('=').slice(1).join('=');

  assert.notStrictEqual(value1, value2, 'two successive rotations must yield different values');
});

// 11. Unsupported key name is rejected with a clear error.
test('rotateKey throws for unsupported key name', ({ rotateKey }) => {
  assert.throws(
    () => rotateKey('DATABASE_URL'),
    /not a supported rotatable key/,
    'should throw with an informative message',
  );
});

// 12. Unsupported key rejection is logged as a failure.
test('failed rotation is logged with status "failure"', ({ rotateKey }) => {
  try { rotateKey('AWS_ACCESS_KEY_ID'); } catch { /* expected */ }

  const log = JSON.parse(fs.readFileSync(ORIG_LOG_FILE, 'utf8'));
  assert.strictEqual(log.length, 1);
  assert.strictEqual(log[0].status, 'failure');
  assert.strictEqual(log[0].keyName, 'AWS_ACCESS_KEY_ID');
  assert.ok(log[0].error, 'failure entry must include an error message');
  // Error message must not reference key values.
  const envContent = fs.readFileSync(ORIG_ENV_FILE, 'utf8');
  for (const line of envContent.split('\n')) {
    const match = line.match(/^([A-Z][A-Z0-9_]*)=(.+)$/);
    if (match) {
      assert.ok(
        !log[0].error.includes(match[2]),
        `error message must not contain the value of ${match[1]}`,
      );
    }
  }
});

// 13. The .env.test file content never leaks into rotation-log.json.
test('rotation-log.json never contains any .env.test values', ({ rotateKey }) => {
  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');

  const logText    = fs.readFileSync(ORIG_LOG_FILE, 'utf8');
  const envContent = fs.readFileSync(ORIG_ENV_FILE, 'utf8');

  for (const line of envContent.split('\n')) {
    const match = line.match(/^([A-Z][A-Z0-9_]*)=(.+)$/);
    if (match) {
      assert.ok(
        !logText.includes(match[2]),
        `rotation-log.json must NOT contain the value of ${match[1]}`,
      );
    }
  }
});

// ─── Summary ─────────────────────────────────────────────────────────────────

console.log(`\n${passed + failed} tests: ${passed} passed, ${failed} failed.\n`);
if (failed > 0) process.exit(1);

