  // Pattern: KEY=<value>[<optional trailing comment>]
  lines[lineIdx] = lines[lineIdx].replace(
    /^([A-Z][A-Z0-9_]*=)(.*)$/,
    (_, namePart, _oldValue) => `${namePart}${newValue}`,
    // _oldValue is intentionally ignored and never stored/logged.
  );

  const newContent = lines.join('\n');

  // ① Write to the temp file first.
  fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });

  // ② Atomically rename tmp → target.
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ─── Rotation log ─────────────────────────────────────────────────────────────

/**
 * Append a rotation event to rotation-log.json.
 *
 * Logged fields (NEVER includes the key value):
 *   - timestamp   ISO-8601 string
 *   - keyName     The env-var name that was rotated
 *   - status      "success" | "failure"
 *   - error       (only on failure) the error message string
 *
 * @param {string} keyName
 * @param {'success'|'failure'} status
 * @param {string|null} [errorMessage]
 */
function appendRotationLog(keyName, status, errorMessage = null) {
  // Read the existing log array, or start fresh.
  let logEntries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        logEntries = parsed;
      }
    } catch {
      // If the file is corrupt, start a new log rather than crashing.
      logEntries = [];
    }
  }

  /** @type {object} */
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,   // variable NAME only — never the value
    status,
  };

  if (status === 'failure' && errorMessage) {
    entry.error = errorMessage;
  }

  logEntries.push(entry);

  // Write the updated log atomically via a temp file.
  const logTmp = `${LOG_FILE}.tmp`;
  fs.writeFileSync(logTmp, JSON.stringify(logEntries, null, 2) + '\n', {
    encoding: 'utf8',
    flag: 'w',
  });
  fs.renameSync(logTmp, LOG_FILE);
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotate the key identified by `keyName`.
 *
 * 1. Validates that `keyName` is in the supported rotation set AND present
 *    in .env.test (reading only names, never values).
 * 2. Generates a new opaque placeholder value in memory.
 * 3. Updates .env.test atomically (tmp-then-rename).
 * 4. Logs the event (name + timestamp only) to rotation-log.json.
 *
 * Throws if `keyName` is not supported or not present in the file.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ keyName: string, timestamp: string }}
 *   Metadata about the rotation — does NOT include the new key value.
 */
function rotateKey(keyName) {
  const rotatableNames = getRotatableKeyNames();

  if (!rotatableNames.includes(keyName)) {
    const err = new Error(
      `"${keyName}" is not a supported rotatable key. ` +
      `Supported keys present in .env.test: [${rotatableNames.join(', ')}]`,
    );
    appendRotationLog(keyName, 'failure', err.message);
    throw err;
  }

  try {
    // Generate the new value in memory only — it is passed directly into the
    // file-update function and is never assigned to a logged variable.
    atomicUpdateEnvFile(keyName, generatePlaceholder(keyName));

    const timestamp = new Date().toISOString();
    appendRotationLog(keyName, 'success');

    console.log(`[key-rotation] Rotated ${keyName} at ${timestamp}`);

    // Return metadata only — the caller receives no key material.
    return { keyName, timestamp };
  } catch (err) {
    appendRotationLog(keyName, 'failure', err.message);
    // Re-throw so the caller knows the rotation failed.
    throw err;
  }
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  rotateKey,
  getRotatableKeyNames, // useful for callers who want to enumerate supported keys
};

