/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Security contract (enforced throughout this module):
 *  - Key VALUES are never read into variables beyond what is strictly required
 *    to rewrite the .env.test file line-by-line.
 *  - Key values are NEVER passed to any logging function, console output,
 *    error message, or external call.
 *  - rotation-log.json records only: timestamp, keyName, and outcome status.
 *  - The atomic write pattern (tmp file → fs.renameSync) ensures the env file
 *    is never left in a partially-written state.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Parse an .env file into an ordered array of entries so that comments,
 * blank lines, and key ordering are all preserved on rewrite.
 *
 * Each entry is one of:
 *   { type: 'pair',    key: string, raw: string }   ← assignment line
 *   { type: 'comment', raw: string }                ← # comment or blank line
 *
 * The raw value for 'pair' entries is the FULL original line. We deliberately
 * do NOT expose the parsed value — only the key name is extracted.
 */
function parseEnvLines(fileContent) {
  return fileContent.split('\n').map((line) => {
    // A valid assignment line: optional leading spaces, KEY=anything
    const match = line.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=(.*)$/);
    if (match) {
      return { type: 'pair', key: match[1], raw: line };
    }
    return { type: 'comment', raw: line };
  });
}

/**
 * Return the set of key names defined in the env file.
 * Values are intentionally discarded — we only need the names.
 *
 * @param {string} filePath
 * @returns {Set<string>}
 */
function readKeyNames(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const keyNames = new Set();
  for (const entry of parseEnvLines(content)) {
    if (entry.type === 'pair') {
      keyNames.add(entry.key);
    }
  }
  return keyNames;
}

/**
 * Generate a new placeholder value for a rotated key.
 *
 * Format: ROTATED-<keyName>-<timestamp>-<8 random hex chars>
 *
 * This is intentionally a placeholder. In a real system the caller would
 * supply the actual new credential obtained from the issuing service.
 * The placeholder format makes it obvious the value must be replaced.
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const ts    = Date.now();
  const rand  = crypto.randomBytes(4).toString('hex'); // 8 hex chars
  return `ROTATED-${keyName}-${ts}-${rand}`;
}

/**
 * Append a single rotation event to rotation-log.json.
 *
 * Logged fields (key VALUE is deliberately absent):
 *   - timestamp  : ISO-8601 string
 *   - keyName    : the variable name (e.g. "ANTHROPIC_API_KEY")
 *   - status     : "success" | "failure"
 *   - error      : error message string (only present on failure)
 *
 * @param {string} keyName
 * @param {'success'|'failure'} status
 * @param {string|null} [errorMessage]
 */
function appendRotationLog(keyName, status, errorMessage = null) {
  // Load existing log array, or start fresh.
  let log = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // Corrupted log — start a new one rather than crash.
      log = [];
    }
  }

  const entry = {
    timestamp : new Date().toISOString(),
    keyName,    // variable name only — never the value
    status,
  };
  if (errorMessage !== null) {
    entry.error = errorMessage; // error text must not contain key values
  }

  log.push(entry);
  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ─── Public API ────────────────────────────────────────────────────────────────

/**
 * Read the current .env.test file and return the names of keys that have
 * rotation support (i.e. ANTHROPIC_API_KEY and STRIPE_SECRET_KEY if present).
 *
 * @returns {{ rotatableKeys: string[], allKeys: string[] }}
 */
function getRotatableKeys() {
  // The keys we provide rotation support for, per the module specification.
  const SUPPORTED = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

  const allKeys       = [...readKeyNames(ENV_FILE)];
  const rotatableKeys = allKeys.filter((k) => SUPPORTED.has(k));

  return { rotatableKeys, allKeys };
}

/**
 * Rotate a single key in .env.test atomically.
 *
 * Steps:
 *  1. Validate that keyName is one of the supported, rotatable keys.
 *  2. Read the current env file and parse it line-by-line.
 *  3. Replace ONLY the matching key's assignment line with a new placeholder.
 *  4. Write the result to .env.test.tmp.
 *  5. Rename .env.test.tmp → .env.test  (atomic on POSIX systems).
 *  6. Log the event (name + outcome only) to rotation-log.json.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ success: boolean, keyName: string, message: string }}
 */
function rotateKey(keyName) {
  // ── 1. Guard: only rotate explicitly supported keys ────────────────────────
  const SUPPORTED = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

  if (typeof keyName !== 'string' || keyName.trim() === '') {
    const msg = 'keyName must be a non-empty string.';
    appendRotationLog(String(keyName), 'failure', msg);
    return { success: false, keyName, message: msg };
  }

  if (!SUPPORTED.has(keyName)) {
    const msg = `"${keyName}" is not in the supported rotation set ` +
                `(${[...SUPPORTED].join(', ')}).`;
    appendRotationLog(keyName, 'failure', msg);
    return { success: false, keyName, message: msg };
  }

  // ── 2. Read current file ───────────────────────────────────────────────────
  let fileContent;
  try {
    fileContent = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    const msg = `Could not read ${ENV_FILE}: ${err.code ?? err.message}`;
    appendRotationLog(keyName, 'failure', msg);
    return { success: false, keyName, message: msg };
  }

  const entries = parseEnvLines(fileContent);

  // Confirm the key actually exists in the file.
  const targetEntry = entries.find(
    (e) => e.type === 'pair' && e.key === keyName,
  );
  if (!targetEntry) {
    const msg = `Key "${keyName}" not found in ${ENV_FILE}.`;
    appendRotationLog(keyName, 'failure', msg);
    return { success: false, keyName, message: msg };
  }

  // ── 3. Build new file content — replace only the target line ───────────────
  const placeholder = generatePlaceholder(keyName);

  const newLines = entries.map((entry) => {
    if (entry.type === 'pair' && entry.key === keyName) {
      // Replace assignment; old value is never captured in a variable.
      return `${keyName}=${placeholder}`;
    }
    return entry.raw;
  });

  const newContent = newLines.join('\n');

  // ── 4 & 5. Atomic write: tmp file → rename ─────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (err) {
    // Best-effort cleanup of the tmp file.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* ignore */ }

    const msg = `Atomic write failed for "${keyName}": ${err.code ?? err.message}`;
    appendRotationLog(keyName, 'failure', msg);
    return { success: false, keyName, message: msg };
  }

  // ── 6. Log the successful rotation (name + status only) ───────────────────
  appendRotationLog(keyName, 'success');

  const msg = `Key "${keyName}" rotated successfully. ` +
              `Update the placeholder value with the real credential from your secrets provider.`;
  console.log(`[key-rotation] ${new Date().toISOString()} | ${msg}`);

  return { success: true, keyName, message: msg };
}

// ─── Module exports ────────────────────────────────────────────────────────────

module.exports = { rotateKey, getRotatableKeys };

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 *
 * Runs without any test framework — plain Node.js assertions.
 * Execute with:  node key-rotation.test.js
 */

'use strict';

const fs     = require('fs');
const path   = require('path');
const assert = require('assert');

// ─── Paths ─────────────────────────────────────────────────────────────────────

const ENV_FILE  = path.resolve(__dirname, '.env.test');
const LOG_FILE  = path.resolve(__dirname, 'rotation-log.json');
const TMP_FILE  = path.resolve(__dirname, '.env.test.tmp');

// ─── Test harness ──────────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;

function test(name, fn) {
  try {
    fn();
    console.log(`  ✓ ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗ ${name}`);
    console.error(`    ${err.message}`);
    failed++;
  }
}

// ─── Fixture helpers ──────────────────────────────────────────────────────────

const ORIGINAL_ENV = fs.readFileSync(ENV_FILE, 'utf8');

function restoreEnv() {
  fs.writeFileSync(ENV_FILE, ORIGINAL_ENV, 'utf8');
}

function removeIfExists(filePath) {
  try { fs.unlinkSync(filePath); } catch { /* ignore */ }
}

function readLog() {
  if (!fs.existsSync(LOG_FILE)) return [];
  return JSON.parse(fs.readFileSync(LOG_FILE, 'utf8'));
}

// ─── Tests ─────────────────────────────────────────────────────────────────────

console.log('\nkey-rotation.js — test suite\n');

// Fresh state before each group.
removeIfExists(LOG_FILE);
restoreEnv();

// Re-require after restoring state.
// We delete the cache entry so each require() gets a clean module.
delete require.cache[require.resolve('./key-rotation')];
const { rotateKey, getRotatableKeys } = require('./key-rotation');

// ── getRotatableKeys ──────────────────────────────────────────────────────────
console.log('getRotatableKeys()');

test('returns ANTHROPIC_API_KEY in rotatableKeys', () => {
  const { rotatableKeys } = getRotatableKeys();
  assert.ok(rotatableKeys.includes('ANTHROPIC_API_KEY'),
    'ANTHROPIC_API_KEY should be listed as rotatable');
});

test('returns STRIPE_SECRET_KEY in rotatableKeys', () => {
  const { rotatableKeys } = getRotatableKeys();
  assert.ok(rotatableKeys.includes('STRIPE_SECRET_KEY'),
    'STRIPE_SECRET_KEY should be listed as rotatable');
});

test('allKeys includes non-rotatable keys too', () => {
  const { allKeys } = getRotatableKeys();
  assert.ok(allKeys.includes('DATABASE_URL'), 'DATABASE_URL should appear in allKeys');
  assert.ok(allKeys.includes('AWS_ACCESS_KEY_ID'), 'AWS_ACCESS_KEY_ID should appear in allKeys');
});

test('rotatableKeys is a strict subset — non-supported keys are excluded', () => {
  const { rotatableKeys } = getRotatableKeys();
  assert.ok(!rotatableKeys.includes('DATABASE_URL'),
    'DATABASE_URL must not appear in rotatableKeys');
  assert.ok(!rotatableKeys.includes('AWS_ACCESS_KEY_ID'),
    'AWS_ACCESS_KEY_ID must not appear in rotatableKeys');
});

// ── rotateKey — success path ───────────────────────────────────────────────────
console.log('\nrotateKey() — success path');

test('returns success:true for ANTHROPIC_API_KEY', () => {
  restoreEnv();
  const result = rotateKey('ANTHROPIC_API_KEY');
  assert.strictEqual(result.success, true, `Expected success, got: ${result.message}`);
  assert.strictEqual(result.keyName, 'ANTHROPIC_API_KEY');
  restoreEnv();
});

test('new placeholder is written to .env.test for ANTHROPIC_API_KEY', () => {
  restoreEnv();
  rotateKey('ANTHROPIC_API_KEY');

  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const lines   = content.split('\n');
  const line    = lines.find((l) => l.startsWith('ANTHROPIC_API_KEY='));

  assert.ok(line, 'ANTHROPIC_API_KEY line must still exist in .env.test');

  const newValue = line.split('=').slice(1).join('=');
  assert.match(newValue, /^ROTATED-ANTHROPIC_API_KEY-\d+-[0-9a-f]{8}$/,
    `Placeholder format unexpected: ${newValue}`);
  restoreEnv();
});

test('original (canary) value is replaced — not left in file', () => {
  restoreEnv();
  // Read the original value for this key to confirm it is gone after rotation.
  const originalLines  = ORIGINAL_ENV.split('\n');
  const originalLine   = originalLines.find((l) => l.startsWith('ANTHROPIC_API_KEY='));
  const originalValue  = originalLine.split('=').slice(1).join('=');

  rotateKey('ANTHROPIC_API_KEY');

  const newContent = fs.readFileSync(ENV_FILE, 'utf8');
  assert.ok(!newContent.includes(originalValue),
    'Original canary value must not remain in .env.test after rotation');
  restoreEnv();
});

test('returns success:true for STRIPE_SECRET_KEY', () => {
  restoreEnv();
  const result = rotateKey('STRIPE_SECRET_KEY');
  assert.strictEqual(result.success, true);
  assert.strictEqual(result.keyName, 'STRIPE_SECRET_KEY');
  restoreEnv();
});

test('new placeholder is written to .env.test for STRIPE_SECRET_KEY', () => {
  restoreEnv();
  rotateKey('STRIPE_SECRET_KEY');

  const content = fs.readFileSync(ENV_FILE, 'utf8');
  const line    = content.split('\n').find((l) => l.startsWith('STRIPE_SECRET_KEY='));

  assert.ok(line, 'STRIPE_SECRET_KEY line must still exist');
  const newValue = line.split('=').slice(1).join('=');
  assert.match(newValue, /^ROTATED-STRIPE_SECRET_KEY-\d+-[0-9a-f]{8}$/,
    `Placeholder format unexpected: ${newValue}`);
  restoreEnv();
});

test('other keys are untouched when rotating ANTHROPIC_API_KEY', () => {
  restoreEnv();
  rotateKey('ANTHROPIC_API_KEY');

  const newContent = fs.readFileSync(ENV_FILE, 'utf8');

  // Every line from the original that is NOT the rotated key should be present verbatim.
  for (const line of ORIGINAL_ENV.split('\n')) {
    if (line.startsWith('ANTHROPIC_API_KEY=')) continue; // this one changed
    assert.ok(newContent.includes(line),
      `Non-rotated line was unexpectedly modified: "${line}"`);
  }
  restoreEnv();
});

test('comments and blank lines are preserved', () => {
  restoreEnv();
  rotateKey('ANTHROPIC_API_KEY');

  const newContent = fs.readFileSync(ENV_FILE, 'utf8');
  assert.ok(
    newContent.includes('# Synthetic test credentials'),
    'Comment line must be preserved verbatim',
  );
  restoreEnv();
});

test('no tmp file left behind after successful rotation', () => {
  restoreEnv();
  rotateKey('ANTHROPIC_API_KEY');
  assert.ok(!fs.existsSync(TMP_FILE), '.env.test.tmp must not exist after successful rotation');
  restoreEnv();
});

test('successive rotations each produce a different placeholder', () => {
  restoreEnv();
  rotateKey('ANTHROPIC_API_KEY');
  const content1 = fs.readFileSync(ENV_FILE, 'utf8');

  // Small delay so Date.now() ticks (in practice crypto randomness is sufficient,
  // but the delay guarantees the timestamp differs too).
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 5);

  rotateKey('ANTHROPIC_API_KEY');
  const content2 = fs.readFileSync(ENV_FILE, 'utf8');

  const val1 = content1.split('\n').find((l) => l.startsWith('ANTHROPIC_API_KEY=')).split('=')[1];
  const val2 = content2.split('\n').find((l) => l.startsWith('ANTHROPIC_API_KEY=')).split('=')[1];

  assert.notStrictEqual(val1, val2, 'Each rotation must produce a unique placeholder');
  restoreEnv();
});

