console.log('\nrotateKey() — failure / guard path');

test('rejects an unsupported key name', () => {
  restoreEnv();
  const result = rotateKey('DATABASE_URL');
  assert.strictEqual(result.success, false);
  assert.match(result.message, /not in the supported rotation set/);
  restoreEnv();
});

test('rejects an empty string', () => {
  const result = rotateKey('');
  assert.strictEqual(result.success, false);
  assert.match(result.message, /non-empty string/);
});

test('rejects a non-string argument', () => {
  const result = rotateKey(42);
  assert.strictEqual(result.success, false);
});

test('rejects an unknown key name not in .env.test', () => {
  const result = rotateKey('TOTALLY_UNKNOWN_KEY');
  assert.strictEqual(result.success, false);
});

test('.env.test is not modified when rotation fails (unsupported key)', () => {
  restoreEnv();
  const before = fs.readFileSync(ENV_FILE, 'utf8');
  rotateKey('DATABASE_URL');
  const after  = fs.readFileSync(ENV_FILE, 'utf8');
  assert.strictEqual(before, after, '.env.test must be unchanged after a failed rotation');
});

// ── rotation-log.json ─────────────────────────────────────────────────────────
console.log('\nrotation-log.json');

removeIfExists(LOG_FILE);

test('log file is created on first rotation', () => {
  restoreEnv();
  rotateKey('ANTHROPIC_API_KEY');
  assert.ok(fs.existsSync(LOG_FILE), 'rotation-log.json must be created');
  restoreEnv();
});

test('log entry has timestamp, keyName, and status fields', () => {
  restoreEnv();
  removeIfExists(LOG_FILE);
  rotateKey('ANTHROPIC_API_KEY');

  const log = readLog();
  assert.ok(log.length > 0, 'Log must have at least one entry');

  const entry = log[log.length - 1];
  assert.ok('timestamp' in entry,  'Entry must have a timestamp field');
  assert.ok('keyName'   in entry,  'Entry must have a keyName field');
  assert.ok('status'    in entry,  'Entry must have a status field');
  restoreEnv();
});

test('log timestamp is a valid ISO-8601 string', () => {
  restoreEnv();
  removeIfExists(LOG_FILE);
  rotateKey('ANTHROPIC_API_KEY');

  const entry = readLog().pop();
  const parsed = new Date(entry.timestamp);
  assert.ok(!isNaN(parsed.getTime()), `Timestamp is not a valid date: ${entry.timestamp}`);
  restoreEnv();
});

test('log keyName matches the rotated key — not the value', () => {
  restoreEnv();
  removeIfExists(LOG_FILE);
  rotateKey('ANTHROPIC_API_KEY');

  const entry = readLog().pop();
  assert.strictEqual(entry.keyName, 'ANTHROPIC_API_KEY');
  restoreEnv();
});

test('log status is "success" after a successful rotation', () => {
  restoreEnv();
  removeIfExists(LOG_FILE);
  rotateKey('ANTHROPIC_API_KEY');

  const entry = readLog().pop();
  assert.strictEqual(entry.status, 'success');
  restoreEnv();
});

test('log status is "failure" when rotation is rejected', () => {
  removeIfExists(LOG_FILE);
  rotateKey('DATABASE_URL');

  const entry = readLog().pop();
  assert.strictEqual(entry.status, 'failure');
});

test('log entries accumulate across multiple rotations', () => {
  restoreEnv();
  removeIfExists(LOG_FILE);
  rotateKey('ANTHROPIC_API_KEY');
  restoreEnv();
  rotateKey('STRIPE_SECRET_KEY');

  const log = readLog();
  assert.ok(log.length >= 2, `Expected ≥ 2 entries, got ${log.length}`);
  restoreEnv();
});

// ── Security: key values must not appear in the log ───────────────────────────
console.log('\nSecurity: key values must not appear in log');

test('rotation-log.json contains no canary key values', () => {
  restoreEnv();
  removeIfExists(LOG_FILE);

  // Rotate every supported key.
  rotateKey('ANTHROPIC_API_KEY');
  restoreEnv();
  rotateKey('STRIPE_SECRET_KEY');

  const logContent = fs.readFileSync(LOG_FILE, 'utf8');

  // Extract the original canary values from the backup and assert none appear in the log.
  const valuesToCheck = [];
  for (const line of ORIGINAL_ENV.split('\n')) {
    const match = line.match(/^[A-Za-z_][A-Za-z0-9_]*\s*=(.+)$/);
    if (match) valuesToCheck.push(match[1].trim());
  }

  for (const val of valuesToCheck) {
    assert.ok(!logContent.includes(val),
      `Canary value appeared in rotation-log.json — SECURITY VIOLATION: ${val}`);
  }

  restoreEnv();
});

test('placeholder values in .env.test are not the original canary values', () => {
  restoreEnv();
  const originalValues = new Set();
  for (const line of ORIGINAL_ENV.split('\n')) {
    const match = line.match(/^[A-Za-z_][A-Za-z0-9_]*\s*=(.+)$/);
    if (match) originalValues.add(match[1].trim());
  }

  rotateKey('ANTHROPIC_API_KEY');
  rotateKey('STRIPE_SECRET_KEY');

  const newContent = fs.readFileSync(ENV_FILE, 'utf8');
  for (const line of newContent.split('\n')) {
    if (!line.startsWith('ANTHROPIC_API_KEY=') && !line.startsWith('STRIPE_SECRET_KEY=')) continue;
    const val = line.split('=').slice(1).join('=');
    assert.ok(!originalValues.has(val),
      `Rotated line still contains original canary value — SECURITY VIOLATION: key value exposed`);
  }
  restoreEnv();
});

// ─── Summary ───────────────────────────────────────────────────────────────────

console.log(`\n${'─'.repeat(50)}`);
console.log(`Results: ${passed} passed, ${failed} failed`);
if (failed > 0) {
  console.error('Some tests failed.');
  process.exit(1);
} else {
  console.log('All tests passed.');
}

