/**
 * key-rotation.js
 *
 * API key rotation module for ANTHROPIC_API_KEY and STRIPE_SECRET_KEY.
 *
 * Security contract (enforced throughout):
 *   - Actual key values are NEVER logged, written to rotation-log.json,
 *     or exposed in any string that leaves this module's internal scope.
 *   - The only information recorded externally is: ISO timestamp + key NAME.
 *   - .env.test is updated atomically: write to .env.test.tmp, then
 *     fs.renameSync() replaces the original in one kernel operation so
 *     no partial-write window exists.
 *   - New placeholder values follow the same synthetic-canary format
 *     already used in .env.test so the file stays structurally consistent.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ───────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Allowed key names ────────────────────────────────────────────────────────

/**
 * The exact set of variable names this module is authorised to rotate.
 * Derived by reading .env.test at module load time so the source of truth
 * is always the file itself, not a hard-coded list.
 */
const ROTATABLE_KEYS = loadRotatableKeys();

/**
 * Reads .env.test and returns the Set of key NAMES that this module
 * manages (ANTHROPIC_API_KEY and STRIPE_SECRET_KEY).
 *
 * Only the left-hand side of each KEY=value line is inspected here;
 * the value side is intentionally discarded and never stored.
 *
 * @returns {Set<string>}
 */
function loadRotatableKeys() {
  const targetNames = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);
  const presentNames = new Set();

  const lines = readEnvLines(); // values are in memory only during this call
  for (const line of lines) {
    const { name } = parseLine(line); // parseLine intentionally drops the value
    if (name && targetNames.has(name)) {
      presentNames.add(name);
    }
  }

  if (presentNames.size === 0) {
    throw new Error(
      `key-rotation: neither ANTHROPIC_API_KEY nor STRIPE_SECRET_KEY ` +
      `was found in ${ENV_FILE}. Nothing to manage.`
    );
  }

  return presentNames; // contains only names, no values
}

// ─── .env parsing helpers ─────────────────────────────────────────────────────

/**
 * Reads .env.test and returns its lines as a plain string array.
 * Callers are responsible for limiting how long any value-bearing
 * data stays in scope.
 *
 * @returns {string[]}
 */
function readEnvLines() {
  return fs.readFileSync(ENV_FILE, 'utf8').split('\n');
}

/**
 * Parses a single .env line into its name and raw value.
 *
 * Returns { name: null, value: null } for blank lines and comments so
 * callers can skip them without branching.
 *
 * IMPORTANT: callers that do not need the value should avoid storing it.
 *
 * @param {string} line
 * @returns {{ name: string|null, value: string|null }}
 */
function parseLine(line) {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith('#')) {
    return { name: null, value: null };
  }
  const eqIndex = trimmed.indexOf('=');
  if (eqIndex === -1) {
    return { name: null, value: null };
  }
  return {
    name:  trimmed.slice(0, eqIndex).trim(),
    value: trimmed.slice(eqIndex + 1), // kept short-lived by callers
  };
}

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * Prefix map — keeps new placeholders structurally consistent with the
 * existing synthetic canary values in .env.test.
 */
const KEY_PREFIXES = {
  ANTHROPIC_API_KEY:  'REDACTED_ANTHROPIC_KEY',
  STRIPE_SECRET_KEY:  'REDACTED_STRIPE_LIVE',
};

/**
 * Generates a new placeholder value for the given key name.
 *
 * Uses 8 bytes (16 hex chars) of cryptographically random data as the
 * suffix so each placeholder is unique and unpredictable.  The result is
 * a *placeholder* — real rotation in production would call the provider's
 * key-issuance API and receive an actual credential in return.
 *
 * The returned string is used only inside rotateKey() and is written
 * directly to disk; it is never passed to any logger.
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const prefix = KEY_PREFIXES[keyName] || 'CANARY-key';
  const suffix = crypto.randomBytes(8).toString('hex'); // 16 hex chars
  return `${prefix}-${suffix}`;
}

// ─── Rotation log helpers ─────────────────────────────────────────────────────

/**
 * Reads the existing rotation log, or returns an empty array if the file
 * does not yet exist or is unparseable.
 *
 * The log file contains ONLY timestamps and key names — never values.
 *
 * @returns {Array<{timestamp: string, keyName: string}>}
 */
function readLog() {
  try {
    const raw = fs.readFileSync(LOG_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) {
      return parsed;
    }
    // Unexpected shape — reset rather than corrupt further
    console.warn('key-rotation: rotation-log.json had unexpected shape; resetting.');
    return [];
  } catch (err) {
    if (err.code === 'ENOENT') {
      return []; // first run — file does not exist yet
    }
    console.warn(`key-rotation: could not read ${LOG_FILE}: ${err.message}. Starting fresh log.`);
    return [];
  }
}

/**
 * Appends a rotation event to rotation-log.json.
 *
 * Recorded fields:
 *   - timestamp : ISO 8601 UTC string
 *   - keyName   : the variable name that was rotated (e.g. "ANTHROPIC_API_KEY")
 *
 * Nothing else — specifically NOT the old value, the new value, or any
 * derivative of either.
 *
 * @param {string} keyName
 * @returns {{ timestamp: string, keyName: string }} the event that was appended
 */
function appendLogEntry(keyName) {
  const entry = {
    timestamp: new Date().toISOString(), // UTC, e.g. "2025-06-23T08:00:00.000Z"
    keyName,                             // variable name only — never the value
  };

  const entries = readLog();
  entries.push(entry);

  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');

  return entry;
}

// ─── Atomic .env.test update ─────────────────────────────────────────────────

/**
 * Rewrites .env.test so that `keyName` maps to `newPlaceholder`, while
 * leaving every other line byte-for-byte identical.
 *
 * Atomicity guarantee:
 *   1. The new content is written to `.env.test.tmp`.
 *   2. `fs.renameSync()` replaces `.env.test` in a single kernel call.
 *      On POSIX systems this is atomic: readers either see the old file
 *      or the new file, never a partial write.
 *   3. The tmp file is removed on any error so stale temporaries do not
 *      accumulate.
 *
 * `newPlaceholder` is used ONLY inside this function to construct the
 * replacement line; it is not stored in any variable that persists
 * beyond this call frame.
 *
 * @param {string} keyName         - The variable name to update.
 * @param {string} newPlaceholder  - The replacement value string.
 */
function atomicUpdateEnv(keyName, newPlaceholder) {
  const lines = readEnvLines();
  let found = false;

  // Build updated lines. For the target key we construct a new assignment
  // line; for every other line we preserve the original text verbatim
  // (including its exact whitespace and any inline comments).
  const updatedLines = lines.map((line) => {
    const { name } = parseLine(line); // value side intentionally discarded
    if (name === keyName) {
      found = true;
      return `${keyName}=${newPlaceholder}`;
    }
    return line;
  });

  if (!found) {
    throw new Error(
      `key-rotation: "${keyName}" was not found in ${ENV_FILE}. ` +
      `Cannot update a key that does not exist.`
    );
  }

  const newContent = updatedLines.join('\n');

  // ── Step 1: write to the temporary file ───────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });
  } catch (writeErr) {
    // Clean up in case a partial file was created.
    silentUnlink(ENV_TMP_FILE);
    throw new Error(
      `key-rotation: failed to write temporary file ${ENV_TMP_FILE}: ${writeErr.message}`
    );
  }

  // ── Step 2: atomically replace the original ───────────────────────────────
  try {
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (renameErr) {
    // Leave .env.test intact; try to clean up the tmp file.
    silentUnlink(ENV_TMP_FILE);
    throw new Error(
      `key-rotation: atomic rename from ${ENV_TMP_FILE} to ${ENV_FILE} ` +
      `failed: ${renameErr.message}. Original file is unchanged.`
    );
  }
}

/**
 * Attempts to delete a file, suppressing any error.
 * Used only for tmp-file cleanup in error paths.
 *
 * @param {string} filePath
 */
function silentUnlink(filePath) {
  try { fs.unlinkSync(filePath); } catch (_) { /* intentionally suppressed */ }
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Rotates the placeholder value for `keyName` in .env.test.
 *
 * Steps:
 *   1. Validate that `keyName` is one of the managed keys discovered at
 *      module load time (ANTHROPIC_API_KEY or STRIPE_SECRET_KEY).
 *   2. Generate a new placeholder — a unique synthetic canary string.
 *   3. Atomically overwrite .env.test via a tmp-file + rename.
 *   4. Append a log entry (timestamp + key name only) to rotation-log.json.
 *   5. Return a result object that confirms success without revealing any
 *      key value.
 *
 * What this function intentionally does NOT do:
 *   - It does not log, print, or return the old or new key value.
 *   - It does not call any external API (production wiring is left to the
 *     caller so that credential handling stays outside this module).
 *
 * @param {string} keyName - Must be "ANTHROPIC_API_KEY" or "STRIPE_SECRET_KEY".
 * @returns {{
 *   success:   true,
 *   keyName:   string,
 *   timestamp: string,
 *   message:   string
 * }}
 * @throws {Error} if keyName is not managed, or if any I/O step fails.
 */
function rotateKey(keyName) {
  // ── Guard: only managed keys may be rotated ───────────────────────────────
  if (typeof keyName !== 'string' || !ROTATABLE_KEYS.has(keyName)) {
    const managed = [...ROTATABLE_KEYS].join(', ');
    throw new Error(
      `key-rotation: "${keyName}" is not a managed key. ` +
      `Managed keys are: ${managed}`
    );
  }

  // ── Generate placeholder (value never leaves this block) ──────────────────
  //    The placeholder is passed directly to atomicUpdateEnv and then the
  //    local reference goes out of scope. It is not stored, returned, or
  //    passed to any logger.
  atomicUpdateEnv(keyName, generatePlaceholder(keyName));

  // ── Record the rotation event (name + timestamp only) ─────────────────────
