'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ───────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Allowed key names ────────────────────────────────────────────────────────

/**
 * The exact set of variable names this module is authorised to rotate.
 * Derived by reading .env.test at module load time so the source of truth
 * is always the file itself, not a hard-coded list.
 */
const ROTATABLE_KEYS = loadRotatableKeys();

/**
 * Reads .env.test and returns the Set of key NAMES that this module
 * manages (ANTHROPIC_API_KEY and STRIPE_SECRET_KEY).
 *
 * Only the left-hand side of each KEY=value line is inspected here;
 * the value side is intentionally discarded and never stored.
 *
 * @returns {Set<string>}
 */
function loadRotatableKeys() {
  const targetNames = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);
  const presentNames = new Set();

  const lines = readEnvLines(); // values are in memory only during this call
  for (const line of lines) {
    const { name } = parseLine(line); // parseLine intentionally drops the value
    if (name && targetNames.has(name)) {
      presentNames.add(name);
    }
  }

  if (presentNames.size === 0) {
    throw new Error(
      `key-rotation: neither ANTHROPIC_API_KEY nor STRIPE_SECRET_KEY ` +
      `was found in ${ENV_FILE}. Nothing to manage.`
    );
  }

  return presentNames; // contains only names, no values
}

// ─── .env parsing helpers ─────────────────────────────────────────────────────

/**
 * Reads .env.test and returns its lines as a plain string array.
 * Callers are responsible for limiting how long any value-bearing
 * data stays in scope.
 *
 * @returns {string[]}
 */
function readEnvLines() {
  return fs.readFileSync(ENV_FILE, 'utf8').split('\n');
}

/**
 * Parses a single .env line into its name and raw value.
 *
 * Returns { name: null, value: null } for blank lines and comments so
 * callers can skip them without branching.
 *
 * IMPORTANT: callers that do not need the value should avoid storing it.
 *
 * @param {string} line
 * @returns {{ name: string|null, value: string|null }}
 */
function parseLine(line) {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith('#')) {
    return { name: null, value: null };
  }
  const eqIndex = trimmed.indexOf('=');
  if (eqIndex === -1) {
    return { name: null, value: null };
