/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Design principles:
 *  - Only the *names* (variable names) of keys are ever read from .env.test;
 *    the values themselves are never stored in a variable, logged, or
 *    transmitted anywhere.
 *  - The .env.test file is updated atomically: content is written to a
 *    temporary file (.env.test.tmp) which is then renamed into place, so a
 *    crash mid-write can never leave the file in a half-written state.
 *  - rotation-log.json records only the timestamp and key name — never the
 *    old or new key value.
 *  - New key values are generated as clearly-marked PLACEHOLDER strings.
 *    In a real deployment this function would call the upstream provider's
 *    key-issuance API instead; the placeholder makes it obvious that a human
 *    (or CI pipeline) must complete the rotation.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ───────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Key-name discovery ───────────────────────────────────────────────────────

/**
 * readRotatableKeyNames()
 *
 * Parses .env.test and returns the *names* of every variable that is flagged
 * for rotation support.  Currently the flag is implicit: any variable whose
 * name appears in ROTATABLE_PREFIXES is included.
 *
 * IMPORTANT: values are deliberately discarded during parsing — they are
 * never assigned to a variable or returned by this function.
 *
 * @returns {string[]}  Array of variable names, e.g. ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']
 */
function readRotatableKeyNames() {
  const ROTATABLE_PREFIXES = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];

  const raw = fs.readFileSync(ENV_FILE, 'utf8');
  const foundNames = [];

  for (const line of raw.split('\n')) {
    const trimmed = line.trim();

    // Skip blank lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;

    // Extract the variable name ONLY — everything after '=' is ignored
    const varName = trimmed.slice(0, eqIndex).trim();

    if (ROTATABLE_PREFIXES.includes(varName)) {
      foundNames.push(varName);
    }
  }

  return foundNames;
}

// ─── Placeholder generator ────────────────────────────────────────────────────

/**
 * generatePlaceholder(keyName)
 *
 * Returns a clearly-labelled placeholder string that can be committed to
 * .env.test while the real credential is obtained out-of-band.
 *
 * The placeholder includes:
 *   - A "ROTATED-PLACEHOLDER" marker so grep / secret-scanners won't mistake
 *     it for a live credential.
 *   - The key name so the placeholder is self-documenting.
 *   - A short random hex suffix so successive rotations produce distinct
 *     values and any accidental re-use is detectable.
 *
 * The random bytes are generated with crypto.randomBytes (CSPRNG).
 *
 * @param   {string} keyName  Variable name, e.g. 'ANTHROPIC_API_KEY'
 * @returns {string}          Placeholder value — NOT a real credential
 */
function generatePlaceholder(keyName) {
  const randomSuffix = crypto.randomBytes(12).toString('hex'); // 24 hex chars
  return `ROTATED-PLACEHOLDER-${keyName}-${randomSuffix}`;
}

// ─── Atomic .env.test updater ─────────────────────────────────────────────────

/**
 * updateEnvFile(keyName, newPlaceholder)
 *
 * Replaces the value of `keyName` in .env.test with `newPlaceholder` using an
 * atomic write-then-rename strategy:
 *
 *   1. Read the entire current file content.
 *   2. Build the updated content in memory (value substitution only; all
 *      other lines, comments and whitespace are preserved verbatim).
 *   3. Write to .env.test.tmp.
 *   4. fsync the file descriptor so bytes are flushed to disk.
 *   5. Close the file descriptor.
 *   6. fs.renameSync(.env.test.tmp → .env.test)  ← atomic on POSIX systems.
 *
 * If step 2 finds no matching variable the function throws rather than
 * silently writing an unchanged file, because that indicates a caller bug.
 *
 * NOTE: the *old* value is never captured in a named variable.
 *
 * @param {string} keyName         Variable name to update
 * @param {string} newPlaceholder  Replacement value (a placeholder string)
 */
function updateEnvFile(keyName, newPlaceholder) {
  const currentContent = fs.readFileSync(ENV_FILE, 'utf8');
  const lines = currentContent.split('\n');

  let matched = false;
  const updatedLines = lines.map((line) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return line;

    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) return line;

    if (trimmed.slice(0, eqIndex).trim() === keyName) {
      matched = true;
      // Preserve any leading whitespace from the original line, then
      // write   VARNAME=<newPlaceholder>   — old value is never read.
      const leadingWhitespace = line.match(/^(\s*)/)[1];
      return `${leadingWhitespace}${keyName}=${newPlaceholder}`;
    }
    return line;
  });

  if (!matched) {
    throw new Error(
      `updateEnvFile: key "${keyName}" not found in ${ENV_FILE}. ` +
      'Rotation aborted — no changes written.'
    );
  }

  const updatedContent = updatedLines.join('\n');

  // --- Atomic write ---
  // Open with 'w' (create or truncate), write, fsync, close, then rename.
  const fd = fs.openSync(ENV_TMP_FILE, 'w', 0o600);
  try {
    fs.writeSync(fd, updatedContent, 0, 'utf8');
    fs.fsyncSync(fd);        // flush OS buffer to disk before rename
  } finally {
    fs.closeSync(fd);        // always close, even if fsync fails
  }

  // Rename is atomic on POSIX; on Windows it will throw if the destination
  // exists — use a try/catch to clean up the tmp file in that case.
  try {
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (renameErr) {
    // Best-effort cleanup of the temp file before re-throwing.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch (_) { /* ignore */ }
    throw renameErr;
  }
}

// ─── Rotation logger ──────────────────────────────────────────────────────────

/**
 * appendRotationLog(keyName)
 *
 * Appends a rotation event record to rotation-log.json.
 *
 * Each record contains ONLY:
 *   - timestamp  (ISO-8601)
 *   - keyName    (variable name — NOT the value)
 *   - status     ("rotated")
 *
 * The log file is a JSON array.  If the file does not yet exist it is
 * created.  The file is read into memory, the new entry is pushed, and the
 * whole array is written back (acceptable for an audit log of modest size).
 *
 * @param {string} keyName  Variable name that was rotated
 */
function appendRotationLog(keyName) {
  let entries = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
    } catch (_parseErr) {
      // If the log file is corrupt, start fresh rather than crashing.
      entries = [];
    }
  }

  entries.push({
    timestamp: new Date().toISOString(),
    keyName,          // variable name only — value is never included
    status: 'rotated',
  });

  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * rotateKey(keyName)
 *
 * Full rotation lifecycle for a single key:
 *
 *   1. Validate that `keyName` is among the rotatable keys discovered in
 *      .env.test (guards against typos and attempts to rotate unrelated vars).
 *   2. Generate a new placeholder value.
 *   3. Atomically update .env.test.
 *   4. Append a sanitised entry to rotation-log.json.
 *   5. Return a result object — the placeholder value is included so the
 *      caller can hand it to the provisioning system; it is the caller's
 *      responsibility not to log it further.
 *
 * @param   {string} keyName  Variable name to rotate, e.g. 'ANTHROPIC_API_KEY'
 * @returns {{ keyName: string, timestamp: string, status: string, newPlaceholder: string }}
 * @throws  {Error} if keyName is not found among rotatable keys, or if file
 *                  I/O fails at any step.
 */
function rotateKey(keyName) {
  if (typeof keyName !== 'string' || !keyName.trim()) {
    throw new TypeError('rotateKey: keyName must be a non-empty string.');
  }

  // Step 1 — Validate against the known rotatable key names in .env.test
  const rotatableNames = readRotatableKeyNames();
  if (!rotatableNames.includes(keyName)) {
    throw new Error(
      `rotateKey: "${keyName}" is not a recognised rotatable key. ` +
      `Known rotatable keys: [${rotatableNames.join(', ')}]`
    );
  }

  // Step 2 — Generate placeholder (CSPRNG-backed, never a real credential)
  const newPlaceholder = generatePlaceholder(keyName);

  // Step 3 — Atomic file update
  updateEnvFile(keyName, newPlaceholder);

  // Step 4 — Audit log (key name + timestamp only, no values)
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName);

  console.log(`[key-rotation] ${timestamp} — rotated key: ${keyName} (value not logged)`);

  // Step 5 — Return result; newPlaceholder is returned for handoff to a
  //           provisioning system but is NOT written to any log here.
  return {
    keyName,
    timestamp,
    status: 'rotated',
    newPlaceholder,   // caller must treat this as a secret
  };
}

/**
 * listRotatableKeys()
 *
 * Convenience function: returns the array of key *names* eligible for
 * rotation as discovered from .env.test.
 *
 * @returns {string[]}
 */
function listRotatableKeys() {
  return readRotatableKeyNames();
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = { rotateKey, listRotatableKeys };

/**
 * key-rotation.test.js
 *
 * Tests for the key-rotation module.
 *
 * Uses only Node.js built-ins (no Jest / Mocha dependency) so it can be run
 * directly with:
 *
 *   node key-rotation.test.js
 *
 * Exit code 0 = all tests passed.
 * Exit code 1 = one or more tests failed.
 */

'use strict';

