/**
 * key-rotation.js
 *
 * API-key rotation helper.
 *
 * Design constraints
 * ------------------
 * • Only the KEY NAMES (left-hand side of KEY=value pairs) are ever read into
 *   memory from .env.test.  The corresponding values are treated as opaque
 *   byte sequences that are rewritten verbatim or replaced — they are NEVER
 *   stored in a named variable, logged, or returned to callers.
 * • rotation-log.json records timestamp + key name only.
 * • The .env.test update is atomic: we write to .env.test.tmp first, then
 *   use fs.rename() which is a single syscall on POSIX systems (no window
 *   where a reader can see a partial file).
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ── File paths ────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Parse an .env file and return ONLY the key names found in it.
 * Values are deliberately never stored; the raw line is kept so we can
 * reconstruct the file without touching entries we don't own.
 *
 * Returns an object whose shape mirrors the file structure:
 *   {
 *     keyNames : Set<string>,          // e.g. Set { 'ANTHROPIC_API_KEY', … }
 *     lines    : Array<{               // original lines, value-free metadata
 *       raw      : string,             // exact original text (for unchanged lines)
 *       isEntry  : boolean,            // true  → KEY=value line
 *       keyName  : string | null,      // key name if isEntry, else null
 *     }>
 *   }
 *
 * NOTE: `raw` contains the full original line (including the value) so the
 * file can be rewritten unchanged for unmodified entries.  We deliberately do
 * NOT extract the value into a separate field; storing it only inside `raw`
 * means callers cannot accidentally access it by field name.
 */
function parseEnvFile(filePath) {
  const content  = fs.readFileSync(filePath, 'utf8');
  const keyNames = new Set();
  const lines    = content.split('\n').map((raw) => {
    // Skip comments and blank lines
    const trimmed = raw.trim();
    if (trimmed === '' || trimmed.startsWith('#')) {
      return { raw, isEntry: false, keyName: null };
    }

    // Match KEY=…  (value intentionally not captured into a named group)
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex < 1) {
      return { raw, isEntry: false, keyName: null };
    }

    const keyName = trimmed.slice(0, eqIndex).trim();

    // Basic validation: env var names are [A-Za-z_][A-Za-z0-9_]*
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(keyName)) {
      return { raw, isEntry: false, keyName: null };
    }

    keyNames.add(keyName);
    return { raw, isEntry: true, keyName };
  });

  return { keyNames, lines };
}

/**
 * Generate a new key placeholder.
 *
 * Format:  PLACEHOLDER-<keyName>-<32 random hex chars>
 *
 * Using "PLACEHOLDER" as a prefix makes it immediately obvious in any
 * downstream system that this is a sentinel value, not a real credential.
 * The random suffix ensures uniqueness across rotations.
 *
 * @param  {string} keyName  - The environment variable name being rotated.
 * @returns {string}          - New placeholder string.
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `PLACEHOLDER-${keyName}-${randomHex}`;
}

/**
 * Append a rotation event to rotation-log.json.
 *
 * Only the key NAME and a UTC timestamp are recorded.
 * The actual key value is never passed to this function.
 *
 * @param {string} keyName - The environment variable name that was rotated.
 */
function appendRotationLog(keyName) {
  let entries = [];

  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
    } catch {
      // Corrupted log — start fresh rather than losing new entries.
      entries = [];
    }
  }

  entries.push({
    timestamp : new Date().toISOString(),   // UTC ISO-8601
    keyName,                                // variable name only — NOT the value
    event     : 'rotated',
  });

  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2) + '\n', 'utf8');
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Read the current .env.test file and return the set of key names that are
 * candidates for rotation (only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY).
 *
 * @returns {Set<string>} Set of rotateable key names present in .env.test.
 */
function getRotatableKeys() {
  const ROTATABLE = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);
  const { keyNames } = parseEnvFile(ENV_FILE);

  const found = new Set();
  for (const name of ROTATABLE) {
    if (keyNames.has(name)) {
      found.add(name);
    }
  }
  return found;
}

/**
 * Rotate a single key in .env.test.
 *
 * Steps:
 *  1. Parse .env.test, confirming keyName exists and is rotatable.
 *  2. Generate a new placeholder value.
 *  3. Rebuild the file content, substituting only the target key's value.
 *  4. Write rebuilt content to .env.test.tmp.
 *  5. Atomically rename .env.test.tmp → .env.test.
 *  6. Append a rotation event (timestamp + key name) to rotation-log.json.
 *  7. Return a result object: { keyName, rotatedAt }.
 *     The placeholder value is NOT included in the return value.
 *
 * @param  {string} keyName - The environment variable name to rotate.
 * @returns {{ keyName: string, rotatedAt: string }}
 * @throws  {Error} If keyName is not present in .env.test or is not rotatable.
 */
function rotateKey(keyName) {
  // ── 1. Validate ─────────────────────────────────────────────────────────────
  const ROTATABLE = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

  if (!ROTATABLE.has(keyName)) {
    throw new Error(
      `"${keyName}" is not in the list of rotatable keys. ` +
      `Supported keys: ${[...ROTATABLE].join(', ')}`
    );
  }

  const { keyNames, lines } = parseEnvFile(ENV_FILE);

  if (!keyNames.has(keyName)) {
    throw new Error(
      `Key "${keyName}" was not found in ${ENV_FILE}. ` +
      'Cannot rotate a key that does not exist in the env file.'
    );
  }

  // ── 2. Generate placeholder ──────────────────────────────────────────────────
  const placeholder = generatePlaceholder(keyName);
  // `placeholder` is used only to write back to the file.
  // It is intentionally NOT logged and NOT returned.

  // ── 3. Rebuild file content ──────────────────────────────────────────────────
  const newLines = lines.map(({ raw, isEntry, keyName: lineKey }) => {
    if (isEntry && lineKey === keyName) {
      // Replace this line with KEY=<placeholder>.
      // We never read the old value; we just overwrite from the '=' onward.
      return `${keyName}=${placeholder}`;
    }
    // Return every other line byte-for-byte unchanged.
    return raw;
  });

  const newContent = newLines.join('\n');

  // ── 4. Write to temp file ────────────────────────────────────────────────────
  fs.writeFileSync(ENV_TMP_FILE, newContent, { encoding: 'utf8', flag: 'w' });

  // ── 5. Atomic rename ─────────────────────────────────────────────────────────
  // fs.renameSync is backed by rename(2) on POSIX — a single atomic syscall.
  // On the same filesystem the destination is replaced instantaneously.
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);

  // ── 6. Log rotation event ────────────────────────────────────────────────────
  const rotatedAt = new Date().toISOString();
  appendRotationLog(keyName);

  // ── 7. Return safe metadata ──────────────────────────────────────────────────
  console.log(`[key-rotation] Rotated key "${keyName}" at ${rotatedAt}`);
  // Do NOT log `placeholder` or any key value here.

  return { keyName, rotatedAt };
}

// ── Module exports ────────────────────────────────────────────────────────────

module.exports = { getRotatableKeys, rotateKey };

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js
 *
 * All tests operate on isolated temp copies of .env.test so the real file is
 * never permanently modified by the test suite.
 *
 * Security invariants verified:
 *   • Actual key values never appear in rotation-log.json.
 *   • Actual key values never appear in the return value of rotateKey().
 *   • The placeholder written to .env.test is distinct on every call.
 *   • Unsupported key names are rejected.
 *   • Non-existent key names are rejected.
 *   • After rotation the file is valid (parseable, key still present).
 *   • .env.test.tmp is cleaned up after a successful rotation.
 *   • Log entries contain exactly { timestamp, keyName, event }.
 */

'use strict';

const fs     = require('fs');
const path   = require('path');
const assert = require('assert');
const crypto = require('crypto');

// ── Test infrastructure ───────────────────────────────────────────────────────

const TESTS_PASSED = [];
const TESTS_FAILED = [];

function test(name, fn) {
  try {
    fn();
    TESTS_PASSED.push(name);
    console.log(`  ✓ ${name}`);
  } catch (err) {
    TESTS_FAILED.push({ name, err });
    console.error(`  ✗ ${name}`);
    console.error(`    ${err.message}`);
  }
}

// ── Fixture helpers ───────────────────────────────────────────────────────────

const REAL_ENV     = path.resolve(__dirname, '.env.test');
const REAL_LOG     = path.resolve(__dirname, 'rotation-log.json');
const TMP_ENV      = path.resolve(__dirname, '.env.test.tmp');
const BACKUP_ENV   = path.resolve(__dirname, '.env.test.bak');
const BACKUP_LOG   = path.resolve(__dirname, 'rotation-log.json.bak');

/** Save originals so we can restore them after each test. */
function saveOriginals() {
  fs.copyFileSync(REAL_ENV, BACKUP_ENV);
  if (fs.existsSync(REAL_LOG)) {
    fs.copyFileSync(REAL_LOG, BACKUP_LOG);
  } else {
    // Mark absence
    if (fs.existsSync(BACKUP_LOG)) fs.unlinkSync(BACKUP_LOG);
  }
}

/** Restore originals and clean up temp artefacts. */
function restoreOriginals() {
  fs.copyFileSync(BACKUP_ENV, REAL_ENV);
  fs.unlinkSync(BACKUP_ENV);

  if (fs.existsSync(BACKUP_LOG)) {
    fs.copyFileSync(BACKUP_LOG, REAL_LOG);
    fs.unlinkSync(BACKUP_LOG);
  } else if (fs.existsSync(REAL_LOG)) {
    fs.unlinkSync(REAL_LOG);
  }

  if (fs.existsSync(TMP_ENV)) fs.unlinkSync(TMP_ENV);
}

/**
 * Read .env.test and return a Map of { keyName → value } so tests can inspect
 * what the file now contains.  We allow this read inside the test suite only
 * (it is never called from key-rotation.js itself).
 */
function readEnvAsMap(filePath) {
  const map = new Map();
  const lines = fs.readFileSync(filePath, 'utf8').split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const eqIdx = trimmed.indexOf('=');
    if (eqIdx < 1) continue;
    const k = trimmed.slice(0, eqIdx).trim();
    const v = trimmed.slice(eqIdx + 1);
    map.set(k, v);
  }
  return map;
}

// ── Load the module under test ────────────────────────────────────────────────

const { getRotatableKeys, rotateKey } = require('./key-rotation');

// ── Test suite ────────────────────────────────────────────────────────────────

console.log('\nkey-rotation.js — test suite\n');

// ── getRotatableKeys ──────────────────────────────────────────────────────────

console.log('getRotatableKeys()');

test('returns a Set', () => {
  const result = getRotatableKeys();
  assert.ok(result instanceof Set, 'Expected a Set');
});

test('contains ANTHROPIC_API_KEY', () => {
  const result = getRotatableKeys();
  assert.ok(result.has('ANTHROPIC_API_KEY'), 'Expected ANTHROPIC_API_KEY in set');
});

test('contains STRIPE_SECRET_KEY', () => {
  const result = getRotatableKeys();
  assert.ok(result.has('STRIPE_SECRET_KEY'), 'Expected STRIPE_SECRET_KEY in set');
});

test('does NOT expose key values (set contains only strings without "=" or "sk-")', () => {
  const result = getRotatableKeys();
  for (const entry of result) {
    assert.ok(!entry.includes('='), `Set entry contains "=": ${entry}`);
    assert.ok(!entry.startsWith('sk-'), `Set entry looks like a key value: ${entry}`);
  }
});

// ── rotateKey — rejection cases ───────────────────────────────────────────────

console.log('\nrotateKey() — rejection cases');

test('throws for an unsupported key name', () => {
  assert.throws(
    () => rotateKey('DATABASE_URL'),
    /not in the list of rotatable keys/,
    'Expected error for unsupported key'
  );
});

test('throws for an empty string key name', () => {
  assert.throws(
    () => rotateKey(''),
    /not in the list of rotatable keys/,
    'Expected error for empty key name'
  );
});

test('throws when key is absent from .env.test', () => {
  saveOriginals();
  try {
    // Temporarily remove ANTHROPIC_API_KEY from the file
    const original = fs.readFileSync(REAL_ENV, 'utf8');
    const modified = original
      .split('\n')
      .filter((l) => !l.startsWith('ANTHROPIC_API_KEY='))
      .join('\n');
    fs.writeFileSync(REAL_ENV, modified, 'utf8');

    assert.throws(
      () => rotateKey('ANTHROPIC_API_KEY'),
      /was not found in/,
      'Expected error for missing key'
    );
  } finally {
    restoreOriginals();
  }
});

// ── rotateKey — success: ANTHROPIC_API_KEY ────────────────────────────────────

console.log('\nrotateKey() — ANTHROPIC_API_KEY rotation');

test('return value contains keyName but NOT the key value', () => {
  saveOriginals();
  try {
    const result = rotateKey('ANTHROPIC_API_KEY');
    assert.strictEqual(result.keyName, 'ANTHROPIC_API_KEY');
    assert.ok(result.rotatedAt, 'rotatedAt should be present');

