/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Design principles enforced throughout this module:
 *  - Actual key VALUES are never logged, stored in the rotation log, or
 *    written to any location other than the target .env file itself.
 *  - Only key NAMES and opaque metadata (timestamps, status) leave the
 *    rotation pipeline.
 *  - Writes to .env.test are atomic: the new content is first written to a
 *    temporary file (.env.test.tmp), then renamed over the target in a single
 *    syscall so readers never see a half-written file.
 *  - The set of rotateable keys is derived exclusively from what is already
 *    present in .env.test – no hard-coded allowlist is required.
 */

'use strict';

const fs        = require('fs');
const path      = require('path');
const crypto    = require('crypto');
const os        = require('os');

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const TMP_FILE     = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ---------------------------------------------------------------------------
// Keys that this module is authorised to rotate.
// Populated at load-time by reading .env.test – see loadRotateableKeys().
// ---------------------------------------------------------------------------

const SUPPORTED_KEYS = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];

// ---------------------------------------------------------------------------
// .env parsing helpers
// ---------------------------------------------------------------------------

/**
 * Parse a raw .env file string into an ordered array of line descriptors so
 * that we can reconstruct the file faithfully (preserving comments, blank
 * lines, and ordering).
 *
 * Each descriptor is one of:
 *   { type: 'assignment', name: string, raw: string }
 *   { type: 'other',                    raw: string }   // comment / blank
 *
 * We deliberately do NOT store the value in the descriptor so it never ends
 * up in any data structure that might be serialised or logged.
 */
function parseEnvLines(content) {
  return content.split('\n').map((raw) => {
    // Match `KEY=anything` where KEY is a valid env-var identifier.
    const match = raw.match(/^([A-Za-z_][A-Za-z0-9_]*)\s*=(.*)$/);
    if (match) {
      return { type: 'assignment', name: match[1], raw };
    }
    return { type: 'other', raw };
  });
}

/**
 * Read .env.test and return the ordered line descriptors.
 * Throws if the file cannot be read.
 */
function readEnvLines() {
  let content;
  try {
    content = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    throw new Error(`Cannot read ${ENV_FILE}: ${err.message}`);
  }
  return parseEnvLines(content);
}

// ---------------------------------------------------------------------------
// Key discovery
// ---------------------------------------------------------------------------

/**
 * Read .env.test and return the set of key NAMES that are present AND are in
 * SUPPORTED_KEYS.  This is the authoritative list of keys that rotateKey()
 * will accept.
 *
 * @returns {string[]} Array of rotateable key names found in the file.
 */
function loadRotateableKeys() {
  const lines = readEnvLines();
  const found = [];
  for (const line of lines) {
    if (line.type === 'assignment' && SUPPORTED_KEYS.includes(line.name)) {
      found.push(line.name);
    }
  }
  return found;
}

// ---------------------------------------------------------------------------
// Placeholder generation
// ---------------------------------------------------------------------------

/**
 * Generate a new opaque placeholder value for the given key name.
 *
 * In a real rotation pipeline this function would call the upstream provider's
 * API (Anthropic / Stripe) to obtain a real credential.  Here we produce a
 * clearly-synthetic placeholder so that:
 *   a) No real secrets are ever generated or stored by this module.
 *   b) The placeholder is obviously not a production credential.
 *   c) Each rotation produces a unique value (via random hex suffix).
 *
 * Format:  PLACEHOLDER-<KEY_NAME>-<16 random hex bytes>
 *
 * The caller (rotateKey) passes this directly into the file write; it is
 * never returned to the outside and is not logged.
 *
 * @param {string} keyName
 * @returns {string}
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `PLACEHOLDER-${keyName}-${randomHex}`;
}

// ---------------------------------------------------------------------------
// Rotation log helpers
// ---------------------------------------------------------------------------

/**
 * Read the existing rotation log from disk, or return an empty log structure
 * if none exists yet.
 *
 * The log schema:
 * {
 *   "rotations": [
 *     {
 *       "timestamp": "<ISO-8601>",
 *       "keyName":   "<KEY_NAME>",
 *       "status":    "success" | "failure",
 *       "error":     "<message>"   // only present on failure
 *     },
 *     ...
 *   ]
 * }
 *
 * IMPORTANT: key VALUES are never stored in this structure.
 *
 * @returns {{ rotations: object[] }}
 */
function readLog() {
  try {
    const raw = fs.readFileSync(LOG_FILE, 'utf8');
    const parsed = JSON.parse(raw);
    // Defensive: ensure the expected shape exists.
    if (!Array.isArray(parsed.rotations)) {
      parsed.rotations = [];
    }
    return parsed;
  } catch {
    // File doesn't exist yet, or is malformed – start fresh.
    return { rotations: [] };
  }
}

/**
 * Append a rotation event to rotation-log.json.
 *
 * @param {object} event  Must NOT contain any key value.
 * @param {string} event.keyName   - Name of the rotated key.
 * @param {string} event.status    - 'success' | 'failure'
 * @param {string} [event.error]   - Error message on failure (no key material).
 */
function appendLogEntry(event) {
  const log = readLog();

  const entry = {
    timestamp: new Date().toISOString(),
    keyName:   event.keyName,
    status:    event.status,
  };

  if (event.status === 'failure' && event.error) {
    // Sanitise the error message: strip anything that looks like a key value
    // (long alphanumeric tokens) just in case an upstream error embeds one.
    entry.error = sanitiseErrorMessage(event.error);
  }

  log.rotations.push(entry);

  // Write the log atomically via a temp file and rename, same pattern as the
  // .env write, to prevent corruption if the process is interrupted.
  const tmpLog = LOG_FILE + '.tmp';
  try {
    fs.writeFileSync(tmpLog, JSON.stringify(log, null, 2) + '\n', { encoding: 'utf8', mode: 0o600 });
    fs.renameSync(tmpLog, LOG_FILE);
  } catch (logErr) {
    // Logging failure must never mask the primary operation result.
    // We print a warning to stderr only (no key material present here).
    process.stderr.write(`[key-rotation] WARNING: could not write rotation log: ${logErr.message}\n`);
    try { fs.unlinkSync(tmpLog); } catch { /* ignore */ }
  }
}

/**
 * Remove tokens that might be secret key material from an error string.
 * Tokens matching the pattern of a long alphanumeric/hyphen/underscore
 * sequence (≥ 20 chars) are redacted.
 *
 * @param {string} message
 * @returns {string}
 */
function sanitiseErrorMessage(message) {
  return String(message).replace(/[A-Za-z0-9_\-]{20,}/g, '[REDACTED]');
}

// ---------------------------------------------------------------------------
// Atomic .env write
// ---------------------------------------------------------------------------

/**
 * Write the updated .env.test content atomically.
 *
 * Steps:
 *   1. Write to ENV_FILE + '.tmp'  (TMP_FILE)
 *   2. fs.renameSync(TMP_FILE, ENV_FILE)  — atomic on POSIX filesystems
 *
 * The temporary file is created with mode 0o600 so it is never world-readable
 * even momentarily.
 *
 * @param {string} content  The complete new file content.
 */
function atomicWriteEnv(content) {
  // Clean up any stale temp file before we start.
  try { fs.unlinkSync(TMP_FILE); } catch { /* doesn't exist, fine */ }

  try {
    fs.writeFileSync(TMP_FILE, content, { encoding: 'utf8', mode: 0o600 });
  } catch (err) {
    throw new Error(`Failed to write temporary env file ${TMP_FILE}: ${err.message}`);
  }

  try {
    fs.renameSync(TMP_FILE, ENV_FILE);
  } catch (err) {
    // Attempt cleanup so we don't leave secrets in a temp file.
    try { fs.unlinkSync(TMP_FILE); } catch { /* ignore */ }
    throw new Error(`Atomic rename of ${TMP_FILE} → ${ENV_FILE} failed: ${err.message}`);
  }
}

// ---------------------------------------------------------------------------
// Core rotation function
// ---------------------------------------------------------------------------

/**
 * Rotate the key identified by keyName in .env.test.
 *
 * Process:
 *  1. Validate keyName against the SUPPORTED_KEYS list.
 *  2. Confirm keyName actually exists in the current .env.test.
 *  3. Generate a new placeholder value (never logged).
 *  4. Rebuild the .env.test content, replacing only the target assignment line.
 *  5. Write the new content atomically (tmp → rename).
 *  6. Append a success entry to rotation-log.json (name + timestamp only).
 *
 * On any failure, a failure entry is appended to the log and the error is
 * re-thrown so callers can handle it.
 *
 * @param {string} keyName  The environment variable name to rotate,
 *                          e.g. 'ANTHROPIC_API_KEY'.
 * @returns {{ keyName: string, timestamp: string }}
 *   Confirmation object containing only the key name and rotation timestamp.
 *   The new key value is intentionally NOT returned.
 */
function rotateKey(keyName) {
  // ------------------------------------------------------------------
  // 1. Validate keyName
  // ------------------------------------------------------------------
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    const err = new Error('rotateKey: keyName must be a non-empty string.');
    appendLogEntry({ keyName: String(keyName), status: 'failure', error: err.message });
    throw err;
  }

  const normalisedName = keyName.trim();

  if (!SUPPORTED_KEYS.includes(normalisedName)) {
    const err = new Error(
      `rotateKey: '${normalisedName}' is not in the supported keys list ` +
      `(${SUPPORTED_KEYS.join(', ')}).`
    );
    appendLogEntry({ keyName: normalisedName, status: 'failure', error: err.message });
    throw err;
  }

  // ------------------------------------------------------------------
  // 2. Read and parse the current .env.test
  // ------------------------------------------------------------------
  let lines;
  try {
    lines = readEnvLines();
  } catch (err) {
    appendLogEntry({ keyName: normalisedName, status: 'failure', error: err.message });
    throw err;
  }

  const targetIndex = lines.findIndex(
    (l) => l.type === 'assignment' && l.name === normalisedName
  );

  if (targetIndex === -1) {
    const err = new Error(
      `rotateKey: key '${normalisedName}' was not found in ${ENV_FILE}.`
    );
    appendLogEntry({ keyName: normalisedName, status: 'failure', error: err.message });
    throw err;
  }

  // ------------------------------------------------------------------
  // 3. Generate the replacement value — never assign to a variable that
  //    escapes this scope, and never log it.
  // ------------------------------------------------------------------

  // ------------------------------------------------------------------
  // 4. Rebuild file content
  //    We replace only the matched line; all other lines (including
  //    comments) are preserved verbatim.
  // ------------------------------------------------------------------
  const newLines = lines.map((line, index) => {
    if (index === targetIndex) {
      // Construct the new assignment line with the fresh placeholder.
      // The placeholder is generated inline so it never sits in a named
      // variable outside this map callback.
      return `${normalisedName}=${generatePlaceholder(normalisedName)}`;
    }
    return line.raw;
  });

  // Preserve original trailing-newline behaviour.
  const newContent = newLines.join('\n');

  // ------------------------------------------------------------------
  // 5. Atomic write
  // ------------------------------------------------------------------
  try {
    atomicWriteEnv(newContent);
  } catch (err) {
    appendLogEntry({ keyName: normalisedName, status: 'failure', error: err.message });
    throw err;
  }

  // ------------------------------------------------------------------
  // 6. Log the successful rotation (name + timestamp only — NO value)
  // ------------------------------------------------------------------
  const timestamp = new Date().toISOString();
  appendLogEntry({ keyName: normalisedName, status: 'success' });

  console.log(`[key-rotation] Rotated key '${normalisedName}' at ${timestamp}.`);

  return { keyName: normalisedName, timestamp };
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

module.exports = {
  /**
   * Rotate a single key by name.
   * @type {(keyName: string) => { keyName: string, timestamp: string }}
   */
  rotateKey,

  /**
   * Return the list of key names present in .env.test that this module
   * supports rotating.  Useful for callers that want to enumerate candidates
   * without hard-coding names.
   * @type {() => string[]}
   */
  loadRotateableKeys,

  // Expose constants so consumers can inspect configuration.
  ENV_FILE,
  LOG_FILE,
  SUPPORTED_KEYS,
};

