'use strict';

/**
 * key-rotation.js
 *
 * API key rotation module.
 *
 * Safety contract
 * ---------------
 *  - Key *values* are NEVER logged, returned to callers, or written anywhere
 *    other than the .env file itself.
 *  - rotation-log.json records only { timestamp, keyName, status } — no values.
 *  - The .env update is atomic: written to a .tmp file first, then fs.renameSync
 *    replaces the real file so a crash mid-write cannot corrupt it.
 */

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ── paths ──────────────────────────────────────────────────────────────────
const ENV_PATH     = path.resolve(__dirname, '.env.test');
const ENV_TMP_PATH = path.resolve(__dirname, '.env.test.tmp');
const LOG_PATH     = path.resolve(__dirname, 'rotation-log.json');

// ── keys this module is allowed to rotate ─────────────────────────────────
// Only ANTHROPIC_API_KEY and STRIPE_SECRET_KEY are in scope per the spec.
// We discover them by reading the .env file so the list stays in one place.
const ROTATEABLE_KEY_NAMES = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];

// ── helpers ────────────────────────────────────────────────────────────────

/**
 * Parse a .env file into an ordered array of line descriptors so we can
 * round-trip the file without destroying comments or blank lines.
 *
 * Each element is one of:
 *   { type: 'pair',    raw: string, name: string }   – KEY=VALUE line
 *   { type: 'other',   raw: string }                 – comment / blank line
 *
 * The parsed VALUE is intentionally never stored in any descriptor field —
 * we only need the name to locate which line to replace.
 */
function parseEnvLines(content) {
  return content.split('\n').map(raw => {
    // Match lines of the form:  KEY=anything  (KEY must start with a letter/_)
    const match = raw.match(/^([A-Za-z_][A-Za-z0-9_]*)=/);
    if (match) {
      return { type: 'pair', raw, name: match[1] };
    }
    return { type: 'other', raw };
  });
}

/**
 * Read the .env file and return the set of key names that are both present
 * in the file and listed in ROTATEABLE_KEY_NAMES.
 *
 * Values are never captured — only names.
 */
function readRotateableKeyNames() {
  const content = fs.readFileSync(ENV_PATH, 'utf8');
  const lines   = parseEnvLines(content);

  const present = new Set(
    lines
      .filter(l => l.type === 'pair')
      .map(l => l.name)
  );

  return ROTATEABLE_KEY_NAMES.filter(name => present.has(name));
}

/**
 * Generate a new key placeholder.
 *
 * In a production system this would call the provider's API to issue a real
 * credential.  Here we produce a clearly-marked placeholder so the .env file
 * is never left with an invalid entry, and no real secrets are invented.
 *
 * Format: ROTATED-<keyName>-<16 random hex bytes>
 *
 * The value is returned to the caller ONLY so it can be written into the
 * .env file.  It is not logged anywhere.
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  return `ROTATED-${keyName}-${randomHex}`;
}

/**
 * Append one rotation event to rotation-log.json.
 *
 * Only { timestamp, keyName, status } are written — never any key value.
 */
function appendRotationLog(keyName, status, errorMessage) {
  let log = [];

  if (fs.existsSync(LOG_PATH)) {
    try {
      const raw = fs.readFileSync(LOG_PATH, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // Corrupted log — start fresh rather than crash.
      log = [];
    }
  }

  const entry = {
    timestamp: new Date().toISOString(),
    keyName,
    status, // 'success' | 'failure'
    ...(errorMessage ? { error: errorMessage } : {}),
  };

  // Final safety check: make sure no key value accidentally ended up in the
  // entry through a coding mistake.
  if (JSON.stringify(entry).toLowerCase().includes('rotated-')) {
    // This branch should never be reached; it is a defensive tripwire.
    throw new Error('BUG: key value leaked into log entry — aborting log write');
  }

  log.push(entry);

  fs.writeFileSync(LOG_PATH, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ── public API ─────────────────────────────────────────────────────────────

/**
 * rotateKey(keyName)
 *
 * Rotates the named key inside .env.test:
 *   1. Validates that keyName is one of the allowed rotateable keys and that
 *      it actually exists in the current .env.test.
 *   2. Generates a new placeholder value (crypto-random, never logged).
 *   3. Writes the updated .env content to .env.test.tmp.
 *   4. Atomically renames .env.test.tmp → .env.test.
 *   5. Logs { timestamp, keyName, status } to rotation-log.json.
 *
 * @param  {string} keyName  The environment variable name to rotate.
 * @throws {Error}           If keyName is not rotateable or not found.
 */
function rotateKey(keyName) {
  // ── 1. Validate ──────────────────────────────────────────────────────────
  if (!ROTATEABLE_KEY_NAMES.includes(keyName)) {
    const err = new Error(
      `rotateKey: "${keyName}" is not in the list of rotateable keys ` +
      `(${ROTATEABLE_KEY_NAMES.join(', ')})`
    );
    appendRotationLog(keyName, 'failure', err.message);
    throw err;
  }

  const rotateable = readRotateableKeyNames();
  if (!rotateable.includes(keyName)) {
    const err = new Error(
      `rotateKey: "${keyName}" was not found in ${ENV_PATH}`
    );
    appendRotationLog(keyName, 'failure', err.message);
    throw err;
  }

  // ── 2. Build the updated file content ────────────────────────────────────
  // Read the raw file; parse into lines; replace only the target line.
  // The current value is read but immediately discarded — it is never
  // assigned to a variable, logged, or returned.
  const content    = fs.readFileSync(ENV_PATH, 'utf8');
  const lines      = parseEnvLines(content);
  const newValue   = generatePlaceholder(keyName); // never logged
  let   keyFound   = false;

  const updatedLines = lines.map(line => {
    if (line.type === 'pair' && line.name === keyName) {
      keyFound = true;
      // Replace the entire line; the old value is discarded, not captured.
      return { ...line, raw: `${keyName}=${newValue}` };
    }
    return line;
  });

  if (!keyFound) {
    // Defensive — readRotateableKeyNames() should have caught this already.
    const err = new Error(
      `rotateKey: "${keyName}" line disappeared between validation and write`
    );
    appendRotationLog(keyName, 'failure', err.message);
    throw err;
  }

  const updatedContent = updatedLines.map(l => l.raw).join('\n');

  // ── 3 & 4. Atomic write: tmp → rename ────────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_PATH, updatedContent, 'utf8');
    fs.renameSync(ENV_TMP_PATH, ENV_PATH);
  } catch (ioErr) {
    // Clean up the tmp file if it was created but rename failed.
    try { fs.unlinkSync(ENV_TMP_PATH); } catch { /* best-effort */ }
    appendRotationLog(keyName, 'failure', ioErr.message);
    throw ioErr;
  }

  // ── 5. Log the rotation event (name + timestamp only) ────────────────────
  appendRotationLog(keyName, 'success');

  // newValue intentionally goes out of scope here without being returned
  // or stored anywhere outside the .env file.
}

// ── module exports ─────────────────────────────────────────────────────────
module.exports = {
  rotateKey,
  readRotateableKeyNames, // useful for callers that want to list managed keys
};

'use strict';

