 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Uses Node's built-in assert module — no extra test framework required.
 *
 * Run with:  node key-rotation.test.js
 */

const assert = require('assert');
const fs     = require('fs');
const path   = require('path');

// ── file paths that the module under test uses ────────────────────────────
const ENV_PATH     = path.resolve(__dirname, '.env.test');
