function resetEnv() {
  fs.writeFileSync(ENV_PATH, ORIGINAL_ENV, 'utf8');
}

function clearLog() {
  if (fs.existsSync(LOG_PATH)) fs.unlinkSync(LOG_PATH);
}

function clearTmp() {
  if (fs.existsSync(ENV_TMP_PATH)) fs.unlinkSync(ENV_TMP_PATH);
}

function readLog() {
  if (!fs.existsSync(LOG_PATH)) return [];
  return JSON.parse(fs.readFileSync(LOG_PATH, 'utf8'));
}

function readEnv() {
  return fs.readFileSync(ENV_PATH, 'utf8');
}

/** Extract the current value for a given key from the .env file. */
function getEnvValue(keyName) {
  const match = readEnv().match(new RegExp(`^${keyName}=(.*)$`, 'm'));
  return match ? match[1] : null;
}

// Re-require the module fresh so each test group gets a clean module cache.
function loadModule() {
  // Bust the require cache so state-less helpers are re-evaluated.
  delete require.cache[require.resolve('./key-rotation')];
  return require('./key-rotation');
}

