/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security contract:
 *   - Key VALUES are never logged, never stored in the rotation log,
 *     and never appear in any string passed to console or written to
 *     rotation-log.json.
 *   - The .env.test file is updated atomically: a temporary file
 *     (.env.test.tmp) is fully written and fsynced before being
 *     renamed over the original, so a crash mid-write cannot
 *     corrupt the live file.
 *   - Only the key NAME (e.g. "ANTHROPIC_API_KEY") and a timestamp
 *     are persisted to the audit log.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ── Paths ────────────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const TMP_FILE     = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ── Keys eligible for rotation ───────────────────────────────────────────────
// We discover these by parsing .env.test at module load time, then
// restricting rotateKey() to only the names already present in that file.
// This prevents the rotation function from being used to inject arbitrary
// new variables.

/**
 * Parse an env file into a Map<name, rawLine> preserving comments and
 * blank lines exactly so we can round-trip the file without disturbing
 * anything we are not rotating.
 *
 * Returns:
 *   {
 *     lines : string[]         – every raw line in original order
 *     index : Map<string, number> – variable name → line index
 *   }
 */
function parseEnvFile(filePath) {
  const raw   = fs.readFileSync(filePath, 'utf8');
  const lines = raw.split('\n');

  // Remove a trailing empty element that results from a file ending in '\n'
  // We will re-add the terminating newline when we write.
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop();
  }

  const index = new Map();

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim();

    // Skip blank lines and comments
    if (line === '' || line.startsWith('#')) continue;

    // KEY=VALUE  (value may contain '=')
    const eqPos = line.indexOf('=');
    if (eqPos < 1) continue;

    const name = line.slice(0, eqPos).trim();
    if (name) {
      index.set(name, i);
    }
  }

  return { lines, index };
}

/**
 * Read .env.test and return the Set of variable names declared in it.
 * Called once at module load; also called inside rotateKey() to get a
 * fresh view in case the file changed between calls.
 */
function readDeclaredKeyNames(filePath) {
  const { index } = parseEnvFile(filePath);
  return new Set(index.keys());
}

// The set of rotateable key names is seeded at load time.
// rotateKey() re-validates against the live file on every call.
const ROTATEABLE_KEYS = readDeclaredKeyNames(ENV_FILE);

// ── Placeholder generator ────────────────────────────────────────────────────

/**
 * Generate a cryptographically random placeholder value for a rotated key.
 *
 * The placeholder is intentionally NOT a real credential — it signals that
 * the slot has been rotated and the real value must be injected by the
 * secrets-management system.  Format:
 *
 *   ROTATED-<keyName>-<16 random hex bytes>-<ISO timestamp fragment>
 *
 * Using the key name (not value) in the placeholder makes log correlation
 * easier without leaking anything sensitive.
 */
function generatePlaceholder(keyName) {
  const randomPart = crypto.randomBytes(16).toString('hex');
  // Compact timestamp: YYYYMMDDTHHmmss
  const now = new Date();
  const ts  = now.toISOString().replace(/[-:]/g, '').slice(0, 15); // e.g. 20240623T081923
  return `ROTATED-${keyName}-${randomPart}-${ts}`;
}

// ── Rotation log ─────────────────────────────────────────────────────────────

/**
 * Append one rotation event to rotation-log.json.
 *
 * The log entry contains ONLY:
 *   - timestamp  (ISO 8601)
 *   - keyName    (the variable name, e.g. "ANTHROPIC_API_KEY")
 *   - event      (always "rotated")
 *
 * Key values — old or new — are NEVER written here.
 */
function appendRotationLog(keyName) {
  const entry = {
    timestamp : new Date().toISOString(),
    keyName,               // variable name only — NOT the value
    event     : 'rotated',
  };

  // Read existing log array (or start fresh).
  let records = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        records = parsed;
      } else {
        // Unexpected format — wrap existing content and continue.
        records = [parsed];
      }
    } catch {
      // Malformed JSON — reset rather than crash.
      records = [];
    }
  }

  records.push(entry);

  // Write the log file.  The log is append-oriented so we accept a
  // non-atomic write here; the worst case is a slightly garbled file
  // on a hard crash, not data corruption of the env file itself.
  fs.writeFileSync(LOG_FILE, JSON.stringify(records, null, 2) + '\n', 'utf8');
}

// ── Core rotation function ───────────────────────────────────────────────────

/**
 * rotateKey(keyName)
 *
 * 1. Validates that keyName exists in .env.test (read fresh each call).
 * 2. Generates a new placeholder value.
 * 3. Rewrites .env.test atomically via a tmp-then-rename strategy.
 * 4. Appends a log entry (name + timestamp only) to rotation-log.json.
 * 5. Returns { keyName, rotatedAt } — the new value is intentionally
 *    NOT returned so callers cannot inadvertently log it.
 *
 * Throws on invalid keyName or any I/O error.
 *
 * @param  {string} keyName  - The environment variable name to rotate.
 * @returns {{ keyName: string, rotatedAt: string }}
 */
function rotateKey(keyName) {
  // ── 1. Input validation ──────────────────────────────────────────────────

  if (typeof keyName !== 'string' || keyName.trim() === '') {
    throw new TypeError('rotateKey: keyName must be a non-empty string');
  }

  const normalizedName = keyName.trim();

  // Re-read the file on every call so we always work from ground truth.
  const liveKeys = readDeclaredKeyNames(ENV_FILE);

  if (!liveKeys.has(normalizedName)) {
    throw new RangeError(
      `rotateKey: "${normalizedName}" is not declared in ${ENV_FILE}. ` +
      `Declared keys: ${[...liveKeys].join(', ')}`
    );
  }

  // ── 2. Generate new placeholder ──────────────────────────────────────────

  const newPlaceholder = generatePlaceholder(normalizedName);

  // ── 3. Atomic file update ────────────────────────────────────────────────
  //
  //   a. Parse the current file (preserving all lines).
  //   b. Locate the target KEY line and replace only the value portion.
  //   c. Write the full content to .env.test.tmp.
  //   d. fsync the tmp file (ensures bytes are on disk before rename).
  //   e. Rename tmp → .env.test  (atomic on POSIX systems).

  const { lines, index } = parseEnvFile(ENV_FILE);
  const lineIdx          = index.get(normalizedName);

  if (lineIdx === undefined) {
    // Should not happen since we just confirmed the key exists, but guard anyway.
    throw new Error(`rotateKey: internal error — could not locate line for "${normalizedName}"`);
  }

  // Replace the line preserving the key name exactly as written in the file.
  // We extract the original name from the line so we don't accidentally change
  // its casing or surrounding whitespace.
  const originalLine = lines[lineIdx];
  const eqPos        = originalLine.indexOf('=');
  const originalName = originalLine.slice(0, eqPos);   // preserve original casing/spacing
  lines[lineIdx]     = `${originalName}=${newPlaceholder}`;

  const newContent = lines.join('\n') + '\n';   // restore trailing newline

  // Write to tmp file
  const tmpFd = fs.openSync(TMP_FILE, 'w', 0o600);  // owner-read/write only
  try {
    fs.writeSync(tmpFd, newContent);
    fs.fsyncSync(tmpFd);                // flush to disk before rename
  } finally {
    fs.closeSync(tmpFd);
  }

  // Atomic rename: on POSIX this is guaranteed to be atomic.
  fs.renameSync(TMP_FILE, ENV_FILE);

  // ── 4. Audit log (name + timestamp only) ────────────────────────────────

  const rotatedAt = new Date().toISOString();
  appendRotationLog(normalizedName);

  // ── 5. Console audit trail (name + timestamp only) ──────────────────────

  console.log(`[key-rotation] Rotated key "${normalizedName}" at ${rotatedAt}`);

  // ── 6. Return metadata — value deliberately excluded ────────────────────

  return { keyName: normalizedName, rotatedAt };
}

// ── Public API ───────────────────────────────────────────────────────────────

module.exports = {
  rotateKey,

  /**
   * Returns the set of key names currently declared in .env.test.
   * Useful for callers that want to enumerate rotateable keys without
   * parsing the env file themselves.
   */
  getRotateableKeys() {
    return readDeclaredKeyNames(ENV_FILE);
  },
};

