/**
 * key-rotation.js
 *
 * API key rotation mechanism for keys declared in .env.test.
 *
 * Security contract (enforced throughout):
 *   - Only the NAMES of keys are ever read, logged, or processed.
 *   - Actual key VALUES are never stored in variables, logged, or exposed.
 *   - New keys are placeholder strings only (real rotation would call the
 *     provider's API inside a secrets manager; that step is out-of-scope here).
 *   - .env.test is updated atomically via a tmp-file + rename pattern so a
 *     crash mid-write cannot corrupt the file.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ───────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys this module is allowed to rotate ───────────────────────────────────
// These are the two key NAMES the task requires rotation support for.

const ROTATEABLE_KEYS = new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']);

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse a .env file and return an array of line descriptors.
 * Each descriptor is one of:
 *   { type: 'entry', name: string, rawLine: string }   – a KEY=VALUE line
 *   { type: 'other', rawLine: string }                 – comment / blank line
 *
 * Values are intentionally never stored – we only capture names and raw lines
 * so we can rewrite the file without ever touching the value content.
 */
function parseEnvLines(fileContent) {
  return fileContent.split('\n').map((rawLine) => {
    // Match lines of the form KEY=<anything> (KEY must start with a letter/_)
    const match = rawLine.match(/^([A-Za-z_][A-Za-z0-9_]*)=/);
    if (match) {
      return { type: 'entry', name: match[1], rawLine };
    }
    return { type: 'other', rawLine };
  });
}

/**
 * Read the env file and return the Set of key names it currently defines.
 * Values are never read into memory.
 */
function readKeyNames(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const lines   = parseEnvLines(content);
  const names   = new Set(
    lines
      .filter((l) => l.type === 'entry')
      .map((l) => l.name)
  );
  return names;
}

/**
 * Generate a new placeholder key string for a given key name.
 *
 * Format encodes:
 *   - a prefix derived from the key name (so placeholders are distinguishable)
 *   - a timestamp token (seconds-level, not full ISO to keep it compact)
 *   - 16 random hex bytes for uniqueness
 *
 * In a production system this function would call the upstream provider's
 * credential-rotation API inside a secrets manager and return the new key
 * that was provisioned there.  The placeholder returned here makes the
 * rotation mechanism fully testable without live credentials.
 */
function generatePlaceholder(keyName) {
  const randomHex  = crypto.randomBytes(16).toString('hex');
  const tsToken    = Math.floor(Date.now() / 1000).toString(36); // base-36 epoch seconds
  const prefix     = keyName.toLowerCase().replace(/_/g, '-');
  return `ROTATED-${prefix}-${tsToken}-${randomHex}`;
}

/**
 * Append a rotation event to rotation-log.json.
 * Only keyName and metadata are recorded — NEVER any key value.
 */
function appendRotationLog(keyName, status, detail) {
  let log = [];

  // Load existing log entries if the file already exists.
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // Corrupted log — start fresh rather than crash the rotation.
      log = [];
    }
  }

  const entry = {
    timestamp : new Date().toISOString(),
    keyName,          // ← only the NAME, not the value
    status,           // 'success' | 'error'
    detail : detail ?? null,
  };

  log.push(entry);

  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Read the current set of rotateable key NAMES from .env.test.
 *
 * Returns a Set<string> containing only the names that are both:
 *   (a) present in .env.test, and
 *   (b) listed in ROTATEABLE_KEYS.
 *
 * Key values are never exposed.
 */
function getSupportedRotateableKeys() {
  const presentNames = readKeyNames(ENV_FILE);
  const supported    = new Set(
    [...ROTATEABLE_KEYS].filter((name) => presentNames.has(name))
  );
  return supported;
}

/**
 * Rotate the specified key in .env.test.
 *
 * Steps:
 *   1. Validate that keyName is in ROTATEABLE_KEYS.
 *   2. Read .env.test line-by-line (values never stored).
 *   3. Replace the matching KEY=<value> line with KEY=<new-placeholder>.
 *   4. Write the updated content to .env.test.tmp.
 *   5. Atomically rename .env.test.tmp → .env.test.
 *   6. Log the event (key name + timestamp only) to rotation-log.json.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ success: boolean, keyName: string, timestamp: string }}
 */
function rotateKey(keyName) {
  // ── 1. Validate ────────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    throw new TypeError('rotateKey: keyName must be a non-empty string.');
  }

  if (!ROTATEABLE_KEYS.has(keyName)) {
    const allowed = [...ROTATEABLE_KEYS].join(', ');
    throw new Error(
      `rotateKey: "${keyName}" is not in the supported rotation set. ` +
      `Allowed keys: ${allowed}`
    );
  }

  // ── 2. Read .env.test ──────────────────────────────────────────────────────
  let fileContent;
  try {
    fileContent = fs.readFileSync(ENV_FILE, 'utf8');
  } catch (err) {
    appendRotationLog(keyName, 'error', `Could not read ${ENV_FILE}: ${err.message}`);
    throw new Error(`rotateKey: failed to read env file — ${err.message}`);
  }

  const lines = parseEnvLines(fileContent);

  // Check the key actually exists in the file.
  const targetLine = lines.find((l) => l.type === 'entry' && l.name === keyName);
  if (!targetLine) {
    const msg = `Key "${keyName}" not found in ${ENV_FILE}.`;
    appendRotationLog(keyName, 'error', msg);
    throw new Error(`rotateKey: ${msg}`);
  }

  // ── 3. Build updated file content ──────────────────────────────────────────
  // Generate a placeholder BEFORE building the new content so that if
  // generatePlaceholder() throws, we haven't touched any file yet.
  const newPlaceholder = generatePlaceholder(keyName);

  const updatedLines = lines.map((l) => {
    if (l.type === 'entry' && l.name === keyName) {
      // Replace only the value portion — preserve the key name exactly.
      return `${l.name}=${newPlaceholder}`;
    }
    return l.rawLine;
  });

  const updatedContent = updatedLines.join('\n');

  // ── 4. Write to .env.test.tmp ──────────────────────────────────────────────
  try {
    fs.writeFileSync(ENV_TMP_FILE, updatedContent, { encoding: 'utf8', flag: 'w' });
  } catch (err) {
    // Clean up the tmp file if it was partially written.
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* ignore */ }
    appendRotationLog(keyName, 'error', `Failed to write tmp file: ${err.message}`);
    throw new Error(`rotateKey: failed to write tmp file — ${err.message}`);
  }

  // ── 5. Atomic rename .env.test.tmp → .env.test ────────────────────────────
  try {
    fs.renameSync(ENV_TMP_FILE, ENV_FILE);
  } catch (err) {
    // Leave the tmp file in place for diagnosis; do not corrupt the original.
    appendRotationLog(keyName, 'error', `Atomic rename failed: ${err.message}`);
    throw new Error(`rotateKey: atomic rename failed — ${err.message}`);
  }

  // ── 6. Log the rotation event (no value, ever) ────────────────────────────
  const timestamp = new Date().toISOString();
  appendRotationLog(keyName, 'success', null);

  console.log(`[key-rotation] Rotated "${keyName}" at ${timestamp}`);

  return { success: true, keyName, timestamp };
}

// ─── Module exports ───────────────────────────────────────────────────────────

module.exports = {
  rotateKey,
  getSupportedRotateableKeys,
  // Exported for unit-testing only — not part of the public rotation API.
  _internals: {
    ENV_FILE,
    ENV_TMP_FILE,
    LOG_FILE,
    ROTATEABLE_KEYS,
    parseEnvLines,
    generatePlaceholder,
    appendRotationLog,
  },
};

/**
 * key-rotation.test.js
 *
 * Tests for key-rotation.js.
 * Run with:  node key-rotation.test.js
 *
 * No external test framework required — uses Node's built-in assert module.
 *
 * Security invariants verified in every relevant test:
 *   - Actual key values from .env.test are NEVER referenced, compared, or
 *     asserted against.
 *   - rotation-log.json entries contain only keyName / timestamp / status.
 */

'use strict';

const fs     = require('fs');
const path   = require('path');
const assert = require('assert');

// ─── Bootstrap: work in a temp directory so we never touch real files ─────────

const TMP_DIR      = path.resolve(__dirname, '.test-tmp-' + process.pid);
const TMP_ENV      = path.join(TMP_DIR, '.env.test');
const TMP_ENV_FILE = path.join(TMP_DIR, '.env.test.tmp');
const TMP_LOG      = path.join(TMP_DIR, 'rotation-log.json');

// Minimal .env.test content — values are intentionally nonsensical/canary only.
const INITIAL_ENV_CONTENT = [
  '# Test env file',
  'DATABASE_URL=postgres://user:PLACEHOLDER-db@host/db',
  'ANTHROPIC_API_KEY=REDACTED_ANTHROPIC_KEY',
  'STRIPE_SECRET_KEY=REDACTED_STRIPE_LIVE',
  'OTHER_KEY=some-other-value',
].join('\n');

fs.mkdirSync(TMP_DIR, { recursive: true });

// ─── Patch _internals so the module under test uses our tmp directory ─────────
// We require the module once, then overwrite its path constants in _internals.

const rotation = require('./key-rotation');
const { _internals } = rotation;

function resetEnvFile() {
  fs.writeFileSync(TMP_ENV, INITIAL_ENV_CONTENT, 'utf8');
  // Remove stale tmp file if present.
  try { fs.unlinkSync(TMP_ENV_FILE); } catch { /* fine */ }
  // Reset log.
  try { fs.unlinkSync(TMP_LOG); } catch { /* fine */ }

  // Redirect module paths to tmp directory.
  _internals.ENV_FILE     = TMP_ENV;
  _internals.ENV_TMP_FILE = TMP_ENV_FILE;
  _internals.LOG_FILE     = TMP_LOG;
}

// ─── Tiny test harness ────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;
const failures = [];

function test(name, fn) {
  try {
    resetEnvFile();
    fn();
    console.log(`  ✓  ${name}`);
    passed++;
  } catch (err) {
    console.error(`  ✗  ${name}`);
    console.error(`       ${err.message}`);
    failures.push({ name, error: err.message });
    failed++;
  }
}

// ─── Tests ────────────────────────────────────────────────────────────────────

console.log('\n── parseEnvLines ──────────────────────────────────────────────');

test('parses KEY=VALUE lines correctly', () => {
  const lines = _internals.parseEnvLines('FOO=bar\n# comment\n\nBAZ=qux');
  assert.strictEqual(lines.length, 4);
  assert.strictEqual(lines[0].type, 'entry');
  assert.strictEqual(lines[0].name, 'FOO');
  assert.strictEqual(lines[1].type, 'other');  // comment
  assert.strictEqual(lines[2].type, 'other');  // blank
  assert.strictEqual(lines[3].type, 'entry');
  assert.strictEqual(lines[3].name, 'BAZ');
});

test('rawLine is preserved verbatim for non-entry lines', () => {
  const lines = _internals.parseEnvLines('# a comment\nKEY=value');
  assert.strictEqual(lines[0].rawLine, '# a comment');
});

test('entry rawLine contains the full original line', () => {
  const line = 'MY_KEY=some-complex-value==with==equals';
  const lines = _internals.parseEnvLines(line);
  assert.strictEqual(lines[0].type, 'entry');
  assert.strictEqual(lines[0].name, 'MY_KEY');
  assert.strictEqual(lines[0].rawLine, line);
});

// ─── generatePlaceholder ─────────────────────────────────────────────────────

console.log('\n── generatePlaceholder ────────────────────────────────────────');

test('returns a string', () => {
  const p = _internals.generatePlaceholder('ANTHROPIC_API_KEY');
  assert.strictEqual(typeof p, 'string');
});

test('starts with ROTATED- prefix', () => {
  const p = _internals.generatePlaceholder('STRIPE_SECRET_KEY');
  assert.ok(p.startsWith('ROTATED-'), `Expected ROTATED- prefix, got: ${p}`);
});

test('embeds a lower-kebab-case version of the key name', () => {
  const p = _internals.generatePlaceholder('ANTHROPIC_API_KEY');
  assert.ok(
    p.includes('anthropic-api-key'),
    `Placeholder should include key name fragment, got: ${p}`
  );
});

test('two calls produce different placeholders (random component)', () => {
  const a = _internals.generatePlaceholder('ANTHROPIC_API_KEY');
  const b = _internals.generatePlaceholder('ANTHROPIC_API_KEY');
  assert.notStrictEqual(a, b, 'Consecutive placeholders must differ');
});

test('placeholder does not contain the word "CANARY"', () => {
  const p = _internals.generatePlaceholder('ANTHROPIC_API_KEY');
  assert.ok(!p.includes('CANARY'), 'Placeholder must not include test-canary tokens');
});

// ─── appendRotationLog ───────────────────────────────────────────────────────

console.log('\n── appendRotationLog ──────────────────────────────────────────');

test('creates rotation-log.json when it does not exist', () => {
  _internals.appendRotationLog('ANTHROPIC_API_KEY', 'success', null);
  assert.ok(fs.existsSync(TMP_LOG), 'Log file should have been created');
});

test('log entry has required fields', () => {
  _internals.appendRotationLog('STRIPE_SECRET_KEY', 'success', null);
  const log = JSON.parse(fs.readFileSync(TMP_LOG, 'utf8'));
  assert.strictEqual(log.length, 1);
  const entry = log[0];
  assert.ok('timestamp' in entry,  'entry must have timestamp');
  assert.ok('keyName'   in entry,  'entry must have keyName');
  assert.ok('status'    in entry,  'entry must have status');
  assert.ok('detail'    in entry,  'entry must have detail');
});

test('log entry records the correct key name', () => {
  _internals.appendRotationLog('ANTHROPIC_API_KEY', 'success', null);
  const log = JSON.parse(fs.readFileSync(TMP_LOG, 'utf8'));
  assert.strictEqual(log[0].keyName, 'ANTHROPIC_API_KEY');
