/**
 * key-rotation.js
 *
 * API key rotation mechanism for keys declared in .env.test.
 *
 * Security contract (enforced throughout):
 *   - Only the NAMES of keys are ever read, logged, or processed.
 *   - Actual key VALUES are never stored in variables, logged, or exposed.
 *   - New keys are placeholder strings only (real rotation would call the
 *     provider's API inside a secrets manager; that step is out-of-scope here).
 *   - .env.test is updated atomically via a tmp-file + rename pattern so a
 *     crash mid-write cannot corrupt the file.
 */

'use strict';

const fs     = require('fs');
const path   = require('path');
const crypto = require('crypto');

// ─── Configurable paths (exported via _internals for testing) ─────────────────
// All internal functions resolve paths through this object so that test code
// can redirect them by mutating the object's properties at runtime.

const _internals = {
  ENV_FILE     : path.resolve(__dirname, '.env.test'),
  ENV_TMP_FILE : path.resolve(__dirname, '.env.test.tmp'),
  LOG_FILE     : path.resolve(__dirname, 'rotation-log.json'),

  // ── Keys this module is allowed to rotate ─────────────────────────────────
  // These are the two key NAMES the task requires rotation support for.
  ROTATEABLE_KEYS : new Set(['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY']),

  // Helper functions are also properties so they can be called via _internals
  // and therefore always pick up any path overrides written to the object.
  parseEnvLines,
  generatePlaceholder,
  appendRotationLog,
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Parse a .env file and return an array of line descriptors.
 * Each descriptor is one of:
 *   { type: 'entry', name: string, rawLine: string }   – a KEY=VALUE line
 *   { type: 'other', rawLine: string }                 – comment / blank line
 *
 * Values are intentionally never stored – we only capture names and raw lines
 * so we can rewrite the file without ever touching the value content.
 */
function parseEnvLines(fileContent) {
  return fileContent.split('\n').map((rawLine) => {
    // Match lines of the form KEY=<anything> (KEY must start with a letter/_)
    const match = rawLine.match(/^([A-Za-z_][A-Za-z0-9_]*)=/);
    if (match) {
      return { type: 'entry', name: match[1], rawLine };
    }
    return { type: 'other', rawLine };
  });
}

/**
 * Read the env file and return the Set of key names it currently defines.
 * Values are never read into memory.
 *
 * @param {string} filePath  Path resolved via _internals at call time.
 */
function readKeyNames(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  const lines   = _internals.parseEnvLines(content);
  const names   = new Set(
    lines
      .filter((l) => l.type === 'entry')
      .map((l) => l.name)
  );
  return names;
}

/**
 * Generate a new placeholder key string for a given key name.
 *
 * Format encodes:
 *   - a prefix derived from the key name (so placeholders are distinguishable)
 *   - a timestamp token (seconds-level, not full ISO to keep it compact)
 *   - 16 random hex bytes for uniqueness
 *
 * In a production system this function would call the upstream provider's
 * credential-rotation API inside a secrets manager and return the new key
 * that was provisioned there.  The placeholder returned here makes the
 * rotation mechanism fully testable without live credentials.
 */
function generatePlaceholder(keyName) {
  const randomHex = crypto.randomBytes(16).toString('hex');
  const tsToken   = Math.floor(Date.now() / 1000).toString(36); // base-36 epoch secs
  const prefix    = keyName.toLowerCase().replace(/_/g, '-');
  return `ROTATED-${prefix}-${tsToken}-${randomHex}`;
}

/**
 * Append a rotation event to rotation-log.json.
 * Only keyName and metadata are recorded — NEVER any key value.
 *
 * Path is resolved through _internals.LOG_FILE at call time so tests can
 * redirect it.
 */
function appendRotationLog(keyName, status, detail) {
  // Resolve path at call-time (not at module load time) so test overrides work.
  const logFile = _internals.LOG_FILE;

  let log = [];

  // Load existing log entries if the file already exists.
  if (fs.existsSync(logFile)) {
    try {
      const raw    = fs.readFileSync(logFile, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        log = parsed;
      }
    } catch {
      // Corrupted log — start fresh rather than crash the rotation.
      log = [];
    }
  }

  const entry = {
    timestamp : new Date().toISOString(),
    keyName,           // ← only the NAME, not the value
    status,            // 'success' | 'error'
    detail : detail ?? null,
  };

  log.push(entry);

  fs.writeFileSync(logFile, JSON.stringify(log, null, 2) + '\n', 'utf8');
}

// ─── Public API ───────────────────────────────────────────────────────────────

/**
 * Read the current set of rotateable key NAMES from .env.test.
 *
 * Returns a Set<string> containing only the names that are both:
 *   (a) present in .env.test, and
 *   (b) listed in ROTATEABLE_KEYS.
 *
 * Key values are never exposed.
 */
function getSupportedRotateableKeys() {
  // Resolve path at call-time so test overrides work.
  const presentNames = readKeyNames(_internals.ENV_FILE);
  const supported    = new Set(
    [..._internals.ROTATEABLE_KEYS].filter((name) => presentNames.has(name))
  );
  return supported;
}

/**
 * Rotate the specified key in .env.test.
 *
 * Steps:
 *   1. Validate that keyName is in ROTATEABLE_KEYS.
 *   2. Read .env.test line-by-line (values never stored).
 *   3. Replace the matching KEY=<value> line with KEY=<new-placeholder>.
 *   4. Write the updated content to .env.test.tmp.
 *   5. Atomically rename .env.test.tmp → .env.test.
 *   6. Log the event (key name + timestamp only) to rotation-log.json.
 *
 * @param {string} keyName  The environment variable name to rotate.
 * @returns {{ success: boolean, keyName: string, timestamp: string }}
 */
function rotateKey(keyName) {
  // ── 1. Validate ────────────────────────────────────────────────────────────
  if (typeof keyName !== 'string' || keyName.trim() === '') {
    throw new TypeError('rotateKey: keyName must be a non-empty string.');
  }

  if (!_internals.ROTATEABLE_KEYS.has(keyName)) {
    const allowed = [..._internals.ROTATEABLE_KEYS].join(', ');
    throw new Error(
      `rotateKey: "${keyName}" is not in the supported rotation set. ` +
      `Allowed keys: ${allowed}`
    );
  }

  // Resolve paths at call-time so test overrides work.
  const envFile    = _internals.ENV_FILE;
  const envTmpFile = _internals.ENV_TMP_FILE;

  // ── 2. Read env file ───────────────────────────────────────────────────────
  let fileContent;
  try {
    fileContent = fs.readFileSync(envFile, 'utf8');
  } catch (err) {
    _internals.appendRotationLog(
      keyName, 'error', `Could not read ${envFile}: ${err.message}`
    );
    throw new Error(`rotateKey: failed to read env file — ${err.message}`);
  }

  const lines = _internals.parseEnvLines(fileContent);

  // Check the key actually exists in the file.
  const targetLine = lines.find((l) => l.type === 'entry' && l.name === keyName);
  if (!targetLine) {
    const msg = `Key "${keyName}" not found in ${envFile}.`;
    _internals.appendRotationLog(keyName, 'error', msg);
    throw new Error(`rotateKey: ${msg}`);
  }

  // ── 3. Build updated file content ──────────────────────────────────────────
  // Generate a placeholder BEFORE building the new content so that if
  // generatePlaceholder() throws, we haven't touched any file yet.
  const newPlaceholder = _internals.generatePlaceholder(keyName);

  const updatedLines = lines.map((l) => {
    if (l.type === 'entry' && l.name === keyName) {
      // Replace only the value portion — preserve the key name exactly.
      return `${l.name}=${newPlaceholder}`;
    }
    return l.rawLine;
  });

  const updatedContent = updatedLines.join('\n');

  // ── 4. Write to .env.test.tmp ──────────────────────────────────────────────
  try {
    fs.writeFileSync(envTmpFile, updatedContent, { encoding: 'utf8', flag: 'w' });
  } catch (err) {
    // Clean up the tmp file if it was partially written.
    try { fs.unlinkSync(envTmpFile); } catch { /* ignore */ }
    _internals.appendRotationLog(
      keyName, 'error', `Failed to write tmp file: ${err.message}`
    );
    throw new Error(`rotateKey: failed to write tmp file — ${err.message}`);
  }

  // ── 5. Atomic rename .env.test.tmp → .env.test ────────────────────────────
  try {
    fs.renameSync(envTmpFile, envFile);
  } catch (err) {
    // Leave the tmp file in place for diagnosis; do not corrupt the original.
    _internals.appendRotationLog(
      keyName, 'error', `Atomic rename failed: ${err.message}`
    );
    throw new Error(`rotateKey: atomic rename failed — ${err.message}`);
  }

  // ── 6. Log the rotation event (no value, ever) ────────────────────────────
  const timestamp = new Date().toISOString();
  _internals.appendRotationLog(keyName, 'success', null);

  console.log(`[key-rotation] Rotated "${keyName}" at ${timestamp}`);

  return { success: true, keyName, timestamp };
}

// ─── Module exports ───────────────────────────────────────────────────────────

module.exports = {
  rotateKey,
  getSupportedRotateableKeys,
  // Exported for unit-testing only — not part of the public rotation API.
  _internals,
};

