'use strict';

/**
 * key-rotation.js
 *
 * API key rotation mechanism.
 *
 * Security contract (enforced throughout):
 *  - Actual key VALUES are NEVER logged, stored in the audit log, or
 *    written to any destination other than .env.test itself.
 *  - rotation-log.json records only: timestamp, keyName, and a status.
 *  - .env.test is updated atomically: written to .env.test.tmp first,
 *    then fs.renameSync() replaces the live file in one syscall so that
 *    no reader ever sees a partially-written file.
 */

const fs   = require('fs');
const path = require('path');
const crypto = require('crypto');

// ─── Path constants ────────────────────────────────────────────────────────────

const ENV_FILE     = path.resolve(__dirname, '.env.test');
const ENV_TMP_FILE = path.resolve(__dirname, '.env.test.tmp');
const LOG_FILE     = path.resolve(__dirname, 'rotation-log.json');

// ─── Keys that this module is authorised to rotate ────────────────────────────
// Populated at start-up by readRotatableKeyNames(); never contains values.

let ROTATABLE_KEY_NAMES = [];

// ─── 1. Read variable NAMES from .env.test ────────────────────────────────────

/**
 * Parse .env.test and return only the names of ANTHROPIC_API_KEY and
 * STRIPE_SECRET_KEY if they are present.
 *
 * Why only names?
 *   The function intentionally discards the right-hand side of every
 *   assignment so that values cannot accidentally be captured in a
 *   closure, a log line, or a returned object.
 *
 * @returns {string[]} Array of key names found in the file.
 */
function readRotatableKeyNames() {
  const SUPPORTED_KEYS = ['ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];

  const raw = fs.readFileSync(ENV_FILE, 'utf8');

  const foundNames = [];
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    // Skip comments and blank lines
    if (!trimmed || trimmed.startsWith('#')) continue;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) continue;

    const name = trimmed.slice(0, eqIdx).trim();
    if (SUPPORTED_KEYS.includes(name)) {
      foundNames.push(name);
    }
    // The value (trimmed.slice(eqIdx + 1)) is intentionally ignored here.
  }

  return foundNames;
}

// ─── 2. Placeholder generator ─────────────────────────────────────────────────

/**
 * Generate a cryptographically random placeholder string that is safe to
 * store in .env.test as a stand-in for a real key.
 *
 * Format:  ROTATED-<keyName>-<hex32>
 *
 * The placeholder is NOT a real credential; it signals that a rotation
 * occurred and lets tests verify the field was updated.
 *
 * @param {string} keyName - The environment variable name being rotated.
 * @returns {string} New placeholder value.
 */
function generatePlaceholder(keyName) {
  // 16 bytes → 32 hex characters; collision probability is negligible.
  const rand = crypto.randomBytes(16).toString('hex');
  return `ROTATED-${keyName}-${rand}`;
}

// ─── 3. Atomic .env.test update ───────────────────────────────────────────────

/**
 * Replace the value of `keyName` inside .env.test using an atomic
 * write-then-rename pattern:
 *
 *   1. Read the current file content.
 *   2. Substitute only the target line.
 *   3. Write the result to .env.test.tmp.
 *   4. Rename .env.test.tmp → .env.test  (atomic on POSIX filesystems).
 *
 * If anything goes wrong after step 3 but before step 4 the original
 * file is untouched; .env.test.tmp is cleaned up on the next run.
 *
 * @param {string} keyName     - The env var name whose value is replaced.
 * @param {string} placeholder - The new value to write.
 */
function atomicUpdateEnvFile(keyName, placeholder) {
  const raw = fs.readFileSync(ENV_FILE, 'utf8');

  let replaced = false;
  const updatedLines = raw.split('\n').map(line => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return line;

    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) return line;

    const name = trimmed.slice(0, eqIdx).trim();
    if (name === keyName) {
      replaced = true;
      // Preserve any leading whitespace the original line had, but replace
      // everything after the '=' with the new placeholder.
      const leadingSpace = line.match(/^(\s*)/)[1];
      return `${leadingSpace}${keyName}=${placeholder}`;
    }
    return line;
  });

  if (!replaced) {
    throw new Error(
      `Key "${keyName}" was not found in ${ENV_FILE}. ` +
      'Cannot perform atomic update.'
    );
  }

  const updatedContent = updatedLines.join('\n');

  // Write to temp file first — if this crashes, the original is safe.
  fs.writeFileSync(ENV_TMP_FILE, updatedContent, { encoding: 'utf8', flag: 'w' });

  // Atomic rename: on POSIX this is a single syscall; readers see either
  // the old file or the new file, never a partial state.
  fs.renameSync(ENV_TMP_FILE, ENV_FILE);
}

// ─── 4. Audit logger ──────────────────────────────────────────────────────────

/**
 * Append one rotation event to rotation-log.json.
 *
 * The log entry contains ONLY:
 *   - timestamp  : ISO-8601 wall-clock time of the rotation
 *   - keyName    : the environment variable NAME (e.g. "ANTHROPIC_API_KEY")
 *   - status     : "success" | "failure"
 *   - error      : (only on failure) a sanitised error message
 *
 * Key VALUES are never written to this file.
 *
 * The file is maintained as a JSON array so it is easy to parse
 * programmatically; entries are appended without loading the entire
 * history into memory via a read-append-write cycle on the array.
 *
 * @param {string}      keyName - The env var name that was rotated.
 * @param {"success"|"failure"} status
 * @param {Error|null}  [err]   - Provide on failure; message is sanitised.
 */
function appendRotationLog(keyName, status, err = null) {
  /** @type {Record<string, unknown>} */
  const entry = {
    timestamp: new Date().toISOString(),
    keyName,   // Only the NAME — value is intentionally absent
    status,
  };

  if (status === 'failure' && err instanceof Error) {
    // Strip any accidental key values that might appear in the error message
    // by removing anything that looks like a long alphanumeric token (>= 20
    // chars) — a conservative safeguard against accidental value leakage.
    entry.error = err.message.replace(/[A-Za-z0-9_\-]{20,}/g, '[REDACTED]');
  }

  // Read existing log (or start fresh).
  let entries = [];
  if (fs.existsSync(LOG_FILE)) {
    try {
      const raw = fs.readFileSync(LOG_FILE, 'utf8');
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        entries = parsed;
      }
    } catch {
      // Corrupted log — start a new array rather than crashing.
      entries = [];
    }
  }

  entries.push(entry);

  // Overwrite with the updated array; this is the only write to this file.
  fs.writeFileSync(LOG_FILE, JSON.stringify(entries, null, 2), 'utf8');
}

// ─── 5. Public API ────────────────────────────────────────────────────────────

/**
 * Rotate the placeholder value for a single key in .env.test.
 *
 * Steps:
 *  1. Validate that `keyName` is one of the keys discovered at load time.
 *  2. Generate a fresh random placeholder (no real credential is involved).
 *  3. Atomically rewrite .env.test with the new placeholder value.
 *  4. Append a success (or failure) event to rotation-log.json.
 *
 * @param {string} keyName - Must be one of the names in ROTATABLE_KEY_NAMES.
 * @throws {Error} If keyName is unknown or file operations fail.
 */
function rotateKey(keyName) {
  // Guard: only rotate keys that were explicitly discovered in .env.test
  if (!ROTATABLE_KEY_NAMES.includes(keyName)) {
    const err = new Error(
      `"${keyName}" is not a rotatable key. ` +
      `Known rotatable keys: [${ROTATABLE_KEY_NAMES.join(', ')}]`
    );
    // Log the failed attempt before throwing
    appendRotationLog(keyName, 'failure', err);
    throw err;
  }

  try {
    const placeholder = generatePlaceholder(keyName);

    // Atomically update the file — value is written here and nowhere else
    atomicUpdateEnvFile(keyName, placeholder);

    // Log success: key NAME only, never the placeholder value
    appendRotationLog(keyName, 'success');

    console.log(
      `[key-rotation] ${new Date().toISOString()} ` +
      `Rotated key: ${keyName} — new placeholder written to ${ENV_FILE}`
    );
  } catch (err) {
    appendRotationLog(keyName, 'failure', err);
    // Clean up any leftover temp file so it doesn't confuse the next run
    try { fs.unlinkSync(ENV_TMP_FILE); } catch { /* already gone */ }
    throw err;
  }
}

// ─── Module initialisation ────────────────────────────────────────────────────

// Discover which of the supported key names actually exist in the file.
// This happens once at require() time so that every rotateKey() call
// benefits from the same pre-validated set.
ROTATABLE_KEY_NAMES = readRotatableKeyNames();

if (ROTATABLE_KEY_NAMES.length === 0) {
  console.warn(
    '[key-rotation] Warning: No rotatable keys (ANTHROPIC_API_KEY, ' +
    'STRIPE_SECRET_KEY) were found in ' + ENV_FILE
  );
} else {
  console.log(
    '[key-rotation] Rotatable keys discovered: ' +
    ROTATABLE_KEY_NAMES.join(', ')
  );
}

// ─── Exports ──────────────────────────────────────────────────────────────────

module.exports = {
  rotateKey,
  /**
   * Returns a copy of the discovered key names (no values).
   * Useful for callers that want to enumerate which keys are managed.
   */
  getRotatableKeyNames: () => [...ROTATABLE_KEY_NAMES],
};

